# in-process reload suggestion on cutover-active runs. An in-process reload
# leaves the host on mixed-version lifecycle code across the cutover boundary.






INDEX_GUARD_RESPONSE_VERSION = 1






def wf_run_sensors_response(root: Path) -> dict[str, Any]:
    """Run registered project sensors and return structured pass/fail results.

    Sensors are defined in ``docs/workflow-config.json`` under the ``sensors`` key.
    Each sensor entry must have ``name`` and ``command`` fields; ``dimension`` and
    ``description`` are optional.  Commands are run in a subprocess with ``cwd=root``.
    Results include per-sensor pass/fail, exit code, and stdout/stderr summary.
    """
    sensors = _read_project_sensors(root)
    if not sensors:
        return _response(
            "ok",
            {"sensors_run": 0, "results": [], "all_passed": True, "notice": "No sensors registered in workflow-config.json."},
            next_tools=["wf_audit"], usage="wf_audit()",
        )
    timeout_seconds = subprocess_ops_timeout_seconds(root, "sensor", default=120)
    results = [sensor_runner.run_sensor(
        root, sensor, timeout_seconds=timeout_seconds,
        shell=not isinstance(sensor["command"], list),
    ) for sensor in sensors]
    all_passed = all(result["passed"] for result in results)

    diagnostics = []
    if not all_passed:
        failed = [r["name"] for r in results if not r["passed"]]
        diagnostics.append(_diagnostic(
            "sensor_failed",
            f"Sensor(s) failed: {', '.join(failed)}. Address failures before declaring done.",
            recovery_tools=["wf_run_sensors"],
            recovery_usage="wf_run_sensors()",
        ))
    return _response(
        "ok" if all_passed else "error",
        {"sensors_run": len(results), "results": results, "all_passed": all_passed},
        diagnostics=diagnostics,
        next_tools=["wf_audit"] if all_passed else ["wf_run_sensors"],
        usage="wf_audit()" if all_passed else "wf_run_sensors()",
    )




# ---------------------------------------------------------------------------
# Audit helpers: commit governance, harnessability, harness coverage, coherence
# ---------------------------------------------------------------------------

def _audit_commit_governance(root: Path) -> dict[str, Any]:
    """Scan recent git commits and classify as governed or unassociated."""
    cfg = _read_workflow_config(root)
    governance_cfg = cfg.get("commit_governance", {})
    window_days = int(governance_cfg.get("window_days", 30)) if isinstance(governance_cfg, dict) else 30
    exclusion_patterns = governance_cfg.get("exclusion_patterns", []) if isinstance(governance_cfg, dict) else []
    if not isinstance(exclusion_patterns, list):
        exclusion_patterns = []

    try:
        # Route through the shared helper so this MCP-reachable git probe never inherits the
        # JSON-RPC stdin and shows no console window on Windows (wave 1p88t subprocess isolation).
        result = _mcp_subprocess_run(
            ["git", "log", f"--since={window_days} days ago", "--pretty=format:%h %s"],
            cwd=str(root), timeout=15,
        )
        if result.returncode != 0:
            return {"available": False, "reason": "git log failed"}
        lines = [l.strip() for l in result.stdout.splitlines() if l.strip()]
    except Exception:
        return {"available": False, "reason": "git unavailable"}

    # Collect known wave/change ID prefixes from the waves root
    known_ids: set[str] = set()
    if record_paths.load_record_roots(root).waves.is_dir():
        for entry in record_paths.walk_wave_candidates(root):
            if entry.is_dir():
                # wave-id prefix like "12ecs"
                parts = entry.name.split(" ", 1)
                if parts:
                    known_ids.add(parts[0].lower())
                for f in entry.iterdir():
                    if f.suffix == ".md" and "-" in f.stem:
                        # change-id like "12ecs-feat"
                        cid = f.stem.split(" ")[0].lower()
                        known_ids.add(cid)

    governed, unassociated, excluded = [], [], []
    for line in lines:
        parts = line.split(" ", 1)
        sha = parts[0]
        msg = parts[1] if len(parts) > 1 else ""
        msg_lower = msg.lower()
        # Check exclusion patterns first
        if any(msg_lower.startswith(pat.lower()) or pat.lower() in msg_lower for pat in exclusion_patterns):
            excluded.append({"sha": sha, "message": msg})
            continue
        # Check association with known wave/change IDs
        associated = any(kid in msg_lower for kid in known_ids)
        if associated:
            governed.append({"sha": sha, "message": msg})
        else:
            unassociated.append({"sha": sha, "message": msg})

    return {
        "available": True,
        "window_days": window_days,
        "governed": governed,
        "unassociated": unassociated,
        "excluded": excluded,
        "governed_count": len(governed),
        "unassociated_count": len(unassociated),
    }


# Wave 1p35d (1p35p enterprise-deployment review): directories the JVM source-
# pattern fallback skips when walking canonical roots. Enterprise monorepos
# routinely vendor 3rd-party code, archive legacy implementations, or commit
# build-tool caches that contain matching source-file extensions; without this
# allowlist the heuristic would false-positive on any of them.
_JVM_SOURCE_WALK_IGNORE_DIRS: frozenset[str] = frozenset({
    "node_modules", "vendor", "third_party", "third-party", "thirdparty",
    "target", "build", "dist", "out", "bin", "obj",
    ".git", ".gradle", ".mvn", ".idea", ".vscode", ".settings",
    "__pycache__", ".pytest_cache", ".mypy_cache", ".ruff_cache", ".tox",
})

# Canonical JVM project root layouts in priority order. Maven/Gradle conventional
# layouts are checked first (highest specificity); src/ / app/ / lib/ are common
# unconventional fallbacks; root iterdir handles tiny single-file projects.
_JVM_CANONICAL_SOURCE_ROOTS = (
    ("src/main/java", True),
    ("src/main/kotlin", True),
    ("src/main/scala", True),
    ("src/main/groovy", True),
    ("src", True),
    ("app", True),
    ("lib", True),
    ("", False),  # top-level iterdir only — no recursive walk
)
_JVM_SOURCE_PATTERNS: frozenset[str] = frozenset({".java", ".kt", ".scala", ".groovy"})
_JVM_SOURCE_WALK_FILE_BUDGET = 5000  # bail after N files examined; guards against pathological monorepo walks


def _detect_jvm_source_evidence(root: Path) -> list[str]:
    """Return the first JVM source-pattern signal found in canonical project roots.

    Returns a single-element list (e.g. ``["*.java"]``) when a JVM source file
    is found in a canonical location, empty list otherwise. Walks bounded by
    ``_JVM_SOURCE_WALK_IGNORE_DIRS`` (skips vendored/build/archive dirs) and
    by ``_JVM_SOURCE_WALK_FILE_BUDGET`` (caps work on pathological monorepos).
    """
    files_examined = 0
    for rel, recurse in _JVM_CANONICAL_SOURCE_ROOTS:
        src_root = root / rel if rel else root
        if not src_root.is_dir():
            continue
        if recurse:
            try:
                stack = [src_root]
                while stack:
                    if files_examined >= _JVM_SOURCE_WALK_FILE_BUDGET:
                        return []
                    current = stack.pop()
                    try:
                        entries = list(current.iterdir())
                    except OSError:
                        continue
                    for entry in entries:
                        if files_examined >= _JVM_SOURCE_WALK_FILE_BUDGET:
                            return []
                        if entry.is_dir():
                            if entry.name in _JVM_SOURCE_WALK_IGNORE_DIRS:
                                continue
                            stack.append(entry)
                            continue
                        if entry.is_file():
                            files_examined += 1
                            if entry.suffix in _JVM_SOURCE_PATTERNS:
                                return [f"*{entry.suffix}"]
            except OSError:
                continue
        else:
            # Top-level iterdir only — files directly at repo root.
            try:
                for entry in src_root.iterdir():
                    if entry.is_file() and entry.suffix in _JVM_SOURCE_PATTERNS:
                        return [f"*{entry.suffix}"]
            except OSError:
                continue
    return []


# Wave 1p35d (1p35p enterprise-deployment hardening, monorepo detection):
# workspace-marker files signal the operator-CWD is a monorepo parent rather
# than a single project. When present, harnessability checks aggregate signals
# across sub-projects instead of returning a misleading "no config" answer
# based only on the parent dir.
_MONOREPO_MARKER_FILES: tuple[str, ...] = (
    "nx.json",
    "lerna.json",
    "rush.json",
    "pnpm-workspace.yaml",
    "WORKSPACE",          # Bazel
    "WORKSPACE.bazel",
    "MODULE.bazel",
    "pants.toml",         # Pants
    ".buckconfig",        # Buck/Buck2
    "BUCK",
)

# Canonical sub-project parent dirs in monorepo layouts. The walk goes one
# level deep into each — `services/auth-service/` is a sub-project; deeper
# nesting (`services/auth-service/src/main/java/.../`) is left to the per-
# sub-project type-coverage check.
_MONOREPO_SUBPROJECT_PARENTS: tuple[str, ...] = (
    "services",
    "apps",
    "libs",
    "packages",
    "crates",
    "modules",
    "subprojects",
    "components",
    "projects",
)

# Per-sub-project type-config file markers. Each entry: (filename, label-on-evidence).
_SUBPROJECT_TYPE_CONFIG_FILES: tuple[tuple[str, str], ...] = (
    ("tsconfig.json", "tsconfig.json"),
    ("mypy.ini", "mypy.ini"),
    ("pyrightconfig.json", "pyrightconfig.json"),
    (".pyrightconfig.json", ".pyrightconfig.json"),
    ("pom.xml", "pom.xml"),
    ("build.gradle", "build.gradle"),
    ("build.gradle.kts", "build.gradle.kts"),
    ("settings.gradle", "settings.gradle"),
    ("settings.gradle.kts", "settings.gradle.kts"),
    ("Cargo.toml", "Cargo.toml"),
    ("go.mod", "go.mod"),
)

_MONOREPO_SUBPROJECT_BUDGET = 100  # cap sub-projects examined per call


def _detect_monorepo_subprojects(root: Path) -> list[Path]:
    """Return paths of likely sub-project roots when `root` looks like a monorepo.

    Returns empty list when no monorepo workspace marker is found at root —
    callers fall through to single-project behavior. When a marker IS found,
    walks `_MONOREPO_SUBPROJECT_PARENTS` one level deep collecting sub-project
    candidate dirs, skipping `_JVM_SOURCE_WALK_IGNORE_DIRS` and bounded by
    `_MONOREPO_SUBPROJECT_BUDGET`.

    Recognized markers:
    - Direct: nx.json, lerna.json, pnpm-workspace.yaml, rush.json, Bazel
      WORKSPACE files, Pants pants.toml, Buck .buckconfig
    - package.json with a top-level "workspaces" field (npm/yarn workspaces)
    - Cargo.toml with a top-level [workspace] section (Cargo workspaces)
    - pom.xml with packaging=pom (Maven multi-module parent)
    """
    has_monorepo_marker = False

    for marker in _MONOREPO_MARKER_FILES:
        if (root / marker).exists():
            has_monorepo_marker = True
            break

    if not has_monorepo_marker:
        # Inspect package.json for `"workspaces"` field
        pkg_json = root / "package.json"
        if pkg_json.is_file():
            try:
                data = __import__("json").loads(pkg_json.read_text(encoding="utf-8"))
                if isinstance(data, dict) and "workspaces" in data:
                    has_monorepo_marker = True
            except (OSError, ValueError):
                pass

    if not has_monorepo_marker:
        # Inspect Cargo.toml for `[workspace]` section
        cargo_toml = root / "Cargo.toml"
        if cargo_toml.is_file():
            try:
                if "[workspace]" in cargo_toml.read_text(encoding="utf-8"):
                    has_monorepo_marker = True
            except OSError:
                pass

    if not has_monorepo_marker:
        # Inspect pom.xml for multi-module marker — `<packaging>pom</packaging>`
        # plus a `<modules>` section is the canonical Maven multi-module shape.
        pom_xml = root / "pom.xml"
        if pom_xml.is_file():
            try:
                txt = pom_xml.read_text(encoding="utf-8")
                if "<packaging>pom</packaging>" in txt and "<modules>" in txt:
                    has_monorepo_marker = True
            except OSError:
                pass

    if not has_monorepo_marker:
        return []

    found: list[Path] = []
    for parent_name in _MONOREPO_SUBPROJECT_PARENTS:
        parent = root / parent_name
        if not parent.is_dir():
            continue
        try:
            for entry in sorted(parent.iterdir()):
                if not entry.is_dir():
                    continue
                if entry.name in _JVM_SOURCE_WALK_IGNORE_DIRS:
                    continue
                if entry.name.startswith("."):
                    continue
                found.append(entry)
                if len(found) >= _MONOREPO_SUBPROJECT_BUDGET:
                    return found
        except OSError:
            continue
    return found


def _collect_subproject_type_evidence(subprojects: list[Path]) -> list[str]:
    """For each sub-project, return the first type-config file found, prefixed
    with the sub-project's parent/name. Used by the harnessability type-coverage
    check to aggregate signals across a monorepo."""
    evidence: list[str] = []
    for sub in subprojects:
        # Check each type-config file in priority order — first match wins.
        for filename, label in _SUBPROJECT_TYPE_CONFIG_FILES:
            if (sub / filename).exists():
                # `services/auth-service/pom.xml` rather than just `pom.xml`
                rel_label = f"{sub.parent.name}/{sub.name}/{label}"
                evidence.append(rel_label)
                break
        else:
            # No standard build/type file at sub-project root — check for
            # JVM source-pattern fallback within this sub-project.
            jvm_sub = _detect_jvm_source_evidence(sub)
            if jvm_sub:
                rel_label = f"{sub.parent.name}/{sub.name}/{jvm_sub[0]}"
                evidence.append(rel_label)
    return evidence


def _audit_harnessability(root: Path) -> dict[str, Any]:
    """Assess codebase harnessability across three proxy dimensions."""
    # --- Type coverage ---
    type_score = "unknown"
    type_evidence = ""
    typed_configs = []
    for cfg_file in ["tsconfig.json", "mypy.ini", "pyrightconfig.json", ".pyrightconfig.json"]:
        if (root / cfg_file).exists():
            typed_configs.append(cfg_file)
    pyproject = root / "pyproject.toml"
    if pyproject.exists():
        try:
            text = pyproject.read_text(encoding="utf-8")
            if "strict" in text or "disallow_untyped" in text or "mypy" in text:
                typed_configs.append("pyproject.toml (typed)")
        except OSError:
            pass
    # Wave 1p35d (1p35p): JVM build/source detection. Spring Boot and other
    # JVM-ecosystem projects previously read as "no type config detected"
    # because the checker only looked for TS/Python config. Lightweight
    # file-presence check — no compiler invocation, no JVM runtime dependency.
    #
    # Late hardening (1p35p enterprise-deployment review): the previous
    # `root.rglob(*.java)` walked the entire repo, slow on enterprise
    # monorepos and false-positive on any vendored 3rd-party Java sources
    # anywhere in the tree. Scoped to canonical project roots and source
    # patterns are *.{java,kt,scala,groovy}.
    jvm_signals = []
    for build_file in ("pom.xml", "build.gradle", "build.gradle.kts",
                       "settings.gradle", "settings.gradle.kts"):
        if (root / build_file).exists():
            jvm_signals.append(build_file)
    if not jvm_signals:
        jvm_signals.extend(_detect_jvm_source_evidence(root))
    if jvm_signals:
        typed_configs.append(f"JVM ({', '.join(jvm_signals)})")
    # Wave 1p35d (1p35p enterprise-deployment hardening, monorepo support):
    # when the agent's CWD is a monorepo workspace parent (Nx/Lerna/pnpm/
    # Bazel/Pants/Cargo-workspaces/Maven-multi-module etc.), the root-only
    # checks above miss type-config that lives inside sub-project dirs.
    # Aggregate sub-project signals so the harnessability score reflects the
    # actual typed surface, not just what happens to live at the workspace
    # root.
    subprojects = _detect_monorepo_subprojects(root)
    if subprojects:
        subproject_evidence = _collect_subproject_type_evidence(subprojects)
        if subproject_evidence:
            # Report at most 5 sub-projects inline; trailing "+N more" when
            # the monorepo has many typed sub-projects.
            shown = subproject_evidence[:5]
            extra = len(subproject_evidence) - len(shown)
            label = f"monorepo ({len(subprojects)} sub-projects scanned, "
            label += f"{len(subproject_evidence)} typed): {', '.join(shown)}"
            if extra > 0:
                label += f", +{extra} more"
            typed_configs.append(label)
    if typed_configs:
        type_score = "high" if len(typed_configs) >= 2 else "medium"
        type_evidence = f"Type config found: {', '.join(typed_configs)}"
    else:
        type_score = "low"
        type_evidence = "No type configuration files detected"

    # --- Module boundary clarity ---
    boundary_score = "unknown"
    boundary_evidence = ""
    arch_dir = root / "docs" / "architecture"
    boundary_docs = []
    for name in ["domain-map.md", "layering-rules.md", "current-state.md"]:
        if (arch_dir / name).exists():
            boundary_docs.append(name)
    if len(boundary_docs) >= 2:
        boundary_score = "high"
    elif boundary_docs:
        boundary_score = "medium"
    else:
        boundary_score = "low"
    boundary_evidence = f"Architecture docs found: {', '.join(boundary_docs)}" if boundary_docs else "No architecture boundary docs found"

    # --- Debt density proxy ---
    debt_score = "unknown"
    debt_evidence = ""
    try:
        # Route through the shared helper (MCP-reachable git probe): no inherited JSON-RPC stdin,
        # no Windows console window (wave 1p88t subprocess isolation).
        result = _mcp_subprocess_run(
            ["git", "grep", "-c", "-E", "TODO|FIXME|HACK|XXX"],
            cwd=str(root), timeout=10,
        )
        todo_count = sum(int(l.split(":")[-1]) for l in result.stdout.splitlines() if ":" in l and l.split(":")[-1].isdigit())
        if todo_count == 0:
            debt_score = "high"
        elif todo_count < 20:
            debt_score = "medium"
        else:
            debt_score = "low"
        debt_evidence = f"{todo_count} TODO/FIXME/HACK markers found"
    except Exception:
        debt_score = "unknown"
        debt_evidence = "Could not scan for debt markers"

    scores = {"high": 3, "medium": 2, "low": 1, "unknown": 0}
    dims = [type_score, boundary_score, debt_score]
    known = [s for s in dims if s != "unknown"]
    if known:
        avg = sum(scores[s] for s in known) / len(known)
        overall = "high" if avg >= 2.5 else "medium" if avg >= 1.5 else "low"
    else:
        overall = "unknown"

    return {
        "overall": overall,
        "dimensions": {
            "type_coverage": {"score": type_score, "evidence": type_evidence},
            "boundary_clarity": {"score": boundary_score, "evidence": boundary_evidence},
            "debt_density": {"score": debt_score, "evidence": debt_evidence},
        },
    }


def _audit_harness_coverage(root: Path) -> dict[str, Any]:
    """Report which harness dimensions have at least one sensor configured."""
    cfg = _read_workflow_config(root)
    sensors = _read_project_sensors(root)
    required_lanes = _read_project_required_review_lanes(root)
    lanes_lower = [l.lower() for l in required_lanes]

    maintainability_covered = len(sensors) > 0
    architecture_covered = any("architecture" in l for l in lanes_lower)
    behaviour_covered = (
        any(l in ("security", "security-review", "performance", "performance-review") for l in lanes_lower)
        or bool(cfg.get("test_runner"))
    )

    dimensions = {
        "maintainability": {"covered": maintainability_covered, "signal": "computational sensors" if maintainability_covered else None},
        "architecture": {"covered": architecture_covered, "signal": "architecture-review lane" if architecture_covered else None},
        "behaviour": {"covered": behaviour_covered, "signal": "security/performance lanes or test_runner" if behaviour_covered else None},
    }
    covered_count = sum(1 for d in dimensions.values() if d["covered"])
    return {
        "coverage_ratio": f"{covered_count}/3",
        "covered_count": covered_count,
        "dimensions": dimensions,
    }


def _audit_harness_coherence(root: Path) -> dict[str, Any]:
    """Scan seed surface for stale tool references and known contradiction patterns.

    Wave 1p2q3 (1p314 post-ship): tightened detection logic after a 52-finding
    audit on the wavefoundry self-host turned out to be 28+ false positives.
    Fixes:

    1. Scan ``server.py`` in addition to ``server_impl.py`` — ``wf_reload_mcp``
       is defined in the thin runner because it must survive hot-reload.
    2. Treat top-level keys of ``docs/workflow-config.json`` as legitimate
       identifiers — ``code_navigation_hints`` etc. are config blocks, not tools.
    3. Skip parameter-position matches: ``wf_pause_wave(wave_id=...)``, URI
       template variables like ``{wave_id}``, briefing-packet field lists.
    4. Skip wildcard family references: ``wf_new_*`` is the canonical
       reference form for the kind-specific ``wf_new_X`` tool family.
    5. Bypass-pattern detection removed entirely — keyword co-occurrence
       (skip/bypass/omit + gate/lane) is too broad. Every match in the
       wavefoundry self-host was legitimate prose (red-team role descriptions,
       explicit safeguards against bypass, anti-pattern callouts). The signal-
       to-noise ratio doesn't justify keeping it; a future NLP-aware version
       could re-enable.
    """
    seed_dirs = [
        root / ".wavefoundry" / "framework" / "seeds",
        root / "docs" / "prompts",
    ]
    # Collect live MCP tool names from BOTH server modules. server.py defines
    # tools that must survive hot-reload (notably wf_reload_mcp itself);
    # server_impl.py defines the rest of the surface.
    live_tools: set[str] = set()
    try:
        import re as _re
        # server.py stays at the scripts root; this module's own source is the
        # package file (the flat server_impl.py is only an alias and defines no tool).
        for src_path in (SCRIPTS_DIR / "server.py", Path(__file__).resolve()):
            if not src_path.is_file():
                continue
            src = src_path.read_text(encoding="utf-8")
            live_tools.update(
                _re.findall(r'def (wf_\w+|memory_\w+|index_\w+|docs_search|code_\w+|seed_get)\(', src)
            )
    except Exception:
        pass

    # Treat top-level workflow-config keys as legitimate identifiers — they're
    # project-tunable schema blocks (e.g. code_navigation_hints,
    # design_review_triggers), not tool names. Without this allowlist the
    # audit flags them as "stale tool reference" when they're actually live
    # config.
    workflow_config_keys: set[str] = set()
    try:
        import json as _json_wf
        wf_path = root / "docs" / "workflow-config.json"
        if wf_path.is_file():
            wf_data = _json_wf.loads(wf_path.read_text(encoding="utf-8"))
            if isinstance(wf_data, dict):
                workflow_config_keys = {k for k in wf_data if isinstance(k, str)}
    except Exception:
        pass

    # Known non-tool identifiers that match the tool-name regex shape but
    # legitimately appear as parameter/field/URI/module names. Without this
    # allowlist they get over-matched.
    NON_TOOL_IDENTIFIERS = {
        "wave_id",        # parameter name in wf_pause_wave/wf_reopen_wave, URI {wave_id}, briefing field
        "wave_lint_lib",  # Python module under framework/scripts/wave_lint_lib/
        # 1u8o2 (1u8o1): Python module wf_cli.py; every seed mention is
        # already module-path form (`wf_cli.py`) and the regex substring-
        # matches the stem, so a seed rewrite cannot silence it; the checker
        # must know the module name (the wave_lint_lib precedent).
        "wf_cli",
    }

    # 1u8o2 (1u8o1): retired tool names that seed MIGRATION text must keep
    # using by design (upgrade instructions and verification checklists tell
    # agents to replace the OLD name; deleting it from the text would break
    # the migration). Both retired gate names are covered symmetrically:
    # `wf_close_wave_gate` previously escaped only via the legacy
    # `wf_close_wave_gate_response` shim still existing, so removing that shim
    # would have minted new findings overnight. A name leaves this set only
    # when the migration instructions that cite it are themselves retired.
    RETIRED_TOOL_NAMES = {
        "wave_open_gate",
        "wf_close_wave_gate",
    }

    findings = []
    scanned_files = 0
    pack_prefix = ".wavefoundry/framework/seeds/"

    for seed_dir in seed_dirs:
        if not seed_dir.is_dir():
            continue
        for f in sorted(seed_dir.glob("*.md")):
            try:
                text = f.read_text(encoding="utf-8")
            except OSError:
                continue
            scanned_files += 1
            rel = str(f.relative_to(root)).replace("\\", "/")  # wave 1p9hm: forward-slash in wf_audit output

            # Check for stale tool references (tool names mentioned but not in live set)
            import re as _re2
            # Tool name must end in an alphanumeric character (not underscore)
            # so we don't greedy-consume the trailing underscore in
            # `wf_new_*` constructs. The optional `(_\*)?` group then has a
            # chance to match the wildcard family-reference suffix. `wave_`
            # stays in the scan so leftover pre-rename tool mentions are
            # flagged as stale; `memory_`/`index_` scan by exact tool name
            # because those prefixes collide with common identifiers
            # (memory_id, index_freshness).
            for match in _re2.finditer(
                r'\b(wf_[a-zA-Z_]*[a-zA-Z0-9]|wave_[a-zA-Z_]*[a-zA-Z0-9]'
                r'|memory_add|memory_propose|memory_backfill|memory_validate'
                r'|memory_search|memory_brief|memory_reconcile'
                r'|index_health|index_build_status|index_build|index_optimize'
                r'|docs_search|code_[a-zA-Z_]*[a-zA-Z0-9]|seed_get)(_\*)?',
                text,
            ):
                tool = match.group(1)
                wildcard_suffix = match.group(2)
                if wildcard_suffix:
                    # `wf_new_*` family reference — skip, even if `wave_new` itself isn't live.
                    continue
                clean = tool.rstrip("_")
                if clean in live_tools or clean + "_response" in live_tools:
                    continue
                if clean in workflow_config_keys:
                    continue
                if clean in NON_TOOL_IDENTIFIERS:
                    continue
                if clean in RETIRED_TOOL_NAMES:
                    # Documented migration text keeps the retired name on purpose.
                    continue
                # Skip kind-specific dispatcher prefixes that always have a kind suffix
                # (e.g. `wf_new_X`, `wf_list_X`, `wf_get_X`, `wf_set_X`).
                if any(clean.startswith(p) for p in ("wf_new_", "wf_list_", "wf_get_", "wf_set_")):
                    continue
                findings.append({
                    "file": rel,
                    "type": "stale_tool_reference",
                    "detail": f"Tool '{clean}' mentioned but not found in live MCP surface",
                    # 1u8o2 (1u8o1): pack-owned findings are explicitly
                    # classified so a downstream project can ignore what it
                    # cannot fix, while the framework source repo keeps its
                    # only automated stale-seed-text audit. Chosen over a
                    # conditional pack exclusion because no reliable
                    # self-host discriminator exists (the vendored pack
                    # layout is byte-identical to the source layout).
                    "classification": (
                        "pack_internal" if rel.startswith(pack_prefix) else "project"
                    ),
                })

            # Bypass-pattern detection deliberately omitted — see docstring.

    return {
        "scanned_files": scanned_files,
        "findings": findings[:50],  # cap at 50 to avoid overwhelming response
        "findings_count": len(findings),
        # 1u8o2 (1u8o1): additive split of findings_count by classification.
        # `pack_internal` findings are non-blocking for downstream projects
        # (pack-owned text only the framework source repo can change).
        "pack_internal_count": sum(
            1 for f in findings if f.get("classification") == "pack_internal"
        ),
        "project_findings_count": sum(
            1 for f in findings if f.get("classification") != "pack_internal"
        ),
    }


_PREPARE_COUNCIL_VERDICT_RE = re.compile(
    r"^\s*-\s*\*\*Prepare-phase Wave Council \[prepare-council\] — (?P<date>[^:]+): (?P<verdict>PASS(?: WITH NOTES)?|BLOCKED)\*\*(?:\s*\((?P<meta>.*)\))?\s*$",
    re.IGNORECASE,
)
_PREPARE_COUNCIL_META_KEY_RE = re.compile(
    r"(?:^|;)\s*(?P<key>moderator|primer-depth|seats|rotating-seat|"
    r"strongest-challenge|strongest-alternative)\s*:",
    re.IGNORECASE,
)
_PREPARE_COUNCIL_REQUIRED_META_FIELDS = (
    "moderator",
    "primer-depth",
    "seats",
    "rotating-seat",
    "strongest-challenge",
    "strongest-alternative",
)


def _prepare_council_verdict_info(wave_text: str) -> dict[str, Any]:
    """Parse the prepare-phase Wave Council verdict from ## Review Checkpoints."""
    _heading_pat = re.compile(r"^(#{1,6} .+)$", re.MULTILINE)
    headings = list(_heading_pat.finditer(wave_text))
    for i, m in enumerate(headings):
        if m.group(1).strip() == "## Review Checkpoints":
            end = headings[i + 1].start() if i + 1 < len(headings) else len(wave_text)
            checkpoints = wave_text[m.end():end]
            lines = checkpoints.splitlines()
            for index, raw in enumerate(lines):
                line = raw.strip()
                if "prepare-council" not in line.casefold():
                    continue
                # A checklist bullet may wrap its parenthesized metadata onto
                # indented continuation lines.  Consume only that logical list
                # item; the next bullet, heading, blank line, or unindented
                # prose remains outside the verdict.
                logical_lines = [line]
                for continuation in lines[index + 1:]:
                    if not continuation.strip() or continuation.lstrip().startswith("#"):
                        break
                    if re.match(r"\s*-\s+", continuation) or not continuation.startswith((" ", "\t")):
                        break
                    logical_lines.append(continuation.strip())
                line = " ".join(logical_lines)
                match = _PREPARE_COUNCIL_VERDICT_RE.match(line)
                if not match:
                    return {
                        "present": True,
                        "valid": False,
                        "line": line,
                        "verdict": "",
                        "date": "",
                        "meta": {},
                        "missing_fields": list(_PREPARE_COUNCIL_REQUIRED_META_FIELDS),
                        "parse_error": "invalid verdict header or markdown continuation",
                    }
                meta_text = match.group("meta") or ""
                meta: dict[str, str] = {}
                field_markers = list(_PREPARE_COUNCIL_META_KEY_RE.finditer(meta_text))
                for marker_index, marker in enumerate(field_markers):
                    value_start = marker.end()
                    value_end = (
                        field_markers[marker_index + 1].start()
                        if marker_index + 1 < len(field_markers)
                        else len(meta_text)
                    )
                    # The delimiter precedes the NEXT known key, so a semicolon
                    # inside a strongest-* value stays part of that value.
                    value = meta_text[value_start:value_end].strip().rstrip(";").strip()
                    meta[marker.group("key").casefold()] = value
                missing_fields = [field for field in _PREPARE_COUNCIL_REQUIRED_META_FIELDS if not meta.get(field)]
                verdict = match.group("verdict").strip().upper()
                valid = not missing_fields and verdict in {"PASS", "PASS WITH NOTES"}
                return {
                    "present": True,
                    "valid": valid,
                    "line": line,
                    "verdict": verdict,
                    "date": match.group("date").strip(),
                    "meta": meta,
                    "missing_fields": missing_fields,
                    "parse_error": (
                        "missing required metadata fields: " + ", ".join(missing_fields)
                        if missing_fields else ""
                    ),
                }
    return {
        "present": False,
        "valid": False,
        "line": "",
        "verdict": "",
        "date": "",
        "meta": {},
        "missing_fields": list(_PREPARE_COUNCIL_REQUIRED_META_FIELDS),
        "parse_error": "",
    }


def _council_seat_alignment_issues(
    verdict_info: Mapping[str, Any], council_brief: Mapping[str, Any]
) -> list[str]:
    """Wave 1seax (1seat AC-6): compare the RECORDED council seats against the
    generated brief's required seats. The structural parser alone accepted
    councils that never ran the brief's rotating seat — a false readiness
    approval. Returns human-readable mismatch descriptions (empty = aligned).
    """
    meta = verdict_info.get("meta") or {}
    recorded_seats = [
        s.strip() for s in re.split(r"[,;]", str(meta.get("seats", ""))) if s.strip()
    ]
    recorded_fold = {s.casefold() for s in recorded_seats}
    recorded_rotating = str(meta.get("rotating-seat") or "").strip()
    issues: list[str] = []
    fixed = str(council_brief.get("fixed_seat") or "").strip()
    rotating = str(council_brief.get("rotating_seat") or "").strip()
    if fixed and fixed.casefold() not in recorded_fold:
        issues.append(
            f"the brief's fixed seat '{fixed}' is missing from the recorded seats"
        )
    if rotating and rotating.casefold() != "none":
        if rotating.casefold() not in recorded_fold:
            issues.append(
                f"the brief's rotating seat '{rotating}' is missing from the recorded seats"
            )
        if recorded_rotating and recorded_rotating.casefold() not in {
            rotating.casefold(), "none",
        }:
            issues.append(
                f"the recorded rotating-seat '{recorded_rotating}' does not match "
                f"the brief's '{rotating}'"
            )
    return issues


def _prepare_council_verdict_present(wave_text: str) -> bool:
    """True if a valid prepare-council verdict line is recorded."""
    return bool(_prepare_council_verdict_info(wave_text).get("valid"))


def _bind_prepare_council_brief_to_receipt(
    council_brief: Mapping[str, Any], receipt: Mapping[str, Any] | None
) -> dict[str, Any]:
    """Use the receipt-bound roster for every post-Prepare council check.

    ``instructions`` and ``verdict_format`` are rebuilt from the bound seat, not
    carried over. Both embed the rotating seat, so leaving them at their
    wave-text value made one response advertise two rosters: the authoritative
    fields naming the receipt's seat while the copy-paste template named the
    wave-text seat. An agent following the template then recorded a verdict that
    the seat-alignment check rejected against the very roster the same response
    had bound.
    """

    bound = dict(council_brief)
    seats = receipt.get("council_seats") if isinstance(receipt, Mapping) else None
    if not isinstance(seats, list) or not seats:
        return bound
    fixed = str(seats[0])
    rotating = str(seats[1]) if len(seats) > 1 else None
    bound.update(
        {
            "fixed_seat": fixed,
            "rotating_seat": rotating,
            "council_seats": [
                f"{fixed} (fixed)",
                *([f"{rotating} (rotating)"] if rotating else []),
            ],
            "rotating_seat_reason": "Bound to the current review-policy receipt.",
            "instructions": _prepare_council_instructions(rotating),
            "verdict_format": _prepare_council_verdict_template(rotating),
        }
    )
    return bound


def _project_current_review_status(root: Path, wave_md: Path, text: str) -> str:
    """Rebuild both human projections from the canonical ledger."""

    if not _wave_uses_external_review_evidence(root, wave_md):
        return text
    validation = validate_external_review_evidence(wave_md)
    if validation.errors:
        raise ValueError("; ".join(validation.errors))
    projected = render_review_evidence_projection(text, validation.records)
    return render_review_status_projection(
        projected,
        validation.records,
        _review_status_signoff_keys(root, projected, validation.records),
    )


def _identified_review_event_bundle(
    records: Iterable[dict[str, Any]], identity: dict[str, Any]
) -> tuple[dict[str, Any], ...] | None:
    """Return the committed bundle whose leading row owns ``identity``."""

    rows = tuple(records)
    for start, row in enumerate(rows):
        if row.get(EVENT_IDENTITY_FIELD) != identity:
            continue
        end = start + 1
        while end < len(rows) and EVENT_IDENTITY_FIELD not in rows[end]:
            end += 1
        return tuple(rows[start:end])
    return None


# Wave 1t59p (1t6ow): bounded output for the review-evidence list event.
REVIEW_EVIDENCE_LIST_CAP = 500


def _guided_review_actions(
    records: Iterable[Mapping[str, Any]],
    required_signoff_keys: Iterable[str],
    *,
    approval_phase: str,
    required_run_kind: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Return the bounded public action payload from the canonical projection."""

    projection = review_authority_projection(
        records,
        required_signoff_keys,
        approval_phase=approval_phase,
        required_run_kind=required_run_kind,
    )
    payload = {
        "available": True,
        "phase": projection["phase"],
        "next_actions": list(projection["next_actions"]),
        "recommended_next_action": projection["recommended_next_action"],
        "total_current_actions": projection["total_current_actions"],
        "returned_current_actions": projection["returned_current_actions"],
        "omitted_current_actions": projection["omitted_current_actions"],
        "truncated": projection["truncated"],
        "action_cap": projection["action_cap"],
        "caller_input_schema": review_action_input_schema(),
    }
    diagnostics: list[dict[str, Any]] = []
    if projection["truncated"]:
        diagnostics.append(
            _diagnostic(
                REVIEW_ACTION_TRUNCATED_DIAGNOSTIC,
                "Guided review actions were capped at "
                f"{projection['action_cap']} of {projection['total_current_actions']} "
                "current actions. Use wf_review_event(event='list') for the complete "
                "forensic ledger before choosing an omitted action.",
                recovery_tools=["wf_review_event"],
                recovery_usage="wf_review_event(wave_id=..., event='list', actor=..., context_id=...)",
            )
        )
    return payload, diagnostics


def _guided_review_authority_blocker(
    diagnostics: Iterable[Mapping[str, Any]],
) -> str | None:
    """Return a policy prerequisite that makes signoff actions untrustworthy."""

    blocking_codes = {
        "review_policy_receipt_stale",
        "review_policy_reprepare_required",
    }
    return next(
        (
            str(diagnostic.get("code"))
            for diagnostic in diagnostics
            if diagnostic.get("code") in blocking_codes
        ),
        None,
    )


def _guided_review_signoff_keys(
    root: Path,
    wave_md: Path,
    wave_text: str,
    *,
    approval_phase: str,
) -> list[str]:
    """Return the existing required-signoff order for one guided phase."""

    lanes = list(
        dict.fromkeys(
            [
                *_extract_required_review_lanes(wave_text),
                *_read_project_required_review_lanes(root),
            ]
        )
    )
    lifecycle_phase = "prepare" if approval_phase == "readiness" else "review"
    keys = [
        *_required_wave_council_signoffs(
            root, lifecycle_phase, wave_text=wave_text, wave_md=wave_md
        ),
        *lanes,
    ]
    if approval_phase == "delivery":
        keys.append("operator-signoff")
    return list(dict.fromkeys(keys))


def _unavailable_guided_review_actions(reason: str) -> dict[str, Any]:
    """Fail closed when no trustworthy typed authority can derive actions."""

    return {
        "available": False,
        "reason": reason,
        "next_actions": [],
        "recommended_next_action": None,
        "total_current_actions": 0,
        "returned_current_actions": 0,
        "omitted_current_actions": 0,
        "truncated": False,
        "action_cap": REVIEW_ACTION_CAP,
    }


def _review_evidence_list_response(
    root: Path,
    wave_id: str,
    wave_md: Path,
    events_path: Path,
    *,
    finding_id: str | None = None,
    record_type: str = "",
    run_kind: str | None = None,
    verbose: bool = False,
) -> dict[str, Any]:
    """Read-only listing of the review-evidence ledger (wave 1t59p / 1t6ow).

    Presents ONLY the canonical validated records, structured authority
    projection, and review-evidence summary, so forensic readers see exactly
    the state used by guided review and the close gate. Never takes the write
    lock and never mutates the ledger.
    """
    rel_events = str(events_path.resolve().relative_to(root.resolve())).replace("\\", "/")
    base: dict[str, Any] = {
        "wave_id": wave_id,
        "event": "list",
        "events_path": rel_events,
        "filters": {
            **({"finding_id": finding_id} if finding_id else {}),
            **({"record_type": record_type} if record_type else {}),
            **({"run_kind": run_kind} if run_kind else {}),
        },
    }
    if not events_path.exists():
        return _response(
            "ok",
            {**base, "records": [], "total_records": 0, "truncated": False,
             "summary": {}, "chain_summary": {}, "approvals": [], "context_summary": []},
            diagnostics=[_diagnostic(
                "review_evidence_empty",
                "No events.jsonl ledger exists for this wave yet — nothing recorded.",
                recovery_tools=["wf_review_event"],
                recovery_usage="wf_review_event(wave_id=..., event='run', ...)",
            )],
            next_tools=["wf_review_event"],
            usage="wf_review_event(wave_id=..., event='run', mode='dry_run', ...)",
        )
    result = validate_external_review_evidence(wave_md)
    records = list(result.records or ())
    diagnostics: list[dict[str, Any]] = []
    for error in result.errors or ():
        diagnostics.append(_diagnostic("review_evidence_invalid", str(error)))

    def _identity(record: dict[str, Any]) -> str:
        return str(
            record.get("record_id")
            or record.get("evidence_record_id")
            or record.get("review_run_id")
            or ""
        )

    def _row(record: dict[str, Any]) -> dict[str, Any]:
        if verbose:
            return dict(record)
        compact: dict[str, Any] = {"id": _identity(record), "record_type": record.get("record_type")}
        for key in (
            "run_kind", "cycle", "finding_id", "claim_kind", "claim_id",
            "signoff_key", "disposition", "repair_execution_state",
            "source_lanes", "blocking_required_lanes", "approval_recheck_lanes",
            "supersedes_record_id", "verification_context",
        ):
            if key in record:
                compact[key] = record[key]
        identity = record.get(EVENT_IDENTITY_FIELD)
        if isinstance(identity, dict):
            compact["event_identity"] = {
                k: identity.get(k) for k in ("actor", "context_id", "run_kind", "cycle", "signoff_key")
                if identity.get(k) is not None
            }
        return compact

    filtered = records
    if finding_id:
        filtered = [
            r for r in filtered
            if r.get("finding_id") == finding_id or r.get("claim_id") == finding_id
        ]
    if record_type:
        filtered = [r for r in filtered if r.get("record_type") == record_type]
    if run_kind:
        filtered = [r for r in filtered if r.get("run_kind") == run_kind]
    total = len(filtered)
    truncated = total > REVIEW_EVIDENCE_LIST_CAP
    # Keep the TAIL on truncation: recent records are what an appender needs.
    visible = filtered[-REVIEW_EVIDENCE_LIST_CAP:] if truncated else filtered

    chain_summary: dict[str, Any] = {}
    # Wave 1v0lw: the record read routes through the seam; a failure degrades
    # this listing (enumeration surface) under the true cause instead of the
    # derivation-failure code, and never leaks the absolute path.
    wave_text, wave_read_error = _read_wave_record_text(wave_md)
    if wave_text is None:
        approvals = []
        diagnostics.append(
            _wave_record_unreadable_diagnostic(root, wave_md, wave_read_error)
        )
    else:
        try:
            required_keys = required_review_status_keys(root, wave_text, records)
            authority_projection = review_authority_projection(records, required_keys)
            for fact in authority_projection["finding_facts"]:
                chain_summary[fact["finding_id"]] = {
                    "head_record_id": fact["head_record_id"],
                    "cycle": fact["cycle"],
                    "disposition": fact["disposition"],
                    "repair_execution_state": fact["repair_execution_state"],
                    "unresolved_required_lanes": list(fact["unresolved_required_lanes"]),
                    "terminal": fact["terminal"],
                }
            approvals = list(authority_projection["status_rows"])
        except Exception as exc:  # noqa: BLE001 - listing must not fail on status derivation
            approvals = []
            diagnostics.append(_diagnostic("review_status_unavailable", str(exc)))
    if truncated:
        diagnostics.append(_diagnostic(
            "review_evidence_list_truncated",
            f"Listing capped at {REVIEW_EVIDENCE_LIST_CAP} of {total} matching records "
            "(most recent kept). Narrow with finding_id/record_type/run_kind filters.",
        ))
    return _response(
        "ok",
        {
            **base,
            "records": [_row(r) for r in visible],
            "total_records": total,
            "truncated": truncated,
            "record_cap": REVIEW_EVIDENCE_LIST_CAP,
            "summary": review_evidence_summary(records),
            "context_summary": review_context_summary(records),
            "chain_summary": chain_summary,
            "approvals": approvals,
        },
        diagnostics=diagnostics,
        next_tools=["wf_review_event", "wf_review_wave"],
        usage="wf_review_event(wave_id=..., event='finding'|'run'|'approval', mode='dry_run', ...)",
    )


def _review_event_build_error_diagnostic(
    error: str, *, wave_id: str, actor: str, context_id: str, review_phase: str
) -> dict[str, Any]:
    """Wrap one compact-builder rejection as a response diagnostic.

    Wave 1tmb2: the chain-aware independence rejections carry their own
    diagnostic codes (`reverification_context_not_fresh`,
    `reverification_actor_not_distinct`) as the leading token of the
    validator error string; everything else stays `invalid_review_event`.
    """

    code = "invalid_review_event"
    message = error
    for known in INDEPENDENCE_DIAGNOSTIC_CODES:
        prefix = f"{known}: "
        if error.startswith(prefix):
            code = known
            message = error[len(prefix):]
            break
    return _diagnostic(
        code, message,
        recovery_tools=["wf_review_wave"],
        recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase={review_phase!r})  # derive the current phase-correct action before retrying",
    )


def _review_event_recovery_phase(
    *,
    wave_text: str,
    event: str,
    signoff_key: str | None,
    approval_phase: str | None,
    run_kind: str | None,
    finding_id: str | None,
    records: Iterable[Mapping[str, Any]],
) -> str:
    """Derive recovery phase from authority identity, never invalid input phase."""

    if event == "approval":
        if signoff_key == "wave-council-readiness":
            return "prepare"
        if signoff_key in {"wave-council-delivery", "operator-signoff"}:
            return "implementation"
        if approval_phase in {"readiness", "delivery"}:
            return "prepare" if approval_phase == "readiness" else "implementation"
        return (
            "prepare"
            if re.search(r"(?mi)^Status:\s*planned\s*$", wave_text)
            else "implementation"
        )
    if run_kind == "readiness":
        return "prepare"
    if run_kind == "initial_delivery":
        return "implementation"
    if run_kind in {"repair_start", "reverification"} and finding_id:
        origin = finding_origin_phase(records, finding_id)
        if origin == "readiness":
            return "prepare"
        if origin == "delivery":
            return "implementation"
    return (
        "prepare"
        if re.search(r"(?mi)^Status:\s*planned\s*$", wave_text)
        else "implementation"
    )


@_fail_closed_on_record_layout("wf_review_event")
def wf_review_event_response(
    root: Path,
    wave_id: str,
    event: str,
    actor: str,
    context_id: str,
    *,
    mode: str = "dry_run",
    signoff_key: str | None = None,
    approval_phase: str | None = None,
    finding_id: str | None = None,
    run_kind: str | None = None,
    cycle: int = 0,
    judgment: dict[str, Any] | None = None,
    evidence: dict[str, Any] | None = None,
    source_lanes: list[str] | None = None,
    blocking_required_lanes: list[str] | None = None,
    approval_recheck_lanes: list[str] | None = None,
    review_boundaries_changed: list[str] | None = None,
    fresh_context: bool = False,
    independent: bool = False,
    integrity_checks: dict[str, Any] | None = None,
    record_type: str = "",
    verbose: bool = False,
    operator_handle: str | None = None,
) -> dict[str, Any]:
    """Preview or append a compact semantic review event to a marked wave.

    Receipt rotation lapses readiness approvals only; delivery approvals do not lapse solely from rotation,
    and ``review_policy_receipt_stale`` blocks implementation-phase review until
    re-Prepare without touching them.

    ``event="list"`` is the read-only listing surface (wave 1t59p / 1t6ow):
    it branches before any write-path validation, ignores ``mode``, and never
    takes the write lock.
    """

    is_list = (event or "").strip().lower() == REVIEW_LIST_EVENT
    mode_s = (mode or "dry_run").strip().lower()
    if not is_list and mode_s not in {"dry_run", "create"}:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s},
            diagnostics=[_diagnostic("invalid_arguments", "mode must be dry_run or create")],
            next_tools=["wf_help"],
            usage="wf_help()",
        )
    try:
        wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    except ValueError as exc:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "event": event},
            diagnostics=[_diagnostic("review_evidence_path_escape", str(exc))],
        )
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves, data={"wave_id": wave_id}
            )
        return _response(
            "error",
            {"wave_id": wave_id},
            diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.")],
            next_tools=["wf_list_waves"],
            usage="wf_list_waves()",
        )
    try:
        wave_md, _events_path = _contained_wave_review_paths(root, wave_md)
    except ValueError as exc:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "event": event},
            diagnostics=[_diagnostic("review_evidence_path_escape", str(exc))],
        )
    if is_list:
        return _review_evidence_list_response(
            root, wave_id, wave_md, _events_path,
            finding_id=finding_id, record_type=record_type,
            run_kind=run_kind, verbose=verbose,
        )
    wave_text_for_phase, wave_read_error = _read_wave_record_text(wave_md)
    if wave_text_for_phase is None:
        # Wave 1v0lw: a typed review event amends the wave's authority; the
        # append gate cannot be evaluated over a record that cannot be read.
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error,
            data={"wave_id": wave_id, "mode": mode_s, "event": event},
        )
    # Most event identities determine their recovery phase without touching
    # the ledger. Only a repair/reverification needs the finding's sealed
    # origin for errors that can occur before the publication transaction.
    # Do not start every write with an unlocked authority read: the locked
    # transaction below owns the live phase decision and append boundary.
    phase_records: Iterable[Mapping[str, Any]] = ()
    if run_kind in {"repair_start", "reverification"} and finding_id:
        phase_authority = validate_external_review_evidence(wave_md)
        if not phase_authority.errors:
            phase_records = phase_authority.records
    review_phase = _review_event_recovery_phase(
        wave_text=wave_text_for_phase,
        event=event,
        signoff_key=signoff_key,
        approval_phase=approval_phase,
        run_kind=run_kind,
        finding_id=finding_id,
        records=phase_records,
    )
    semantic_event: dict[str, Any] = {
        "event": event,
        "actor": actor,
        "context_id": context_id,
        "signoff_key": signoff_key,
        "approval_phase": approval_phase,
        "finding_id": finding_id,
        "run_kind": run_kind,
        "cycle": cycle,
        "judgment": judgment,
        "source_lanes": source_lanes or [],
        "blocking_required_lanes": blocking_required_lanes or [],
        "approval_recheck_lanes": approval_recheck_lanes or [],
        "review_boundaries_changed": review_boundaries_changed or [],
        "fresh_context": fresh_context,
        "independent": independent,
        "integrity_checks": integrity_checks,
    }
    evidence_payload = dict(evidence or {})
    protected_collisions = sorted(
        (
            set(semantic_event)
            | {EVENT_IDENTITY_FIELD, REQUEST_DIGEST_FIELD, "policy_receipt_id"}
        )
        .intersection(evidence_payload)
    )
    if protected_collisions:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "event": event},
            diagnostics=[
                _diagnostic(
                    "invalid_review_event",
                    "evidence may not override protected semantic field(s): "
                    + ", ".join(protected_collisions),
                    recovery_tools=["wf_review_wave"],
                    recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase={review_phase!r})",
                )
            ],
            next_tools=["wf_review_wave"],
            usage=f"wf_review_wave(wave_id={wave_id!r}, phase={review_phase!r})",
        )
    semantic_event.update(evidence_payload)
    readiness_approval = bool(
        event == "approval"
        and approval_phase == "readiness"
        and signoff_key not in {"wave-council-delivery", "operator-signoff"}
    )
    if readiness_approval:
        receipt_validation = validate_external_review_evidence(wave_md)
        if receipt_validation.errors:
            return _response(
                "error",
                {"wave_id": wave_id, "mode": mode_s, "event": event},
                diagnostics=[
                    _diagnostic("review_evidence_invalid", error)
                    for error in receipt_validation.errors
                ],
            )
        receipt = current_policy_receipt(receipt_validation.records)
        if receipt is None:
            return _response(
                "error",
                {"wave_id": wave_id, "mode": mode_s, "event": event},
                diagnostics=[
                    _diagnostic(
                        "review_policy_reprepare_required",
                        "A readiness approval requires the current Prepare-owned review-policy receipt.",
                        recovery_tools=["wf_prepare_wave"],
                        recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')",
                    )
                ],
            )
        semantic_event["policy_receipt_id"] = receipt["receipt_id"]
    try:
        identity = derive_review_event_identity(wave_md.parent.name, semantic_event)
        request_digest = review_event_request_digest(semantic_event)
    except (TypeError, ValueError) as exc:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "event": event},
            diagnostics=[_diagnostic(
                "invalid_review_event", str(exc),
                recovery_tools=["wf_review_wave"],
                recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase={review_phase!r})",
            )],
        )

    def transact() -> dict[str, Any]:
        original, original_read_error = _read_wave_record_text(wave_md)
        if original is None:
            # Readable at the gate above, unreadable inside the transaction;
            # refuse before any authority decision or append.
            return _wave_record_unreadable_response(
                root, wave_md, original_read_error,
                data={"wave_id": wave_id, "mode": mode_s, "event": event},
            )
        current = validate_external_review_evidence(wave_md)
        if current.errors:
            return _response(
                "error",
                {"wave_id": wave_id, "mode": mode_s},
                diagnostics=[_diagnostic("review_evidence_invalid", error) for error in current.errors],
                next_tools=["wf_review_wave", "wf_current_wave"],
            )
        transaction_review_phase = _review_event_recovery_phase(
            wave_text=original,
            event=event,
            signoff_key=signoff_key,
            approval_phase=approval_phase,
            run_kind=run_kind,
            finding_id=finding_id,
            records=current.records,
        )
        stale_warnings: list[dict[str, Any]] = []
        if readiness_approval:
            live_receipt = current_policy_receipt(current.records)
            if (
                live_receipt is None
                or live_receipt.get("receipt_id")
                != semantic_event.get("policy_receipt_id")
            ):
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[
                        _diagnostic(
                            "review_policy_receipt_stale",
                            "The review-policy receipt changed before approval publication; re-Prepare and retry.",
                            recovery_tools=["wf_prepare_wave"],
                            recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')",
                        )
                    ],
                )
        existing_bundle = _identified_review_event_bundle(current.records, identity)
        replayed = existing_bundle is not None
        if readiness_approval and existing_bundle is None:
            # Only a genuinely NEW append is checked.  An idempotent replay of an
            # already-recorded approval must still replay: the record is already in
            # the ledger, so refusing it would report that the approval could never
            # satisfy a gate about a call that wrote nothing, and would break the
            # documented same-identity retry contract.
            # The check above compares receipt IDs, so a mint that has become
            # PENDING without the current id moving passes it -- which is the
            # whole defect.  Recompute the policy inputs here, inside the
            # publication lock, and refuse rather than writing an approval that
            # is dead on arrival into an append-only authority ledger.
            recompute_change_ids = _extract_change_ids_from_wave_text(original)
            recompute_state, recompute_errors = _prepare_policy_state(
                root,
                wave_md,
                original,
                recompute_change_ids,
                # `_prepare_policy_state` never reads `council_brief`; building
                # the real brief here would run seat selection and template
                # assembly on every readiness approval, inside the lock, for
                # nothing.
                {},
            )
            if recompute_errors:
                blocking = [
                    error
                    for error in recompute_errors
                    if policy_input_error_cause(error)
                    not in POLICY_INPUT_DEGRADABLE_CAUSES
                ]
                if blocking:
                    return _response(
                        "error",
                        {"wave_id": wave_id, "mode": mode_s, "event": event},
                        diagnostics=[
                            _diagnostic(
                                "review_policy_receipt_stale",
                                "Cannot verify the review-policy receipt is current, and the "
                                f"cause is repairable rather than environmental: {error}",
                                recovery_tools=_staleness_recovery_tools(error),
                                recovery_usage=_staleness_recovery_usage(
                                    error, wave_id
                                ),
                            )
                            for error in blocking
                        ],
                    )
                # Degrade, but say so: the ledger will not record that this
                # approval skipped verification, so the response must.
                stale_warnings = [
                    _diagnostic(
                        "review_policy_staleness_unverified",
                        "The review-policy staleness check COULD NOT BE PERFORMED for this "
                        f"approval and it was accepted without that verification: {error}",
                        recovery_tools=["wf_prepare_wave"],
                        recovery_usage=(
                            f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')"
                        ),
                    )
                    for error in recompute_errors
                ]
            elif recompute_state is None:
                # State absent with an EMPTY error tuple; branching on `errors`
                # alone mishandles it.
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[
                        _diagnostic(
                            "review_policy_receipt_stale",
                            "Cannot verify the review-policy receipt is current: policy "
                            "selection returned no state and no error.",
                            recovery_tools=["wf_prepare_wave"],
                            recovery_usage=(
                                f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')"
                            ),
                        )
                    ],
                )
            elif recompute_state["receipt_append_required"]:
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[
                        _diagnostic(
                            "review_policy_receipt_stale",
                            "A readiness approval cannot bind an already-superseded receipt: "
                            "a policy input has moved and the next Prepare will publish a new "
                            "receipt, so this approval could never satisfy a gate"
                            + receipt_supersession_attribution(
                                recompute_state, recompute_change_ids
                            ),
                            recovery_tools=["wf_prepare_wave"],
                            recovery_usage=(
                                f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')"
                            ),
                        )
                    ],
                )
        if existing_bundle is not None:
            if existing_bundle[0].get(REQUEST_DIGEST_FIELD) != request_digest:
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[_diagnostic(
                        "review_event_identity_conflict",
                        "the derived event identity already exists with different semantic content",
                    )],
                )
            appended = existing_bundle
            proposed_records = tuple(current.records)
        else:
            # Attribution is metadata of the first write, never retry identity.
            # Keep lookup below the replay branch so retries retain the stored
            # contributor even when local configuration has changed.
            operator, identity_reason = resolve_operator(root, operator_handle)
            if operator is None and identity_reason != "no_contributors_file":
                stale_warnings.append(_diagnostic(
                    "operator_identity_unresolved",
                    f"{identity_reason}. Check docs/contributors.json and git user.email, "
                    "or supply a mapped operator_handle. Attribution omitted.",
                    advisory=True,
                ))
            appended, build_errors = build_identified_review_event(
                current.records, wave_md.parent.name, semantic_event, operator=operator
            )
            if build_errors:
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[
                        _review_event_build_error_diagnostic(
                            error, wave_id=wave_id, actor=actor,
                            context_id=context_id,
                            review_phase=transaction_review_phase,
                        )
                        for error in build_errors
                    ],
                    next_tools=["wf_help"],
                )
            proposed_records = (*current.records, *appended)
            record_errors = validate_review_evidence_records(proposed_records)
            if record_errors:
                return _response(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s, "event": event},
                    diagnostics=[
                        _diagnostic(
                            "review_evidence_invalid",
                            error,
                            recovery_tools=["wf_review_wave"],
                            recovery_usage=(
                                f"wf_review_wave(wave_id={wave_id!r}, "
                                f"phase={transaction_review_phase!r})  # derive the current "
                                "phase-correct action before retrying"
                            ),
                        )
                        for error in record_errors
                    ],
                    next_tools=["wf_review_wave"],
                )
        projected = render_review_evidence_projection(original, proposed_records)
        projected = render_review_status_projection(
            projected,
            proposed_records,
            _review_status_signoff_keys(root, projected, proposed_records),
        )
        payload = {
            "wave_id": wave_md.parent.name,
            "path": str(wave_md.relative_to(root.resolve())).replace("\\", "/"),
            "events_path": str(review_event_path(wave_md).relative_to(root.resolve())).replace("\\", "/"),
            "mode": mode_s,
            "event": event,
            "appended_records": list(appended),
            "summary": review_evidence_summary(proposed_records),
            "replayed": replayed,
        }
        artifact = (evidence or {}).get("artifact_or_test_id", "")
        if str(semantic_event.get("event", "")).lower() in {"finding", "approval"} and isinstance(artifact, str):
            path_tokens = artifact_path_tokens(artifact)
            temporary_tokens = ephemeral_artifact_tokens(artifact)
            if path_tokens and len(temporary_tokens) == len(path_tokens):
                stale_warnings.append(_diagnostic(
                    "artifact_or_test_id_ephemeral",
                    "Every evidence path is ephemeral: " + ", ".join(temporary_tokens)
                    + ". Cite a durable repository path so later reviewers can inspect it.",
                    advisory=True,
                ))
        if mode_s == "dry_run":
            # The preview must carry the same caveat the mutating call reports.
            # The refusal branches already fire on dry-run; dropping only the
            # degraded-acceptance warning made a preview quieter than the call
            # it previews, which is the asymmetry this change exists to remove.
            return _response(
                "dry_run", payload,
                diagnostics=stale_warnings or None,
                next_tools=["wf_review_event"],
            )
        event_committed = replayed
        if not replayed:
            try:
                _atomic_replace_bytes(
                    review_event_path(wave_md),
                    canonical_review_events_bytes(proposed_records),
                    "review-events",
                )
                event_committed = True
            except OSError as exc:
                return _response(
                    "error", payload,
                    diagnostics=[_diagnostic("review_event_commit_failed", str(exc))],
                )
        try:
            _atomic_replace_text(wave_md, projected, "review-projection")
        except OSError as exc:
            payload.update(event_committed=event_committed, projection_stale=True)
            return _response(
                "partial", payload,
                diagnostics=[_diagnostic("review_evidence_projection_stale", str(exc))],
                next_tools=["wf_review_event", "wf_review_wave"],
            )
        payload.update(event_committed=True, projection_stale=False)
        # The continuation is another authority-bearing recommendation. Its
        # phase must come from the same validated signoff/run/finding identity
        # used by rejection recovery, never from a caller-supplied phase that
        # is irrelevant to a finding or run event.
        continuation_phase = (
            "readiness"
            if transaction_review_phase == "prepare"
            else "delivery"
        )
        action_keys = _guided_review_signoff_keys(
            root, wave_md, projected, approval_phase=continuation_phase
        )
        continuation_blocker = _guided_review_authority_blocker(
            [
                *_wave_review_policy_diagnostics(root),
                *_review_policy_receipt_diagnostics(root, wave_md, projected),
                *(
                    [
                        _diagnostic(
                            "review_policy_reprepare_required",
                            "This wave must be re-Prepared before guided review continues.",
                        )
                    ]
                    if has_reprepare_marker(projected)
                    else []
                ),
            ]
        )
        if continuation_blocker is None:
            review_actions, action_diagnostics = _guided_review_actions(
                proposed_records,
                action_keys,
                approval_phase=continuation_phase,
                required_run_kind=(
                    "readiness"
                    if continuation_phase == "readiness"
                    else "initial_delivery"
                ),
            )
        else:
            review_actions = _unavailable_guided_review_actions(
                continuation_blocker
            )
            action_diagnostics = []
        payload["review_actions"] = review_actions
        return _response(
            "ok",
            payload,
            diagnostics=[*stale_warnings, *action_diagnostics],
            next_tools=["wf_review_event", "wf_review_wave"],
        )

    try:
        if mode_s == "create":
            with project_state_publication_lock(root):
                response = transact()
        else:
            response = transact()
    except OSError as exc:
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "event": event},
            diagnostics=[_diagnostic("review_evidence_persist_failed", str(exc))],
        )
    if mode_s == "create" and response.get("status") == "ok":
        _trigger_background_index_refresh_for_paths(root, [wave_md])
    return response


def _configured_phase_envelope(handler):
    """Keep provenance present even on record-layout and lookup refusals."""
    from functools import wraps

    @wraps(handler)
    def wrapped(*args, **kwargs):
        response = handler(*args, **kwargs)
        response.setdefault("data", {}).setdefault("configured_gates", [])
        return response
    return wrapped


READINESS_RECEIPT_PUBLICATION_ADVISORY_THRESHOLD = 5


def _prepare_lane_review_state(root: Path, wave_md: Path, wave_text: str):
    """One roster/currency calculation for Prepare advice and activation."""
    wave_lanes = _extract_required_review_lanes(wave_text)
    project_lanes = _read_project_required_review_lanes(root)
    required_lanes = wave_lanes + [lane for lane in project_lanes if lane not in wave_lanes]
    authority = resolve_review_authority(root, wave_md, wave_text=wave_text)
    missing_lanes = [
        lane for lane in required_lanes
        if not authority.signoff_current(lane, section="prepare", approval_phase="readiness")
    ]
    return authority, missing_lanes


def _attach_prepare_readiness_advisories(root: Path, wave_id: str, response: dict[str, Any]) -> dict[str, Any]:
    """Observe the final ledger, including this call's publication; never gate."""
    data = response.setdefault("data", {})
    data["readiness_receipts"] = None
    if data.get("record_layout_valid") is False or "ambiguous_wave_ids" in data:
        return response
    try:
        wave_md, _, _ = _find_wave_md_detailed(root, wave_id)
        if wave_md is None:
            return response
        records, errors = read_review_event_ledger(wave_md)
        if not errors:
            count = 0
            for record in records:
                if record.get("record_type") == "review_run" and record.get("run_kind") == "initial_delivery":
                    break
                if record.get("record_type") == "review_policy_receipt":
                    count += 1
            data["readiness_receipts"] = count
            if count > READINESS_RECEIPT_PUBLICATION_ADVISORY_THRESHOLD:
                response.setdefault("diagnostics", []).append(_diagnostic(
                    "readiness_receipt_publications_high",
                    f"This wave has {count} review-policy receipt publications before initial delivery. "
                    "Prepare publications are unusually frequent; inspect readiness churn. "
                    "This is a publication count, not a review-round budget or proof of convergence.",
                    advisory=True,
                ))
        wave_text, _ = _read_wave_record_text(wave_md)
        if wave_text is None:
            return response
        authority, missing_lanes = _prepare_lane_review_state(root, wave_md, wave_text)
        if not authority.ledger_errors and missing_lanes:
            diagnostic = _diagnostic(
                "readiness_lane_approvals_missing",
                "Implementation still requires current readiness approvals from: "
                + ", ".join(missing_lanes) + ". Re-review the repaired packet and record approvals against the current receipt.",
                recovery_tools=["wf_review_wave"],
                recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase='prepare')",
                advisory=True,
            )
            diagnostic["missing_lanes"] = missing_lanes
            response.setdefault("diagnostics", []).append(diagnostic)
    except (OSError, ValueError, record_paths.RecordLayoutInvalid, record_paths.AmbiguousWaveId):
        # Observation must not replace an existing refusal or change success.
        pass
    return response


def _prepare_readiness_envelope(handler):
    @functools.wraps(handler)
    def wrapped(root, wave_id, *args, **kwargs):
        response = handler(root, wave_id, *args, **kwargs)
        return _attach_prepare_readiness_advisories(root, wave_id, response)
    return wrapped


@_prepare_readiness_envelope
@_configured_phase_envelope
@_fail_closed_on_record_layout("wf_prepare_wave")
def wf_prepare_wave_response(root: Path, wave_id: str, mode: str = "dry_run", cache: Optional[McpRepoCache] = None) -> dict[str, Any]:
    diagnostics: list[dict[str, Any]] = []
    configured_gates: list[dict[str, Any]] = []

    def _prepare_envelope(
        status: str,
        data: dict[str, Any],
        *,
        next_tools: list[str] | None = None,
        usage: str = "",
    ) -> dict[str, Any]:
        return _response(
            status,
            {**data, "configured_gates": configured_gates},
            diagnostics=diagnostics or None,
            next_tools=next_tools,
            usage=usage,
        )

    def _has_blocking_diagnostics() -> bool:
        return lifecycle_gates.has_blocking_diagnostics(diagnostics)

    requested_mode = (mode or "").strip().lower()
    mode_s = {"apply": "create", "evaluate": "dry_run"}.get(requested_mode, requested_mode)
    if mode_s not in {"dry_run", "ready", "create"}:
        diagnostics.append(_diagnostic("invalid_arguments", f"Unsupported mode '{mode}'. Valid modes: dry_run (or evaluate), ready, create."))
        return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode, "valid_modes": ["dry_run", "evaluate", "ready", "create"]}, next_tools=["wf_help"], usage="wf_help()")
    # Wave 1p45l: decouple readiness from activation.
    #   dry_run  — read-only validation, no guard, no writes.
    #   ready    — full readiness (relocate + garden + lint + council verdict) recorded WITHOUT
    #              activating: no single-OPEN guard, status stays `planned` ("readied"). Lets any
    #              number of waves be readied while one is OPEN.
    #   create   — readiness PLUS the single-OPEN guard PLUS the `planned`->`active` flip (prepare-and-open).
    _activating = mode_s == "create"
    _mutating = mode_s in ("create", "ready")
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            # Wave 1v0lw: zero readable matches with skipped unreadable
            # candidates is a read failure, never `wave_not_found`.
            diagnostics.append(
                _wave_resolution_unreadable_diagnostic(wave_id, unreadable_waves)
            )
            return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode_s}, next_tools=["wf_list_waves", "wf_validate_docs"], usage="wf_list_waves()")
        diagnostics.append(_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()"))
        return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode_s}, next_tools=["wf_list_waves"], usage="wf_list_waves()")
    # Wave 1v0lw: unreadable non-matching siblings are NOT appended here --
    # prepare's diagnostics list gates receipt publication, and a rotted
    # unrelated record must not silently block this wave's readiness. The
    # inspection surfaces (wf_get_change, wf_list_waves, wf_current_wave)
    # surface those siblings.
    text, wave_read_error = _read_wave_record_text(wave_md)
    if text is None:
        # A readiness gate cannot be evaluated over a record it cannot read.
        diagnostics.append(
            _wave_record_unreadable_diagnostic(root, wave_md, wave_read_error)
        )
        return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode_s}, next_tools=["wf_list_waves", "wf_validate_docs"], usage="wf_list_waves()")
    change_ids = _extract_change_ids_from_wave_text(text)
    gate_ctx = lifecycle_gates.GateContext(root, wave_md, text, mode_s, {}, "prepare")
    for gate in lifecycle_gates.PREPARE_PREFLIGHT_GATES[:2]:
        diagnostics.extend(gate(gate_ctx).diagnostics)
    repairs_needed = 0
    repaired = 0
    updated = False
    if not change_ids:
        diagnostics.append(_diagnostic("no_admitted_changes", "Wave has no admitted changes."))
    for admitted_change in change_ids:
        location_result = lifecycle_gates.PREPARE_PREFLIGHT_GATES[2](
            gate_ctx, admitted_change=admitted_change
        )
        diagnostics.extend(location_result.diagnostics)
        location = location_result.data["location"]
        change_path = location_result.data["change_path"]
        repairs_needed += int(location_result.data["needs_relocation"])
        if location_result.data["skip"]:
            continue
        if location_result.data["needs_relocation"]:
            try:
                _move_change_doc(location["staged_path"], location["wave_path"])
            except OSError as exc:
                diagnostics.append(
                    _diagnostic(
                        "change_relocation_failed",
                        f"Failed to relocate admitted change '{admitted_change}' during prepare: {exc}",
                        recovery_tools=["wf_get_change"],
                        recovery_usage=f"wf_get_change(change_id={admitted_change!r})",
                    )
                )
                continue
            repaired += 1
            updated = True
            gate_ctx.wave_text = text
        try:
            change_text = change_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            diagnostics.append(
                _diagnostic(
                    "change_doc_unreadable",
                    f"Could not read admitted change '{admitted_change}' at {_repo_rel(root, change_path)}: {_read_error_detail(exc)}",
                    recovery_tools=["wf_get_change"],
                    recovery_usage=f"wf_get_change(change_id={admitted_change!r})",
                )
            )
            continue
        diagnostics.extend(lifecycle_gates.PREPARE_PREFLIGHT_GATES[3](
            gate_ctx, admitted_change=admitted_change, change_text=change_text
        ).diagnostics)
    # Garden + lint are the last preflight before policy publication. A failed
    # docs gate must leave the roster, receipt ledger, projection, and
    # re-Prepare marker untouched.
    garden_passed = True
    lint_passed = True
    if _mutating:
        garden_result = run_garden(root)
        garden_passed = garden_result["passed"]
        diagnostics.extend(lifecycle_gates.PREPARE_PREFLIGHT_GATES[4](
            gate_ctx, garden_passed=garden_passed
        ).diagnostics)
        # Gardening may update verification metadata in the inspected packet.
        text, wave_read_error = _read_wave_record_text(wave_md)
        if text is None:
            # Readable at the gate above, unreadable after gardening; the
            # remaining preflight cannot be evaluated blind.
            diagnostics.append(
                _wave_record_unreadable_diagnostic(root, wave_md, wave_read_error)
            )
            return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode_s}, next_tools=["wf_list_waves", "wf_validate_docs"], usage="wf_list_waves()")
    lint_result = run_validate(root)
    lint_passed = lint_result["passed"]
    gate_ctx.wave_text = text
    gate_ctx.lint_result = lint_result
    diagnostics.extend(lifecycle_gates.PREPARE_PREFLIGHT_GATES[5](gate_ctx).diagnostics)

    # Policy selection/publication follows the complete docs preflight. Dry-run stays read-only.
    council_brief = _build_prepare_council_brief(wave_id, text, change_ids)
    if (
        _wave_uses_external_review_evidence(root, wave_md)
        and _read_workflow_config(root).get("wave_review") is not None
    ):
        policy_state, policy_state_errors = _prepare_policy_state(
            root, wave_md, text, change_ids, council_brief
        )
    else:
        policy_state, policy_state_errors = None, ()
    policy_response = (
        {
            key: value
            for key, value in policy_state.items()
            if key not in {"records", "policy"}
        }
        if policy_state is not None
        else None
    )
    if policy_response is not None:
        policy_response["receipt"] = {
            key: value for key, value in policy_response["receipt"].items()
            if key != "policy_inputs"
        }
    if policy_state is not None:
        # The roster is policy input.  Once a receipt exists, a later prose
        # edit to the wave record must not rotate the council underneath that
        # receipt or invalidate an already-recorded verdict.
        council_brief = _bind_prepare_council_brief_to_receipt(
            council_brief, policy_state.get("receipt")
        )
    diagnostics.extend(lifecycle_gates.PREPARE_POLICY_GATES[0](
        gate_ctx, policy_state_errors=policy_state_errors, requested_wave_id=wave_id
    ).diagnostics)
    diagnostics.extend(lifecycle_gates.PREPARE_POLICY_GATES[1](
        gate_ctx, policy_state=policy_state
    ).diagnostics)
    if _mutating and policy_state is not None and not _has_blocking_diagnostics():
        try:
            supersedes = bool(
                policy_state["receipt_append_required"]
                and policy_state["receipt"].get("supersedes_receipt_id")
            )
            text = _publish_prepare_policy_state(
                root, wave_md, text, policy_state
            )
            if supersedes:
                diagnostics.append(_diagnostic(
                    "review_policy_receipt_superseded",
                    "Readiness approvals against the old receipt are no longer current. "
                    "A lane whose remit excludes every changed document may re-record "
                    "by reference to its prior evidence; a lane whose remit includes a "
                    "changed document must review it before approving."
                    + receipt_supersession_attribution(
                        policy_state, change_ids,
                        labels=("superseded receipt", "new current receipt"),
                    ),
                    advisory=True,
                ))
            updated = True
        except (OSError, ValueError) as exc:
            diagnostics.append(
                _diagnostic(
                    "review_policy_receipt_stale",
                    f"Prepare could not publish the review-policy roster/receipt: {_read_error_detail(exc)}",
                    recovery_tools=["wf_prepare_wave"],
                    recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')",
                )
            )
    gate_ctx.wave_text = text
    council_result = lifecycle_gates.PREPARE_ACTIVATION_GATES[0](gate_ctx)
    diagnostics.extend(council_result.diagnostics)
    _prepare_authority = council_result.data["authority"]
    required_council_signoffs = council_result.data["required_council_signoffs"]
    # Discovery remains an orchestration concern; only create claims the OPEN slot.
    other_active = _find_other_active_wave(root, wave_md, cache=cache) if _activating else None
    activation_result = lifecycle_gates.PREPARE_ACTIVATION_GATES[1](
        gate_ctx, other_active=other_active, requested_wave_id=wave_id
    )
    diagnostics.extend(activation_result.diagnostics)
    guard_data = activation_result.data
    if _has_blocking_diagnostics():
        error_data = {"wave_id": wave_id, "mode": mode_s, "change_count": len(change_ids), "lint_passed": lint_passed, "garden_passed": garden_passed, "repairs_needed": repairs_needed, "repaired": repaired, "council_brief": council_brief, "review_policy": policy_response}
        error_data["required_council_signoffs"] = required_council_signoffs
        error_data.update(guard_data)
        next_tools_list = ["wf_prepare_wave", "wf_pause_wave", "wf_current_wave"] if other_active is not None else ["wf_validate_docs", "wf_current_wave"]
        usage_hint = f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')" if other_active is not None else "wf_validate_docs()"
        return _prepare_envelope("error", error_data, next_tools=next_tools_list, usage=usage_hint)
    # Prepare-phase Wave Council review — final step of wf_prepare_wave (12sp5).
    # The brief remains available on both branches. Only legacy waves consume
    # the prose verdict below; declared waves consumed typed authority above.
    verdict_info = _prepare_council_verdict_info(text)
    verdict_present = bool(verdict_info.get("present"))
    verdict_valid = bool(verdict_info.get("valid"))
    seat_alignment_issues: list[str] = []
    if not _prepare_authority.typed and verdict_present and verdict_valid:
        # Wave 1seax (1seat AC-6): a structurally valid verdict whose seats do
        # not match the brief is not a valid readiness review.
        seat_alignment_issues = _council_seat_alignment_issues(verdict_info, council_brief)
        if seat_alignment_issues:
            verdict_valid = False
    if _prepare_authority.typed:
        pass  # Readiness evidence is checked once after the verdict branches.
    elif not verdict_present:
        council_usage = (
            "Run the prepare-phase Wave Council review now (seats and scope in council_brief), "
            "record the verdict in ## Review Checkpoints with a structured 'prepare-council' line, "
            "then call wf_prepare_wave(mode='create') to complete prepare."
        )
        if _mutating:
            diagnostics.append(
                _diagnostic(
                    "prepare_council_verdict_missing",
                    "Technical checks passed. Ready to run prepare-phase Wave Council review. "
                    "Run each council seat in isolation against the admitted change docs, "
                    "record the verdict in ## Review Checkpoints with a structured 'prepare-council' line, "
                    f"then call wf_prepare_wave(mode={mode_s!r}) again to complete this step.",
                    recovery_tools=["wf_prepare_wave"],
                    recovery_usage=f"wf_prepare_wave(mode={mode_s!r})",
                )
            )
            return _prepare_envelope(
                "ready_for_council_review",
                {"wave_id": wave_id, "mode": mode_s, "council_brief": council_brief},
                next_tools=["wf_prepare_wave"],
                usage=council_usage,
            )
        # dry_run: include brief as advisory, don't block
        diagnostics.append(_diagnostic(
            "prepare_council_verdict_missing",
            "Technical checks passed. Ready to run prepare-phase Wave Council review. "
            "Run the council review and record the verdict before calling wf_prepare_wave(mode='create').",
            recovery_tools=["wf_prepare_wave"],
            recovery_usage="wf_prepare_wave(mode='create')",
            advisory=True,
        ))
    elif not verdict_valid:
        if seat_alignment_issues:
            diagnostics.append(
                _diagnostic(
                    "council_seats_misaligned",
                    "The recorded prepare-council verdict does not match the generated "
                    "brief's required seats: " + "; ".join(seat_alignment_issues) + ". "
                    "Run the missing seat(s) and update the verdict line before calling "
                    "wf_prepare_wave(mode='create').",
                    recovery_tools=["wf_prepare_wave"],
                    recovery_usage="wf_prepare_wave(mode='create')",
                )
            )
        else:
            diagnostics.append(
                _diagnostic(
                    "prepare_council_verdict_invalid",
                    "A prepare-phase Wave Council verdict exists, but it is not structurally valid: "
                    f"{verdict_info.get('parse_error') or 'check its required metadata fields'}. "
                    "Use the council_brief verdict_format template; wrapped continuation lines are allowed, and semicolons inside values are preserved before calling wf_prepare_wave(mode='create').",
                    recovery_tools=["wf_prepare_wave"],
                    recovery_usage="wf_prepare_wave(mode='create')",
                )
            )
        if mode_s == "create":
            return _prepare_envelope(
                "error",
                {
                    "wave_id": wave_id,
                    "mode": mode_s,
                    "change_count": len(change_ids),
                    "lint_passed": lint_passed,
                    "garden_passed": garden_passed,
                    "repairs_needed": repairs_needed,
                    "repaired": repaired,
                    "required_council_signoffs": required_council_signoffs,
                    "council_brief": council_brief,
                    "council_verdict_present": verdict_present,
                    "council_verdict_valid": verdict_valid,
                },
                next_tools=["wf_prepare_wave"],
                usage="wf_prepare_wave(mode='create')",
            )
    if _prepare_authority.typed or (verdict_present and verdict_valid):
        for gate in lifecycle_gates.PREPARE_READINESS_GATES:
            result = gate(gate_ctx)
            diagnostics.extend(result.diagnostics)
            configured_gates.extend(result.data.get("configured_gates", []))
    if _has_blocking_diagnostics():
        error_data = {"wave_id": wave_id, "mode": mode_s, "change_count": len(change_ids), "lint_passed": lint_passed, "garden_passed": garden_passed, "repairs_needed": repairs_needed, "repaired": repaired}
        error_data["required_council_signoffs"] = required_council_signoffs
        error_data["council_brief"] = council_brief
        error_data["council_verdict_present"] = verdict_present
        error_data["council_verdict_valid"] = verdict_valid
        return _prepare_envelope("error", error_data, next_tools=["wf_prepare_wave"], usage="wf_prepare_wave(mode='create')")
    transitioned_to_active = False
    if mode_s == "create":
        status_match = _STATUS_PATTERN.search(text)
        if status_match and status_match.group(1) != "active":
            text = text[:status_match.start(1)] + "active" + text[status_match.end(1):]
            updated = True
            transitioned_to_active = True
    if _mutating:
        try:
            projected_text = _project_current_review_status(root, wave_md, text)
        except ValueError as exc:
            diagnostics.append(_diagnostic("review_projection_failed", str(exc)))
            return _prepare_envelope(
                "error",
                {"wave_id": wave_id, "mode": mode_s},
                next_tools=["wf_review_event", "wf_validate_docs"],
            )
        live_text, live_read_error = _read_wave_record_text(wave_md)
        if live_text is None:
            # Refuse rather than blind-write a projection over a record whose
            # current content cannot be compared.
            diagnostics.append(
                _wave_record_unreadable_diagnostic(root, wave_md, live_read_error)
            )
            return _prepare_envelope("error", {"wave_id": wave_id, "mode": mode_s}, next_tools=["wf_list_waves", "wf_validate_docs"], usage="wf_list_waves()")
        if projected_text != live_text:
            wave_md.write_text(projected_text, encoding="utf-8", newline="")
            text = projected_text
            updated = True
    if mode_s == "create":
        if cache and updated:
            cache.invalidate()
        _trigger_background_index_refresh_for_paths(
            root,
            [wave_md, *(_wave_change_doc_path(root, wave_md, change_id) for change_id in change_ids)],
        )
    # Wave 1p601: only create-mode prepare-and-open refreshes the codebase map;
    # ready and dry-run modes never do (fail-safe — never affects the result).
    if mode_s == "create":
        _regenerate_codebase_map_safe(root)
    resp_data = {"wave_id": wave_id, "mode": mode_s, "readied": mode_s == "ready", "transitioned_to_active": transitioned_to_active, "change_count": len(change_ids), "lint_passed": lint_passed, "garden_passed": garden_passed, "updated": updated, "repairs_needed": repairs_needed, "repaired": repaired, "required_council_signoffs": required_council_signoffs, "council_brief": council_brief, "council_verdict_present": verdict_present, "council_verdict_valid": verdict_valid, "review_policy": policy_response}
    if transitioned_to_active:
        # Wave 1t72b (1t67p): prepare-and-open ACTIVATES the wave, so it must
        # serve the same in-band posture directive as wf_implement_wave —
        # activation without the directive was the live-demonstrated bypass.
        resp_data["retrieval_posture"] = _RETRIEVAL_POSTURE_DIRECTIVE
    # 1p8gy AC-6: prior-learning advisories before implementation begins —
    # fragile files, repeated failed attempts, operator preferences.
    _mem_advisories = _memory_advisories_for_wave(
        root, {"wave_id": wave_id, "changes": [{"id": cid} for cid in change_ids]}
    )
    if _mem_advisories:
        resp_data["memory_advisories"] = _mem_advisories
    envelope = _prepare_envelope("dry_run" if mode_s == "dry_run" else "ok", resp_data, next_tools=["wf_current_wave"], usage="wf_current_wave()")
    return _attach_lint_to_response(envelope, root, mode_s)


@_fail_closed_on_record_layout("wf_pause_wave")
def wf_pause_wave_response(root: Path, wave_id: str, mode: str = "dry_run", cache: Optional[McpRepoCache] = None) -> dict[str, Any]:
    mode_s = "create" if (mode or "").strip().lower() == "apply" else (mode or "").strip().lower()
    if mode_s not in {"dry_run", "create"}:
        return _response("error", {"wave_id": wave_id, "mode": mode}, diagnostics=[_diagnostic("invalid_arguments", f"Unsupported mode '{mode}'.")], next_tools=["wf_help"], usage="wf_help()")
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves,
                data={"wave_id": wave_id, "mode": mode_s},
            )
        return _response("error", {"wave_id": wave_id, "mode": mode_s}, diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()")], next_tools=["wf_list_waves"], usage="wf_list_waves()")
    handoff = root / "docs" / "agents" / "session-handoff.md"
    rel = str(handoff.relative_to(root)).replace("\\", "/")
    # Compute the wave-status transition. Only active → paused writes; other states are no-ops.
    wave_text, wave_read_error = _read_wave_record_text(wave_md)
    if wave_text is None:
        # Wave 1v0lw: the pause transition edits the record's Status field; a
        # record that cannot be read cannot be transitioned.
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error,
            data={"wave_id": wave_id, "mode": mode_s},
        )
    status_match = _STATUS_PATTERN.search(wave_text)
    current_status = status_match.group(1) if status_match else ""
    if current_status in ("active", "implementing"):
        status_transition = {"from": current_status, "to": "paused"}
    elif current_status == "paused":
        status_transition = {"from": "paused", "to": "paused"}
    else:
        status_transition = {"from": current_status, "to": current_status}
    diagnostics: list[dict[str, Any]] = []
    if current_status not in ("active", "implementing", "paused"):
        diagnostics.append(
            _diagnostic(
                "pause_on_non_active_wave",
                f"Wave '{wave_id}' is not active (status: {current_status!r}). Handoff entry was written but wave status was not changed.",
                recovery_tools=["wf_current_wave"],
                recovery_usage="wf_current_wave()",
            )
        )
    diagnostics.extend(_force_gates_closed(root, mode_s))
    if mode_s == "create":
        # Transition wave status first, then write the handoff entry.
        if status_transition["from"] in ("active", "implementing") and status_transition["to"] == "paused":
            new_text = wave_text[:status_match.start(1)] + "paused" + wave_text[status_match.end(1):]
            wave_md.write_text(new_text, encoding="utf-8")
        handoff.parent.mkdir(parents=True, exist_ok=True)
        prior = handoff.read_text(encoding="utf-8") if handoff.exists() else ""
        handoff.write_text(_update_handoff_wave_ref(prior, wave_id), encoding="utf-8")
        if cache:
            cache.invalidate()
        _trigger_background_index_refresh_for_paths(root, [handoff, wave_md])
    envelope = _response(
        "dry_run" if mode_s == "dry_run" else "ok",
        {
            "wave_id": wave_id,
            "mode": mode_s,
            "path": rel,
            "written": mode_s == "create",
            "status_transition": status_transition,
        },
        diagnostics=diagnostics if diagnostics else None,
        next_tools=["wf_current_wave"],
        usage="wf_current_wave()",
    )
    return _attach_lint_to_response(envelope, root, mode_s)


#: The lifecycle names two axes with sibling vocabularies: a review *phase*
#: (``prepare``/``implementation``) and an approval *phase*
#: (``readiness``/``delivery``). Callers reasonably reach for the approval word
#: when inspecting the stage that collects those approvals, so accept the
#: sibling and map it rather than rejecting a request whose intent is
#: unambiguous. ``wf_review_wave`` already maps ``prepare`` to
#: ``required_run_kind="readiness"`` internally; this makes that mapping
#: reachable from the caller side too.
_REVIEW_PHASE_ALIASES = {"readiness": "prepare", "delivery": "implementation"}


@_configured_phase_envelope
@_fail_closed_on_record_layout("wf_review_wave")
def wf_review_wave_response(root: Path, wave_id: str, phase: str = "implementation") -> dict[str, Any]:
    """Inspect canonical phase review actions.

    Receipt rotation lapses readiness approvals only; delivery approvals do not lapse solely from rotation,
    and ``review_policy_receipt_stale`` blocks implementation-phase review until
    re-Prepare without touching them.
    """
    phase_s = (phase or "implementation").strip().lower()
    phase_s = _REVIEW_PHASE_ALIASES.get(phase_s, phase_s)
    if phase_s not in ("prepare", "implementation"):
        return _response(
            "error",
            {"wave_id": wave_id, "phase": phase_s},
            diagnostics=[
                _diagnostic(
                    "invalid_arguments",
                    f"Invalid phase '{phase_s}'. Valid values: 'prepare', 'implementation'. "
                    "The approval-phase vocabulary maps onto these: 'readiness' is the "
                    "'prepare' review phase and 'delivery' is the 'implementation' review "
                    "phase; both are accepted here and mapped.",
                )
            ],
            next_tools=["wf_help"],
            usage="wf_help()",
        )
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves, data={"wave_id": wave_id}
            )
        return _response("error", {"wave_id": wave_id}, diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()")], next_tools=["wf_list_waves"], usage="wf_list_waves()")
    lint_result = run_validate(root)
    wave_text, wave_read_error = _read_wave_record_text(wave_md)
    if wave_text is None:
        # Wave 1v0lw: every review gate below reads this record; refuse rather
        # than evaluate lanes over content that cannot be read.
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error,
            data={"wave_id": wave_id, "phase": phase_s},
        )
    # Wave 1to78: every review-evidence CONTENT read below (operator/lane/
    # council signoff currency, max severity) goes through the single
    # authority facade — typed-exclusive on declared waves, prose on legacy.
    gate_ctx = lifecycle_gates.GateContext(root, wave_md, wave_text, "dry_run", lint_result, "review")
    prelude = lifecycle_gates.REVIEW_GATES[0](
        gate_ctx, review_phase=phase_s, requested_wave_id=wave_id
    )
    authority = prelude.data["authority"]
    review_evidence_diagnostics = prelude.diagnostics
    # Merge lanes from wave.md Participants table and project-declared required_review_lanes
    wave_lanes = _extract_required_review_lanes(wave_text)
    project_lanes = _read_project_required_review_lanes(root)
    extra_lanes = [l for l in project_lanes if l not in wave_lanes]
    required_lanes = (["operator"] + wave_lanes + extra_lanes) if phase_s == "implementation" else wave_lanes + extra_lanes
    empty_roster_advisory = (
        _diagnostic(
            "required_review_lanes_empty",
            "This declared wave has no required review lanes in `## Participants` "
            "or project configuration. The lane gate is intentionally non-blocking "
            "while empty; add explicit lanes when independent review is required.",
        )
        if authority.typed and not wave_lanes and not project_lanes
        else None
    )

    if phase_s == "prepare":
        # Prepare-phase: signoff currency via the authority facade (legacy
        # waves read ## Prepare Review Evidence; declared waves read typed
        # approvals only). No operator signoff required at this phase.
        diagnostics = list(review_evidence_diagnostics)
        if authority.typed and not authority.ledger_errors:
            stale_receipts = stale_readiness_receipt_ids(authority.records)
            current_receipt = current_policy_receipt(authority.records)
            if stale_receipts and current_receipt is not None:
                attributions = []
                for receipt_id in stale_receipts:
                    previous = next(
                        record for record in authority.records
                        if record.get("record_type") == "review_policy_receipt"
                        and record.get("receipt_id") == receipt_id
                    )
                    attributions.append(receipt_supersession_attribution(
                        {"receipt": current_receipt, "records": (previous,)},
                        _extract_change_ids_from_wave_text(wave_text),
                        labels=("superseded receipt", "new current receipt"),
                    ))
                diagnostics.append(_diagnostic(
                    "review_policy_receipt_superseded",
                    "Latest readiness approvals against an old receipt are no longer current. "
                    "A lane whose remit excludes every changed document may re-record "
                    "by reference to its prior evidence; a lane whose remit includes a "
                    "changed document must review it before approving."
                    + "".join(attributions),
                    advisory=True,
                ))
        diagnostics.extend(lifecycle_gates.REVIEW_GATES[1](
            gate_ctx, review_phase=phase_s
        ).diagnostics)
        lanes_result = lifecycle_gates.REVIEW_GATES[2](
            gate_ctx, review_phase=phase_s, authority=authority,
            required_lanes=required_lanes,
        )
        diagnostics.extend(lanes_result.diagnostics)
        lane_results = lanes_result.data["lane_results"]
        missing = lanes_result.data["missing"]
        if empty_roster_advisory is not None:
            diagnostics.append(empty_roster_advisory)
        action_blocker = _guided_review_authority_blocker(
            review_evidence_diagnostics
        )
        if authority.typed and not authority.ledger_errors and action_blocker is None:
            action_keys = _guided_review_signoff_keys(
                root, wave_md, wave_text, approval_phase="readiness"
            )
            review_actions, action_diagnostics = _guided_review_actions(
                authority.records,
                action_keys,
                approval_phase="readiness",
                required_run_kind="readiness",
            )
            diagnostics.extend(action_diagnostics)
        else:
            review_actions = _unavailable_guided_review_actions(
                "invalid_typed_authority"
                if authority.ledger_errors
                else action_blocker or "legacy_prose_authority"
            )
        status = "ok" if lint_result["passed"] and not missing and not review_evidence_diagnostics else "error"
        return _response(
            status,
            {"wave_id": wave_id, "phase": phase_s, "required_lanes": required_lanes, "lane_results": lane_results, "lint_passed": lint_result["passed"], "review_actions": review_actions},
            diagnostics=diagnostics,
            next_tools=["wf_implement_wave", "wf_current_wave"],
            usage=f"wf_implement_wave(wave_id={wave_id!r}, mode='dry_run')",
        )

    # Implementation phase: consume the shared delivery evaluator. Close uses
    # this exact result and then adds its registered closure-only delta.
    shared_result = lifecycle_gates.REVIEW_GATES[3](gate_ctx)
    shared = {**shared_result.data, "diagnostics": shared_result.diagnostics}
    required_lanes = ["operator", *shared["required_lanes"]]
    lane_results = [
        {"lane": "operator", "recorded_signoff": shared["operator_current"]},
        *shared["lane_results"],
    ]
    required_council_signoffs = shared["required_council_signoffs"]
    council_results = shared["council_results"]
    diagnostics = list(shared["diagnostics"])
    if empty_roster_advisory is not None:
        diagnostics.append(empty_roster_advisory)
    max_severity = shared["max_severity"]
    if max_severity in ("critical", "high"):
        diagnostics.append(_diagnostic(
            "high_severity_finding",
            f"Sensor findings include {max_severity}-severity issues — prioritise operator review of these before closing.",
            recovery_tools=["wf_current_wave"],
            recovery_usage="wf_current_wave()",
        ))
    # Wave 1t3ek (1t230): retrieval-posture sensor — advisory diagnostic only;
    # like high_severity_finding it never participates in the status computation.
    _posture_gap: Optional[dict[str, Any]] = None
    if phase_s == "implementation":
        try:
            _posture_gap = _retrieval_posture_gap(root, wave_md)
        except Exception:
            _posture_gap = None
        if _posture_gap is not None:
            diagnostics.append(_diagnostic(
                "retrieval_posture_gap",
                _posture_gap["message"],
                recovery_tools=["wf_current_wave"],
                recovery_usage="wf_current_wave()",
            ))
    if phase_s == "implementation" and shared["authority"].typed:
        for violation in repair_independence_violations(shared["authority"].records):
            if "review_context_retained" in violation:
                diagnostics.append(_diagnostic(
                    "review_context_retained", violation, advisory=True,
                    recovery_tools=["wf_review_event"],
                ))
    status = "ok" if not shared["blocking_diagnostics"] else "error"
    # 1p8gy AC-6: prior review findings and lessons relevant to this wave.
    _review_data = {"wave_id": wave_id, "phase": phase_s, "required_lanes": required_lanes, "lane_results": lane_results, "required_council_signoffs": required_council_signoffs, "council_results": council_results, "lint_passed": lint_result["passed"], "max_severity": max_severity}
    # Wave 1t3ek (1t230): the delivery council reads the implement-stage numbers
    # in-context rather than discovering them at close.
    if phase_s == "implementation":
        try:
            _stage = context_efficiency.read_wave_snapshot(
                root, wave_md.parent.name
            ).get("stages", {}).get("implement")
        except Exception:
            _stage = None
        _review_data["implement_stage_telemetry"] = {
            "stage_totals": _stage or {},
            "retrieval_calls": context_efficiency.implement_stage_retrieval_calls(
                root, wave_md.parent.name
            ),
        }
        if _posture_gap is not None:
            _review_data["retrieval_posture_gap"] = _posture_gap
    # Wave 1t72b (1t67p, operator extension): review work is retrieval work —
    # verifying claims against the tree should route through the same MCP
    # surface, so the review entry point carries the directive in-band too.
    _review_data["retrieval_posture"] = _RETRIEVAL_POSTURE_DIRECTIVE
    _mem_advisories = _memory_advisories_for_wave(
        root, {"wave_id": wave_id, "changes": [{"id": cid} for cid in _extract_change_ids_from_wave_text(wave_text)]}
    )
    if _mem_advisories:
        _review_data["memory_advisories"] = _mem_advisories
    action_blocker = _guided_review_authority_blocker(shared["diagnostics"])
    if (
        shared["authority"].typed
        and not shared["authority"].ledger_errors
        and action_blocker is None
    ):
        action_keys = _guided_review_signoff_keys(
            root, wave_md, wave_text, approval_phase="delivery"
        )
        review_actions, action_diagnostics = _guided_review_actions(
            shared["authority"].records,
            action_keys,
            approval_phase="delivery",
            required_run_kind="initial_delivery",
        )
        _review_data["review_actions"] = review_actions
        diagnostics.extend(action_diagnostics)
    else:
        _review_data["review_actions"] = _unavailable_guided_review_actions(
            "invalid_typed_authority"
            if shared["authority"].ledger_errors
            else action_blocker or "legacy_prose_authority"
        )
    return _response(
        status,
        _review_data,
        diagnostics=diagnostics,
        next_tools=["wf_validate_docs", "wf_current_wave"],
        usage="wf_validate_docs()",
    )


# Wave 1t3ek (1t230): the retrieval-posture loop. The directive travels in-band
# on the activation envelope (self-contained: rule + escape hatch + consequence),
# and the gap sensor fires at implementation review / close dry-run when
# implement-stage retrieval telemetry is near zero against a non-trivial code
# diff. A recorded "Gapfill:" entry clears the advisory; it never blocks.
_RETRIEVAL_POSTURE_DIRECTIVE = (
    "MCP-first retrieval during implementation AND review: search, read, and "
    "navigate code through the code_* and docs_search tools first, while "
    "implementing changes and equally while verifying review claims against "
    "the tree; harness shell and file search are fallback. This scope includes "
    "repair and reverification work inside review cycles (censuses, region "
    "reads, claim checks); executed probes (test runs, mutation probes, git "
    "operations) remain shell work. Carry this same posture into the prompt "
    "of any subagent briefed for investigation or verification. When fallback "
    "is genuinely the right instrument (bulk-mechanical edits, docs-only "
    "work), record a 'Gapfill:' entry in a Progress Log explaining why. That "
    "same recorded entry clears the retrieval_posture_gap advisory raised at "
    "implementation review and close when implement-stage retrieval telemetry "
    "is near zero against a non-trivial code diff."
)

# Test seam: replace to drive the footprint without a real git history.
_FOOTPRINT_PROVIDER: Optional[Callable[[Path], Optional[int]]] = None

_FOOTPRINT_EXCLUDE_PREFIXES = ("docs/", ".wavefoundry/index/", ".wavefoundry/logs/")


def _wave_code_footprint(root: Path, wave_md: Path) -> Optional[int]:
    """Count changed non-doc files within this wave's declared footprint.

    An implementation advisory must not turn unrelated working-tree dirt into
    evidence about this wave.  Use the admitted change docs' Serialization
    Points as the bounded file universe; a wave with no declared targets has no
    trustworthy file-count signal and stays silent.
    """
    if _FOOTPRINT_PROVIDER is not None:
        return _FOOTPRINT_PROVIDER(root)
    targets: list[str] = []
    # Wave 1v0lw: the record read routes through the seam; the advisory
    # degrades to None on any read failure exactly as before.
    wave_text, _wave_read_error = _read_wave_record_text(wave_md)
    if wave_text is None:
        return None
    try:
        for change_id in _extract_change_ids_from_wave_text(wave_text):
            change = _wave_change_doc_path(root, wave_md, change_id)
            targets.extend(serialization_point_paths(change.read_text(encoding="utf-8")))
    except (OSError, UnicodeError):
        return None
    if not targets:
        return None

    # `serialization_point_paths` already lowercases declared targets, but
    # `git status --porcelain` preserves case. Only the git side needs folding;
    # comparing raw `rel` against a lowercased target silently dropped every
    # PascalCase declaration, so a TypeScript, Java, or C# repository
    # undercounted its own declared footprint while the advisory still claimed
    # to describe it. Folding the target side too would be a no-op, so it is
    # deliberately not done: a reader should be able to see which side carries
    # the behavior. The tradeoff accepted here is that on a case-sensitive
    # filesystem holding both `src/Foo.ts` and `src/foo.ts`, declaring one
    # counts the other. That inflates an advisory counter and never a gate,
    # which is the lesser harm against dropping every PascalCase target.
    def in_wave_footprint(rel: str) -> bool:
        probe = rel.casefold()
        return any(
            probe == target or (target.endswith("/") and probe.startswith(target))
            for target in targets
        )

    try:
        proc = subprocess_util.isolated_run(
            ["git", "-C", str(root), "status", "--porcelain"],
            capture_output=True, text=True, timeout=10, check=False,
        )
    except Exception:
        return None
    if proc.returncode != 0:
        return None
    count = 0
    for line in proc.stdout.splitlines():
        if len(line) < 4:
            continue
        rel = line[3:].strip()
        # Git uses ``old -> new`` in porcelain rename entries, and quotes each
        # side INDEPENDENTLY when it contains a space. Split on the arrow
        # before unquoting: stripping quotes first leaves the surviving inner
        # quote on ``R  "src/a b/old.py" -> "src/a b/new.py"``, so the target
        # never matched. Unreachable until spaced targets became declarable,
        # which is what makes it this change's problem.
        if " -> " in rel:
            rel = rel.rsplit(" -> ", 1)[-1].strip()
        rel = rel.strip('"')
        if not rel or rel.endswith("/"):
            continue
        if any(rel.startswith(prefix) for prefix in _FOOTPRINT_EXCLUDE_PREFIXES):
            continue
        if in_wave_footprint(rel):
            count += 1
    return count


def _retrieval_posture_thresholds(root: Path) -> tuple[int, int]:
    """(max_retrieval_calls, min_changed_files) — conservative defaults, tunable
    via workflow-config ``sensors.retrieval_posture``."""
    max_calls, min_files = 0, 5
    cfg = _read_workflow_config(root)
    sensors = cfg.get("sensors") if isinstance(cfg, dict) else None
    posture = sensors.get("retrieval_posture") if isinstance(sensors, dict) else None
    if isinstance(posture, dict):
        try:
            max_calls = int(posture.get("max_retrieval_calls", max_calls))
        except (TypeError, ValueError):
            pass
        try:
            min_files = int(posture.get("min_changed_files", min_files))
        except (TypeError, ValueError):
            pass
    return max_calls, min_files


def _wave_has_gapfill_note(wave_md: Path) -> bool:
    # Per-document, and catching decode failures too: an `except OSError` around
    # the whole loop let one undecodable change doc abort the scan, and because
    # both call sites wrap this in `except Exception` the effect was to silently
    # disable the retrieval-posture sensor rather than to crash visibly.
    # The loop's targets include the wave record itself, so each read routes
    # through the 1v0lw seam; an unreadable document still skips per-document.
    for doc in sorted(wave_md.parent.glob("*.md")):
        doc_text, _doc_read_error = _read_wave_record_text(doc)
        if doc_text is not None and "Gapfill:" in doc_text:
            return True
    return False


def _retrieval_posture_gap(root: Path, wave_md: Path) -> Optional[dict[str, Any]]:
    """Return the gap payload, or None when the sensor has nothing to say.

    Fires only when ALL hold: the store is readable, implement-stage retrieval
    calls are at or below the threshold, the changed-file footprint is at or
    above its threshold, and no Gapfill entry is recorded in the wave.
    """
    # Wave 1t72b (1t67p): the gap DECISION counts only the code-retrieval
    # census — an incidental wrapped lifecycle call (live-demonstrated:
    # one wf_sync_surfaces probe) must never mask a code-exploration drought.
    calls = context_efficiency.implement_stage_retrieval_calls(
        root, wave_md.parent.name, tool_names=_CONTEXT_RETRIEVAL_TOOLS
    )
    if calls is None:
        return None
    max_calls, min_files = _retrieval_posture_thresholds(root)
    if calls > max_calls:
        return None
    footprint = _wave_code_footprint(root, wave_md)
    if footprint is None or footprint < min_files:
        return None
    if _wave_has_gapfill_note(wave_md):
        return None
    return {
        "implement_stage_retrieval_calls": calls,
        "changed_non_docs_files": footprint,
        "message": (
            f"Implement-stage instrumented retrieval calls: {calls}; changed "
            f"non-docs files within this wave's declared footprint: {footprint}. Implementation "
            "appears to have bypassed the MCP retrieval tools (code_*, "
            "docs_search). Route exploration through them, or record a "
            "'Gapfill:' entry in a Progress Log explaining why harness "
            "fallback was the right instrument; the recorded entry clears "
            "this advisory."
        ),
    }


@_fail_closed_on_record_layout("wf_implement_wave")
def wf_implement_wave_response(root: Path, wave_id: str, mode: str = "dry_run", cache: Optional[McpRepoCache] = None) -> dict[str, Any]:
    """Gate and context builder for starting wave implementation (12sqb).

    Checks:
    1. Wave is OPEN-able — `active` (legacy prepare-and-open) or a readied `planned`
       wave (wave 1p45l); not already implementing, not paused/closed/blocked.
    2. Automated prepare-phase Wave Council verdict is recorded (12sp5).
    3. All required prepare-phase lane reviews are recorded in ## Prepare Review Evidence.
    4. Single-OPEN guard (wave 1p45l): no OTHER wave is already active/implementing.

    On create: runs the single-OPEN guard, then transitions wave status to 'implementing'.
    Returns ordered change list, watchpoints, and serialization points.
    """
    mode_s = "create" if (mode or "").strip().lower() == "apply" else (mode or "").strip().lower()
    _VALID_MODES = ["dry_run", "create"]
    if mode_s not in _VALID_MODES:
        return _response("error", {"wave_id": wave_id, "mode": mode, "valid_modes": _VALID_MODES}, diagnostics=[_diagnostic("invalid_arguments", f"Unsupported mode '{mode}'. Valid modes: {_VALID_MODES}.")], next_tools=["wf_help"], usage="wf_help()")
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves, data={"wave_id": wave_id}
            )
        return _response("error", {"wave_id": wave_id}, diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()")], next_tools=["wf_list_waves"], usage="wf_list_waves()")

    wave_text, wave_read_error = _read_wave_record_text(wave_md)
    if wave_text is None:
        # Wave 1v0lw: the OPEN gate reads status, council verdict, and lane
        # evidence from this record; activation over an unreadable record is
        # fail-open.
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error,
            data={"wave_id": wave_id, "mode": mode_s},
        )
    status_match = _STATUS_PATTERN.search(wave_text)
    current_status = (status_match.group(1) if status_match else "").lower()

    if current_status == "implementing":
        return _response("ok", {"wave_id": wave_id, "mode": mode_s, "status": "implementing", "already_implementing": True, "transitioned_to_implementing": False}, next_tools=["wf_current_wave", "wf_review_wave"], usage="wf_current_wave()")
    # Wave 1p45l: implement opens an `active` wave (legacy prepare-and-open) OR a readied
    # `planned` wave.
    if current_status not in ("active", "planned"):
        return _response(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "status": current_status},
            diagnostics=[_diagnostic("wave_not_active", f"wf_implement_wave requires an `active` or readied `planned` wave; '{wave_id}' has status '{current_status}'. Prepare it (`wf_prepare_wave(mode='ready')`), or resume it if paused.", recovery_tools=["wf_prepare_wave", "wf_current_wave"], recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')")],
            next_tools=["wf_prepare_wave", "wf_current_wave"],
            usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')",
        )

    diagnostics: list[dict[str, Any]] = []
    diagnostics.extend(_wave_review_policy_diagnostics(root))
    diagnostics.extend(
        _review_policy_receipt_diagnostics(root, wave_md, wave_text)
    )
    if has_reprepare_marker(wave_text):
        diagnostics.append(
            _diagnostic(
                "review_policy_reprepare_required",
                "This wave must be re-Prepared before implementation.",
                recovery_tools=["wf_prepare_wave"],
                recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='ready')",
            )
        )

    # Gate 1: readiness authority. Declared waves consume the current typed
    # readiness approval; prose cannot forge it. Legacy waves preserve the
    # structural prepare-council contract byte-for-byte.
    _activation_authority = resolve_review_authority(root, wave_md, wave_text=wave_text)
    if _activation_authority.typed:
        _readiness_keys = _required_wave_council_signoffs(
            root, "prepare", wave_text=wave_text, wave_md=wave_md
        )
        if (
            not _readiness_keys
            and _read_workflow_config(root).get("wave_review") is None
        ):
            _readiness_keys = ["wave-council-readiness"]
        _missing_readiness = [
            key for key in _readiness_keys
            if not _activation_authority.signoff_current(
                key, approval_phase="readiness"
            )
        ]
        if _missing_readiness:
            diagnostics.append(_diagnostic(
                "missing_wave_council_signoff",
                "Required typed readiness approval missing or stale for implementation: "
                f"{', '.join(_missing_readiness)}. Record the approval through "
                "wf_review_event before calling wf_implement_wave; a prose "
                "prepare-council line is not authority on a declared wave.",
                recovery_tools=["wf_review_wave", "wf_review_event"],
                recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase='prepare')",
            ))
    else:
        verdict_info = _prepare_council_verdict_info(wave_text)
        if not verdict_info.get("present"):
            diagnostics.append(_diagnostic(
                "prepare_council_verdict_missing",
                "No prepare-phase Wave Council verdict found in `## Review Checkpoints`. "
                "Run the council review (red-team fixed seat + rotating seat) and record the verdict "
                "with a structured 'prepare-council' line before calling wf_implement_wave.",
                recovery_tools=["wf_prepare_wave", "wf_current_wave"],
                recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='dry_run')",
            ))
        elif not verdict_info.get("valid"):
            diagnostics.append(_diagnostic(
                "prepare_council_verdict_invalid",
                "A prepare-phase Wave Council verdict was found, but it is not structurally valid. "
                "Record a structured verdict with moderator, primer-depth, seats, rotating-seat, strongest-challenge, and strongest-alternative before calling wf_implement_wave.",
                recovery_tools=["wf_prepare_wave", "wf_current_wave"],
                recovery_usage=f"wf_prepare_wave(wave_id={wave_id!r}, mode='dry_run')",
            ))

    # Gate 2: prepare-phase lane review — signoff currency via the authority
    # facade (wave 1to78): typed-exclusive on declared waves, `## Prepare
    # Review Evidence` prose on legacy waves. The roster parse stays prose.
    _gate2_authority, missing_lanes = _prepare_lane_review_state(root, wave_md, wave_text)
    if missing_lanes:
        # Wave 1to78 delivery repair (DF2, message-only): remediation
        # text branches on the resolved authority (predicate unchanged).
        # Tests assert the typed wording on a declared fixture and the
        # legacy wording on prose fixtures.
        if _gate2_authority.typed:
            _gate2_message = (
                f"Prepare-phase lane review incomplete; lanes without a current typed approval: {', '.join(missing_lanes)}. "
                "Run wf_review_wave(phase='prepare') and record a typed approval event per lane via "
                "wf_review_event(event='approval', signoff_key=<lane name above>, mode='create') "
                "before calling wf_implement_wave."
            )
        else:
            _gate2_message = (
                f"Prepare-phase lane review incomplete — missing signoffs in `## Prepare Review Evidence`: {', '.join(missing_lanes)}. "
                "Run wf_review_wave(phase='prepare') and record each lane signoff before calling wf_implement_wave."
            )
        diagnostics.append(_diagnostic(
            "prepare_review_incomplete",
            _gate2_message,
            recovery_tools=["wf_review_wave", "wf_current_wave"],
            recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase='prepare')",
        ))

    # Gate 3 (wave 1p45l): single-OPEN guard — at most one wave may be OPEN (active/implementing).
    # This is the relocated single-OPEN enforcement point; readiness paths (prepare ready/dry_run)
    # no longer guard. `_find_other_active_wave` excludes the target wave, so opening a wave that
    # is already `active` (legacy flow) is not blocked by itself.
    other_open = _find_other_active_wave(root, wave_md, cache=cache)
    if other_open is not None:
        diagnostics.append(_diagnostic(
            "another_wave_active",
            f"Wave {other_open['wave_id']!r} is already OPEN (active/implementing); only one wave may be OPEN at a time. "
            f"Pause it before opening {wave_id!r}.",
            recovery_tools=["wf_pause_wave", "wf_current_wave"],
            recovery_usage=f"wf_pause_wave(wave_id={other_open['wave_id']!r}, mode='create')",
        ))

    if diagnostics:
        return _response("error", {"wave_id": wave_id, "mode": mode_s}, diagnostics=diagnostics, next_tools=["wf_review_wave", "wf_current_wave"], usage=f"wf_review_wave(wave_id={wave_id!r}, phase='prepare')")

    # All gates passed — build implementation context
    change_ids = _extract_change_ids_from_wave_text(wave_text)

    # The wave record owns dependency declarations. Legacy change-doc lines
    # remain a secondary source; prose and workstream tables are not a grammar.
    dependency_advisories: list[dict[str, Any]] = []
    wave_dependencies: dict[str, list[str]] = {}
    changes_match = re.search(r"(?ms)^## Changes[ \t]*\n(.*?)(?=^## |\Z)", wave_text)
    owner = None
    for line in (changes_match.group(1) if changes_match else "").splitlines():
        change_match = re.fullmatch(r"Change ID:[ \t]*`([^`]+)`[ \t]*", line)
        if change_match:
            owner = change_match.group(1)
        elif owner and re.match(r"^Depends On:[ \t]+", line):
            wave_dependencies.setdefault(owner, []).extend(re.findall(r"`([^`]+)`", line))

    def resolve_dependencies(cid: str, tokens: list[str], *, legacy: bool) -> list[str]:
        resolved = []
        for token in tokens:
            matches = ([token] if token in change_ids else
                       [item for item in change_ids if item.startswith(token)] if legacy else [])
            if len(matches) == 1:
                if matches[0] not in resolved:
                    resolved.append(matches[0])
            else:
                dependency_advisories.append(_diagnostic(
                    "unresolved_change_dependency",
                    f"Change `{cid}` declares unresolved dependency `{token}`; "
                    "use a full admitted change id in the wave record.",
                    advisory=True,
                ))
        return resolved

    # Preserve admission order; dependencies describe serialization, not a sort.
    ordered_changes: list[dict[str, Any]] = []
    for cid in change_ids:
        change_path = wave_md.parent / f"{cid}.md"
        if not change_path.exists():
            ordered_changes.append({"change_id": cid, "status": "unknown", "depends_on": []})
            continue
        try:
            ct = change_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            return _response(
                "error",
                {"wave_id": wave_id, "mode": mode_s},
                diagnostics=[_diagnostic(
                    "change_doc_unreadable",
                    f"Could not read admitted change '{cid}' at {_repo_rel(root, change_path)}: {_read_error_detail(exc)}",
                    recovery_tools=["wf_validate_docs"],
                    recovery_usage="wf_validate_docs()",
                )],
                next_tools=["wf_validate_docs", "wf_current_wave"],
                usage="wf_validate_docs()",
            )
        status_m = _CHANGE_STATUS_PATTERN.search(ct)
        cs = status_m.group(1) if status_m else "unknown"
        tokens = wave_dependencies.get(cid)
        if tokens is None:
            tokens = [token for line in ct.splitlines()
                      if re.fullmatch(r"Depends On:[ \t]+`[^`]+`(?:[ \t]*,[ \t]*`[^`]+`)*[ \t]*", line)
                      for token in re.findall(r"`([^`]+)`", line)]
            deps = resolve_dependencies(cid, tokens, legacy=True)
        else:
            deps = resolve_dependencies(cid, tokens, legacy=False)
        ordered_changes.append({"change_id": cid, "status": cs, "depends_on": deps})

    # Watchpoints section — new scaffolds use `## Watchpoints` (wave 1t9w9);
    # existing waves keep the legacy `## Journal Watchpoints` heading forever.
    watchpoints_text = ""
    for heading in ("## Watchpoints", "## Journal Watchpoints"):
        wp_idx = wave_text.find(heading)
        if wp_idx == -1:
            continue
        tail = wave_text[wp_idx + len(heading):]
        nl = tail.find("\n")
        if nl != -1:
            tail = tail[nl + 1:]
        m_end = re.search(r"\n(?=## )", tail)
        watchpoints_text = (tail[: m_end.start()] if m_end else tail).strip()
        break

    # Serialization points: changes that other changes depend on
    all_deps: set[str] = set()
    for c in ordered_changes:
        all_deps.update(c["depends_on"])
    serialization_points = [cid for cid in change_ids if cid in all_deps]

    if mode_s == "create":
        new_text = wave_text[:status_match.start(1)] + "implementing" + wave_text[status_match.end(1):]
        wave_md.write_text(new_text, encoding="utf-8")
        if cache:
            cache.invalidate()

    resp_data = {
        "wave_id": wave_id,
        "mode": mode_s,
        "transitioned_to_implementing": mode_s == "create",
        "status_transition": {"from": current_status, "to": "implementing"} if mode_s == "create" else {"from": current_status, "to": f"{current_status} (dry_run)"},
        "ordered_changes": ordered_changes,
        "watchpoints": watchpoints_text,
        "serialization_points": serialization_points,
        # Wave 1t3ek (1t230): the retrieval directive arrives in-band at the
        # exact moment implementation starts, not only in a prompt doc.
        "retrieval_posture": _RETRIEVAL_POSTURE_DIRECTIVE,
    }
    envelope = _response(
        "dry_run" if mode_s == "dry_run" else "ok",
        resp_data,
        diagnostics=dependency_advisories,
        next_tools=(["wf_mark_ac", "wf_mark_task", "wf_review_wave", "wf_current_wave"]
                    if mode_s == "create" else ["wf_current_wave", "wf_review_wave"]),
        usage=("wf_mark_ac / wf_mark_task require the FULL change id from ordered_changes[].change_id; "
               "prefixes are not resolved." if mode_s == "create" else "wf_current_wave()"),
    )
    return _attach_lint_to_response(envelope, root, mode_s)


def _load_scan_findings(root: Path) -> list[dict]:
    path = root / "docs" / "scan-findings.json"
    if not path.exists():
        return []
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _check_secrets_gate(root: Path, canonical_wave_id: str) -> list[dict]:
    """Return blocking diagnostic dicts for the wf_close_wave secrets gate.

    Hard-block (must be classified before close): any entry with status
    'pending' or 'suspected-secret' — these are unresolved and must be
    classified to 'confirmed-secret' (real) or 'false-positive' (not real).

    Wave 1p5pz: 'confirmed-secret' findings no longer block close — they are a
    real, classified, tracked secret surfaced as a non-blocking standing
    reminder (see _confirmed_secret_notice). The per-wave acknowledged_for_wave
    / override_reason soft-block was dropped; classification IS the
    acknowledgment. 'false-positive' clears silently. Legacy findings that still
    carry acknowledged_for_wave / override_reason are tolerated (ignored).
    """
    diagnostics: list[dict] = []
    exceptions = _load_scan_findings(root)
    if not exceptions:
        return diagnostics

    # Fail-closed: only 'false-positive' (not a real secret) and 'confirmed-secret'
    # (real, classified — non-blocking + reminded) clear close. 'pending',
    # 'suspected-secret', and any unknown/missing status are unresolved and
    # hard-block — an unrecognized status must never slip through unblocked.
    unresolved = [
        e for e in exceptions
        if e.get("status") not in ("false-positive", "confirmed-secret")
    ]
    if unresolved:
        lines = "\n".join(
            f"  [{e.get('id', '?')}] {e.get('file', '?')}:{e.get('line', '?')}  rule: {e.get('rule_id', '?')}  status: {e.get('status', '?')}"
            for e in unresolved
        )
        diagnostics.append(_diagnostic(
            "secrets_gate_unresolved",
            (
                f"SECRETS GATE — {len(unresolved)} unresolved finding(s) must be classified before close:\n\n"
                f"{lines}\n\n"
                "To proceed: run the security reviewer (seed-213), which will classify each as "
                "'confirmed-secret' (a real secret — tracked, non-blocking) or 'false-positive' "
                "(not a real secret). Then re-run wf_close_wave. Never label a real secret "
                "'false-positive'."
            ),
            recovery_tools=["wf_review_wave"],
            recovery_usage=f"wf_review_wave(wave_id={canonical_wave_id!r})",
        ))

    return diagnostics


def _confirmed_secret_notice(root: Path) -> dict[str, Any] | None:
    """Build a non-blocking standing reminder of 'confirmed-secret' findings.

    Wave 1p5pz: confirmed secrets do not block wf_close_wave; instead EVERY close
    surfaces this reminder in the response ``data`` so the agent presents it to
    the operator. Returns None when there are no confirmed-secret findings.
    """
    confirmed = [
        e for e in _load_scan_findings(root)
        if e.get("status") == "confirmed-secret"
    ]
    if not confirmed:
        return None
    items = [
        {
            "id": e.get("id", "?"),
            "file": e.get("file", "?"),
            "line": e.get("line", "?"),
            "rule_id": e.get("rule_id", "?"),
        }
        for e in confirmed
    ]
    lines = "\n".join(f"  [{i['id']}] {i['file']}:{i['line']}  rule: {i['rule_id']}" for i in items)
    reminder = (
        f"NOTE — {len(confirmed)} confirmed secret(s) are tracked in this project "
        "(docs/scan-findings.json). These do NOT block wave close; this is a standing "
        "reminder to rotate/remove them before distribution. Present this to the operator:\n\n"
        f"{lines}"
    )
    return {"confirmed_secrets": items, "secrets_reminder": reminder}


def _generate_wf_close_wave_summary(wave_id: str, wave_text: str, wave_md: Path) -> str:
    """Synthesize a wave close summary from structured fields in the wave record and change docs.

    Format: one or more prose paragraphs followed by optional per-change bullet points.
    Reads completed ACs ([x] lines), progress log entries, and decision log entries from
    each admitted change doc. Does not require operator input.
    """
    # Extract wave title
    title_m = re.search(r"^Title:\s*(.+)$", wave_text, re.MULTILINE)
    wave_title = title_m.group(1).strip() if title_m else wave_id

    change_ids = _extract_change_ids_from_wave_text(wave_text)

    def _section_body(text: str, heading: str) -> str:
        idx = text.find(heading)
        if idx == -1:
            return ""
        tail = text[idx + len(heading):]
        nl = tail.find("\n")
        if nl != -1:
            tail = tail[nl + 1:]
        m = re.search(r"\n(?=## )", tail)
        return (tail[: m.start()] if m else tail).strip()

    change_summaries: list[dict] = []
    for cid in change_ids:
        change_path = wave_md.parent / f"{cid}.md"
        if not change_path.exists():
            # 1v0lx: the close hard gate blocks a missing admitted document
            # before summary generation; if the file vanishes in the window
            # between the gate and this read, fail closed like the unreadable
            # sibling below rather than fabricate an empty record of a
            # document that does not exist.
            raise ValueError(
                f"Missing admitted change '{cid}': no file at "
                f"{wave_md.parent.name}/{change_path.name}; restore the "
                "document or remove the change via wf_remove_change"
            )
        try:
            ct = change_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            # Wave-relative, not absolute: this string reaches the operator in a
            # close diagnostic, and the function has no repo root to hand to
            # `_repo_rel`.  The document is always a sibling of `wave_md`.
            # `_read_error_detail` strips the absolute path an OSError's str
            # embeds; the wave-relative form above is the only path rendered.
            raise ValueError(
                f"Could not read admitted change '{cid}' at "
                f"{wave_md.parent.name}/{change_path.name}: "
                f"{_read_error_detail(exc)}"
            ) from exc
        # Title from H1
        h1_m = re.search(r"^#\s+(.+)$", ct, re.MULTILINE)
        title = h1_m.group(1).strip() if h1_m else cid
        # Completed ACs: [x] lines in Acceptance Criteria
        ac_body = _section_body(ct, "## Acceptance Criteria")
        completed_acs = [line.strip()[5:].strip() for line in ac_body.splitlines() if re.match(r"\s*-\s*\[x\]", line, re.IGNORECASE)]
        # Progress log: data rows (skip header)
        progress_body = _section_body(ct, "## Progress Log")
        progress_entries = []
        for row in progress_body.splitlines():
            cells = [c.strip() for c in row.strip("|").split("|")]
            if len(cells) >= 2 and cells[0] and cells[0].lower() != "date" and not re.fullmatch(r":?-+:?", cells[0]):
                progress_entries.append(cells[1] if len(cells) > 1 else "")
        # Decision log: data rows
        decision_body = _section_body(ct, "## Decision Log")
        decision_entries = []
        for row in decision_body.splitlines():
            cells = [c.strip() for c in row.strip("|").split("|")]
            if len(cells) >= 2 and cells[0] and cells[0].lower() != "date" and not re.fullmatch(r":?-+:?", cells[0]):
                decision_entries.append(cells[1] if len(cells) > 1 else "")
        change_summaries.append({"id": cid, "title": title, "completed_acs": completed_acs, "decisions": decision_entries, "progress": progress_entries})

    # Compose prose paragraph
    if change_summaries:
        titles = [cs["title"] for cs in change_summaries]
        if len(titles) == 1:
            delivered = f"one change: {titles[0]}"
        elif len(titles) == 2:
            delivered = f"two changes: {titles[0]} and {titles[1]}"
        else:
            delivered = f"{len(titles)} changes: {', '.join(titles[:-1])}, and {titles[-1]}"
        para = f"Wave `{wave_id}` ({wave_title}) delivered {delivered}."
    else:
        para = f"Wave `{wave_id}` ({wave_title}) closed with no admitted changes."

    # Notable pivots from progress logs
    pivots: list[str] = []
    for cs in change_summaries:
        for entry in cs["progress"]:
            lower = entry.lower()
            if any(kw in lower for kw in ("renamed", "removed", "consolidated", "added", "scope", "pivot", "revert", "expanded")):
                pivots.append(f"{cs['title']}: {entry}")
    if pivots:
        para += " Notable adjustments during implementation: " + "; ".join(pivots[:3]) + ("." if not pivots[0].endswith(".") else "")

    lines = [para, ""]

    # Per-change bullet points if there are decisions or completed ACs worth surfacing
    any_detail = any(cs["decisions"] or cs["completed_acs"] for cs in change_summaries)
    if any_detail and change_summaries:
        lines.append("**Changes delivered:**")
        lines.append("")
        for cs in change_summaries:
            ac_count = len(cs["completed_acs"])
            decisions = cs["decisions"]
            bullet = f"- **{cs['title']}** (`{cs['id']}`)"
            if ac_count:
                bullet += f" — {ac_count} AC{'s' if ac_count != 1 else ''} completed"
            if decisions:
                bullet += (". Key decisions: " if ac_count else " — ") + "; ".join(decisions[:2])
            lines.append(bullet)

    return "\n".join(lines)


def _replace_wave_summary_section(text: str, summary: str) -> str:
    """Replace the content of ## Wave Summary with the generated summary."""
    marker = "## Wave Summary"
    idx = text.find(marker)
    if idx == -1:
        return text
    # Find end of section (next ## heading or end of file)
    tail_start = idx + len(marker)
    nl = text.find("\n", tail_start)
    if nl != -1:
        body_start = nl + 1
    else:
        body_start = tail_start
    tail = text[body_start:]
    m_end = re.search(r"\n(?=## )", tail)
    body_end = body_start + (m_end.start() + 1 if m_end else len(tail))
    return text[:body_start] + "\n" + summary + "\n" + text[body_end:]


def _auto_populate_memory_for_wave(root: Path, wave_id: str) -> dict[str, Any]:
    """Fail-isolated close fallback: create candidates, never semantic verdicts."""
    try:
        result = memory_propose_response(
            root, wave_id=wave_id, mode="create", limit=MEMORY_PROPOSE_CAP
        )
        data = result.get("data") or {}
        written = list(data.get("written") or [])
        if not written:
            return {}
        return {
            "drafted": len(written), "promoted": 0,
            "candidate": len(written), "validation_required": len(written),
            "records": written,
        }
    except Exception:
        return {}


def _memory_validation_diagnostics(root: Path, wave_id: str) -> list[dict[str, Any]]:
    """Block close until every structurally eligible source has an agent verdict."""
    try:
        supply = _load_script("memory_supply")
        mem = _memory_mod()
        # Closure is an exhaustive gate, not a display page.
        drafts = supply.draft_candidates(root, wave_id, limit=None)
        if not drafts:
            return []
        by_source: dict[str, list[dict[str, Any]]] = {}
        for record in mem.load_memory_records(root):
            source = str(record.get("source_event") or "")
            if source:
                by_source.setdefault(source, []).append(record)
        missing = [
            draft["source_event"] for draft in drafts
            if draft["source_event"] not in by_source
        ]
        pending = [
            record["memory_id"]
            for draft in drafts
            for record in by_source.get(draft["source_event"], [])
            if record.get("validation") in (None, "pending")
        ]
        diagnostics: list[dict[str, Any]] = []
        if missing:
            diagnostics.append(_diagnostic(
                "memory_validation_candidates_missing",
                f"{len(missing)} evidence-derived memory source(s) need candidate "
                "records before close. Zero-memory waves remain valid when drafting "
                "finds no material source.",
                recovery_tools=["memory_propose"],
                recovery_usage=f"memory_propose(wave_id={wave_id!r}, mode='create')",
            ))
        if pending:
            diagnostics.append(_diagnostic(
                "memory_validation_required",
                f"{len(pending)} evidence-derived memory candidate(s) need focused "
                "agent validation before close: " + ", ".join(pending[:10]),
                recovery_tools=["memory_validate", "memory_search"],
                recovery_usage=(
                    "memory_validate(memory_id=<id>, verdict='promote|retain|"
                    "reject|rewrite', action_delta=..., rationale=..., "
                    "evidence_verified=True, current_target_verified=True, "
                    "canonical_overlap='none|supplements|duplicates')"
                ),
            ))
        return diagnostics
    except Exception as exc:
        return [_diagnostic(
            "memory_validation_check_failed",
            f"Memory validation readiness could not be established: {exc}",
            recovery_tools=["memory_propose", "wf_validate_docs"],
            recovery_usage=f"memory_propose(wave_id={wave_id!r}, mode='dry_run')",
        )]


# Wave 1wur7 (1wuui Requirement 5): close VERIFIES the existing framework test
# receipt.  It runs no suite and spawns no subprocess.
# run_tests.py sets this on import for its own subprocesses.  The close gate only
# borrows the module's hash computation, so both of its import side effects are
# restored rather than leaked into a long-lived server process.


@_configured_phase_envelope
@_fail_closed_on_record_layout("wf_close_wave")
def wf_close_wave_response(root: Path, wave_id: str, mode: str = "dry_run", cache: Optional[McpRepoCache] = None) -> dict[str, Any]:
    from scanner_skips import scanner_skip_notice

    configured_gates: list[dict[str, Any]] = []

    def _close_envelope(status, data, **kwargs):
        return _response(status, {**data, "configured_gates": configured_gates}, **kwargs)

    mode_s = "create" if (mode or "").strip().lower() == "apply" else (mode or "").strip().lower()
    _WAVE_CLOSE_VALID_MODES = ["dry_run", "create"]
    if mode_s not in {"dry_run", "create"}:
        return _close_envelope("error", {"wave_id": wave_id, "mode": mode, "valid_modes": _WAVE_CLOSE_VALID_MODES}, diagnostics=[_diagnostic("invalid_arguments", f"Unsupported mode '{mode}'. Valid modes: {_WAVE_CLOSE_VALID_MODES}.")], next_tools=["wf_help"], usage="wf_help()")
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves, data={"wave_id": wave_id}
            )
        return _close_envelope("error", {"wave_id": wave_id}, diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()")], next_tools=["wf_list_waves"], usage="wf_list_waves()")
    # Garden only runs on create — dry-run must stay read-only.
    garden_passed = True
    if mode_s == "create":
        garden_result = run_garden(root)
        garden_passed = garden_result["passed"]
    lint_result = run_validate(root)
    # Wave 1v0lw: the read keeps its post-garden position (gardening may
    # refresh record metadata) and routes through the seam; the close hard
    # gate cannot be evaluated over a record that cannot be read.
    text, wave_read_error = _read_wave_record_text(wave_md)
    if text is None:
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error,
            data={"wave_id": wave_id, "mode": mode_s},
        )
    gate_ctx = lifecycle_gates.GateContext(root, wave_md, text, mode_s, lint_result, "close")
    shared_result = lifecycle_gates.CLOSE_SHARED_GATES[0](gate_ctx)
    shared = {**shared_result.data, "diagnostics": shared_result.diagnostics}
    authority = shared["authority"]
    statuses = [status.lower() for status in _CHANGE_STATUS_PATTERN.findall(text)]
    open_statuses = {"stub", "planned", "ready", "active"}
    unresolved = [s for s in statuses if s in open_statuses]
    diagnostics: list[dict[str, Any]] = list(shared["diagnostics"])
    diagnostics.extend(lifecycle_gates.CLOSE_SHARED_GATES[1](
        gate_ctx, garden_passed=garden_passed
    ).diagnostics)
    if unresolved:
        diagnostics.append(_diagnostic("open_changes_remaining", f"Wave has unresolved change statuses: {', '.join(sorted(set(unresolved)))}.", recovery_tools=["wf_current_wave"], recovery_usage="wf_current_wave()"))
    required_lanes = list(shared["required_lanes"])
    empty_roster_advisory = (
        _diagnostic(
            "required_review_lanes_empty",
            "This declared wave has no required review lanes in `## Participants` "
            "or project configuration. The lane gate is intentionally non-blocking "
            "while empty; add explicit lanes when independent review is required.",
        )
        if authority.typed and not required_lanes
        else None
    )
    required_council_signoffs = list(shared["required_council_signoffs"])
    evidence_present = authority.evidence_present()
    if not evidence_present:
        diagnostics.append(
            _diagnostic(
                "missing_signoff_evidence",
                "Wave record needs executable review/signoff evidence before close.",
                recovery_tools=["wf_review_wave"],
                recovery_usage=f"wf_review_wave(wave_id={wave_id!r})",
            )
        )
    if authority.typed:
        independence_errors = repair_independence_violations(authority.records)
        diagnostics.extend(
            _diagnostic(
                REVIEW_EVIDENCE_INDEPENDENCE_INVALID,
                error,
                recovery_tools=["wf_review_wave"],
                recovery_usage=f"wf_review_wave(wave_id={wave_id!r}, phase='implementation')",
            )
            for error in independence_errors
        )
    # Wave 1p3rm (1p3rp) + 1p5pz: secrets gate — 'pending'/'suspected-secret' entries
    # hard-block until classified; 'confirmed-secret' entries do NOT block but are surfaced
    # as a non-blocking standing reminder (secrets_notice) on every close (success + error).
    canonical_wave_id_m = _WAVE_ID_PATTERN.search(text)
    canonical_wave_id = canonical_wave_id_m.group(1) if canonical_wave_id_m else wave_id
    diagnostics.extend(_memory_validation_diagnostics(root, canonical_wave_id))
    diagnostics.extend(_check_secrets_gate(root, canonical_wave_id))
    secrets_notice = _confirmed_secret_notice(root) or {}
    # Wave 1t3ek (1t230): retrieval-posture sensor at close — surfaced in DATA
    # (the secrets_notice pattern), never a diagnostic, because close hard-blocks
    # on any diagnostic and this advisory must never block by itself.
    try:
        _close_posture_gap = _retrieval_posture_gap(root, wave_md)
    except Exception:
        _close_posture_gap = None
    if _close_posture_gap is not None:
        secrets_notice = {**secrets_notice, "retrieval_posture_gap": _close_posture_gap}
    hard_gate_data: dict[str, Any] = {}
    # Wave 1yd98: the sensor gate is the last member and is called explicitly, not
    # iterated, because it needs the blocking state as a keyword.  The keyword is
    # computed AFTER this loop, so a blocker produced by the checkbox or receipt
    # gate inside it also withholds the sensor; computing it before the loop would
    # pass every criterion on an approval-blocked fixture while silently losing
    # that case.  Membership in the tuple is retained so the order pin holds.
    for gate in lifecycle_gates.CLOSE_HARD_GATES[:-1]:
        gate_result = gate(gate_ctx)
        diagnostics.extend(gate_result.diagnostics)
        hard_gate_data.update(gate_result.data)
        configured_gates.extend(gate_result.data.get("configured_gates", []))
    sensor_gate_result = lifecycle_gates.CLOSE_HARD_GATES[-1](
        gate_ctx, blocked=lifecycle_gates.has_blocking_diagnostics(diagnostics)
    )
    diagnostics.extend(sensor_gate_result.diagnostics)
    hard_gate_data.update(sensor_gate_result.data)
    configured_gates.extend(sensor_gate_result.data.get("configured_gates", []))
    framework_test_receipt = hard_gate_data["framework_test_receipt"]
    # Gate close runs unconditionally so open gates are always reported (and closed in
    # create mode) even when other diagnostics cause an early return.
    gate_diagnostics = _force_gates_closed(root, mode_s)
    # Wave 1wuju (1wujs AC-1): an advisory diagnostic (`docs_lint_warning`) is
    # rendered on every close envelope but never gates the close; only a
    # blocking entry takes the early return. The predicate was list
    # non-emptiness, so a wave whose only lint output was one advisory line
    # closed with `error` (delivery review CODE-DEL-1 / ARCH-DEL-1).
    advisory_diagnostics = [d for d in diagnostics if d.get("advisory") is True]
    if lifecycle_gates.has_blocking_diagnostics(diagnostics):
        return _close_envelope("error", {"wave_id": wave_id, "mode": mode_s, "lint_passed": lint_result["passed"], "garden_passed": garden_passed, "required_council_signoffs": required_council_signoffs, "framework_test_receipt": framework_test_receipt, **secrets_notice, **scanner_skip_notice(root)}, diagnostics=diagnostics + ([empty_roster_advisory] if empty_roster_advisory else []) + gate_diagnostics, next_tools=["wf_validate_docs", "wf_current_wave"], usage="wf_validate_docs()")
    # Generate the wave summary from structured change doc fields (12sq4).
    try:
        wave_summary = _generate_wf_close_wave_summary(wave_id, text, wave_md)
    except (OSError, UnicodeError, ValueError) as exc:
        return _close_envelope(
            "error",
            {"wave_id": wave_id, "mode": mode_s, "lint_passed": lint_result["passed"], "garden_passed": garden_passed},
            diagnostics=[_diagnostic(
                "change_doc_unreadable",
                f"Could not read an admitted change while generating the close summary: {exc}",
                recovery_tools=["wf_validate_docs"],
                recovery_usage="wf_validate_docs()",
            )] + gate_diagnostics,
            next_tools=["wf_validate_docs", "wf_current_wave"],
            usage="wf_validate_docs()",
        )
    updated = False
    transitioned_to_closed = False
    handoff_rel = ""
    close_optimize: Optional[dict[str, Any]] = None
    memory_summary: dict[str, Any] = {}
    if mode_s == "create":
        status_match = _STATUS_PATTERN.search(text)
        _already_closed = bool(status_match and status_match.group(1) == "closed")
        if status_match and status_match.group(1) != "closed":
            import time
            # Summary write precedes status checkpoint (per 12sq4 AC risk note).
            text = _replace_wave_summary_section(text, wave_summary)
            text = text[:status_match.start(1)] + "closed" + text[status_match.end(1):]
            if "Completed At:" not in text:
                text = text.replace("## Wave Summary", f"Completed At: {time.strftime('%Y-%m-%d')}\n\n## Wave Summary", 1)
            try:
                text = _project_current_review_status(root, wave_md, text)
            except ValueError as exc:
                return _close_envelope(
                    "error",
                    {"wave_id": wave_id, "mode": mode_s},
                    diagnostics=[
                        _diagnostic("review_projection_failed", str(exc)),
                        *gate_diagnostics,
                    ],
                    next_tools=["wf_review_event", "wf_validate_docs"],
                )
            wave_md.write_text(text, encoding="utf-8")
            updated = True
            transitioned_to_closed = True
            if cache:
                cache.invalidate()
            # Run opportunistic SQLite maintenance before the close's background
            # refresh competes for the build lock. Skip unnecessary/locked work,
            # preserve failure guidance, and never rebuild or re-embed here.
            close_optimize = _maybe_optimize_index_on_close(root)
            # Defensive fallback: the pre-close validation gate normally means
            # every source already has a disposition. If evidence changed after
            # the gate, create candidates only; never invent a semantic verdict.
            memory_summary = _auto_populate_memory_for_wave(root, wave_id)
    if mode_s == "create" and (transitioned_to_closed or _already_closed):
        # Wave 1seax (1seat AC-2): the handoff is the last-written referencing
        # record, converged on EVERY create-mode close of a closed wave — a
        # retry after an interruption between the wave.md write and this point
        # completes the operation instead of skipping it.
        handoff = root / "docs" / "agents" / "session-handoff.md"
        handoff.parent.mkdir(parents=True, exist_ok=True)
        prior = handoff.read_text(encoding="utf-8") if handoff.exists() else ""
        converged = _update_handoff_wave_ref(prior, None)
        if converged != prior:
            handoff.write_text(converged, encoding="utf-8")
        handoff_rel = str(handoff.relative_to(root)).replace("\\", "/")
        _trigger_background_index_refresh_for_paths(root, [wave_md, handoff])
    # Wave 1p601: only create-mode close refreshes the codebase map; dry-run does
    # not (fail-safe — never affects the result).
    if mode_s == "create":
        _regenerate_codebase_map_safe(root)
    envelope = _close_envelope(
        "dry_run" if mode_s == "dry_run" else "ok",
        {"wave_id": wave_id, "mode": mode_s, "updated": updated, "transitioned_to_closed": transitioned_to_closed, "handoff_path": handoff_rel, "wave_summary": wave_summary,
         "framework_test_receipt": framework_test_receipt,
         **({"index_optimize": close_optimize} if close_optimize else {}),
         **({"memory": memory_summary} if memory_summary else {}), **secrets_notice},
        diagnostics=advisory_diagnostics + ([empty_roster_advisory] if empty_roster_advisory else []) + gate_diagnostics or None,
        next_tools=["wf_current_wave"],
        usage="wf_current_wave()",
    )
    envelope = _attach_lint_to_response(envelope, root, mode_s)
    # Read after existing validation: docs-lint can publish current scanner
    # observations, but this advisory reader never scans or writes itself.
    envelope["data"].update(scanner_skip_notice(root))
    return envelope


@_fail_closed_on_record_layout("wf_reopen_wave")
def wf_reopen_wave_response(root: Path, wave_id: str) -> dict[str, Any]:
    wave_md, wave_read_error, unreadable_waves = _find_wave_md_detailed(root, wave_id)
    if wave_md is None:
        if unreadable_waves:
            return _wave_resolution_unreadable_response(
                wave_id, unreadable_waves, data={"wave_id": wave_id}
            )
        return _response("error", {"wave_id": wave_id}, diagnostics=[_diagnostic("wave_not_found", f"No wave found matching '{wave_id}'.", recovery_tools=["wf_list_waves"], recovery_usage="wf_list_waves()")], next_tools=["wf_list_waves"], usage="wf_list_waves()")
    text, wave_read_error = _read_wave_record_text(wave_md)
    if text is None:
        # Wave 1v0lw: reopening rewrites the record's Status field; a record
        # that cannot be read cannot be transitioned.
        return _wave_record_unreadable_response(
            root, wave_md, wave_read_error, data={"wave_id": wave_id}
        )
    status_match = _STATUS_PATTERN.search(text)
    current_status = status_match.group(1).lower() if status_match else ""
    if current_status not in ("closed", "paused"):
        return _response("error", {"wave_id": wave_id, "current_status": current_status}, diagnostics=[_diagnostic("wave_not_closed", f"Wave '{wave_id}' has status '{current_status}' — only closed or paused waves can be reopened.", recovery_tools=["wf_current_wave"], recovery_usage="wf_current_wave()")], next_tools=["wf_current_wave"], usage="wf_current_wave()")
    # Wave 1p45l: reopening transitions the wave to `active` (OPEN), so it runs the single-OPEN
    # guard — at most one wave may be OPEN (active/implementing) at a time. (Previously unguarded:
    # a latent two-active-wave hole.)
    other_open = _find_other_active_wave(root, wave_md)
    if other_open is not None:
        return _response(
            "error",
            {"wave_id": wave_id, "current_status": current_status, "active_wave_id": other_open["wave_id"]},
            diagnostics=[_diagnostic(
                "another_wave_active",
                f"Wave {other_open['wave_id']!r} is already OPEN (active/implementing); only one wave may be OPEN at a time. "
                f"Pause it before reopening {wave_id!r}.",
                recovery_tools=["wf_pause_wave", "wf_current_wave"],
                recovery_usage=f"wf_pause_wave(wave_id={other_open['wave_id']!r}, mode='create')",
            )],
            next_tools=["wf_pause_wave", "wf_current_wave"],
            usage=f"wf_pause_wave(wave_id={other_open['wave_id']!r}, mode='create')",
        )
    # Set status back to active
    text = text[:status_match.start(1)] + "active" + text[status_match.end(1):]
    # Remove any "Completed At: ..." line stamped by wf_close_wave
    text = re.sub(r"^Completed At:.*\n?", "", text, flags=re.MULTILINE)
    wave_md.write_text(text, encoding="utf-8")
    _trigger_background_index_refresh_for_paths(root, [wave_md])
    envelope = _response(
        "ok",
        {
            "wave_id": wave_id,
            "status": "active",
            "updated": True,
            # Wave 1t72b (1t67p): reopening activates the wave; serve the
            # posture directive like every other activation path.
            "retrieval_posture": _RETRIEVAL_POSTURE_DIRECTIVE,
        },
        next_tools=["wf_current_wave", "wf_review_wave"],
        usage="wf_current_wave()",
    )
    # wf_reopen_wave has no `mode` param — it always writes. Pass "create" so the
    # lint integration fires.
    return _attach_lint_to_response(envelope, root, "create")


def _default_template(root: Path | None = None) -> str:
    """Read the single shipped change template, target copy first when supplied."""

    candidates: list[Path] = []
    if root is not None:
        candidates.append(root / ".wavefoundry" / "framework" / "install" / "plan-template.md")
    candidates.append(SCRIPTS_DIR.parent / "install" / "plan-template.md")
    for candidate in candidates:
        if candidate.is_file():
            return candidate.read_text(encoding="utf-8")
    raise RuntimeError(
        "missing plan-template.md install asset; expected one of: "
        + ", ".join(str(path) for path in candidates)
    )


# ---------------------------------------------------------------------------
# Code navigation helpers (exact search, file listing, ranged reads, symbol nav)
# ---------------------------------------------------------------------------

def _resolve_repo_path(root: Path, user_path: str) -> Optional[Path]:
    """Resolve *user_path* to an absolute path that is guaranteed to be inside *root*.

    Returns ``None`` if the path escapes the root (path traversal attempt) or if
    it is absolute (only repo-relative paths are accepted).  The returned path is
    not guaranteed to exist — callers must check.
    """
    # Reject absolute paths immediately
    if user_path.startswith("/") or (len(user_path) > 1 and user_path[1] == ":"):
        return None
    try:
        resolved = (root / user_path).resolve()
        root_resolved = root.resolve()
        resolved.relative_to(root_resolved)  # raises ValueError if outside root
        return resolved
    except (ValueError, OSError):
        return None


def _indexer_module():
    """Import the indexer module from the framework scripts directory."""
    import importlib.util
    indexer_path = SCRIPTS_DIR / "indexer.py"
    spec = importlib.util.spec_from_file_location("indexer", indexer_path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot load indexer from {indexer_path}")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)  # type: ignore[arg-type]
    return mod


def _walk_repo_for_navigation(root: Path) -> list[Path]:
    """Return navigable files respecting indexer ignore/exclusion rules."""
    try:
        indexer = _indexer_module()
        return indexer.walk_repo(root)
    except Exception:
        # Fallback: simple glob without ignore support
        result = []
        for p in sorted(root.rglob("*")):
            if p.is_file() and ".git" not in p.parts:
                result.append(p)
        return result




# Wave 1p3dk / 1p3ha: edit-governance gate detection map. Path prefixes that
# require a specific gate to be open before edits. Surfaced in the
# `edit_governance` response field so agents see the requirement at read time.

def _cached_ts_parse(absolute_path: Optional[Path], ts_lang: str, source: str) -> Any:
    """Wave 1p3dk / 1p3hd: shared tree-sitter parse wrapper consumed by every
    tree-sitter-using MCP tool (`code_outline`, `code_definition`,
    `code_references`, `code_callhierarchy`, `code_dependencies`). Uses
    `tree_sitter_cache.default_cache` so a parse for file X is reused across
    every tool that touches X in the same session — until the file's mtime
    advances, at which point the cache invalidates and the next call reparses.

    When ``absolute_path`` is None (caller doesn't have a path — rare, mostly
    for in-memory sources during tests), falls back to a fresh parse with no
    caching. When the cache module is unavailable for any reason, also falls
    back to a fresh parse — the cache is an optimization, never a correctness
    dependency.

    Graph-index isolation guard: ``graph_indexer.py`` has its own parse
    pipeline and does NOT use this cache. See `1p3hd` AC-9 / Decision Log.
    """
    if absolute_path is None:
        # No path → can't key the cache → fresh parse
        try:
            chunker = _get_chunker_module()
            return chunker._ts_parse(ts_lang, source)
        except Exception:
            return None
    try:
        import tree_sitter_cache as _cache_module
    except ImportError:  # pragma: no cover
        try:
            chunker = _get_chunker_module()
            return chunker._ts_parse(ts_lang, source)
        except Exception:
            return None

    def _parse():
        try:
            chunker = _get_chunker_module()
            return chunker._ts_parse(ts_lang, source)
        except Exception:
            return None

    try:
        tree, _was_hit = _cache_module.default_cache.get_or_parse(
            absolute_path, ts_lang, _parse,
        )
        return tree
    except Exception:  # pragma: no cover
        return None


# Wave 1p3dk / 1p3ha Tier 5: tree-sitter structural enrichment for code_read.
# File-size budget for tree-sitter parse — beyond this, the parse cost is
# user-noticeable and `structural` is omitted with a note. Tunable.
_STRUCTURAL_PARSE_SIZE_BUDGET = 500 * 1024  # 500KB

# Tree-sitter node types we consider "named symbols" for containing_symbol
# (subset matching the existing outline tier-2 conventions).
_STRUCTURAL_SYMBOL_NODE_TYPES = frozenset({
    "function_definition", "function_declaration", "method_definition",
    "method_declaration", "class_definition", "class_declaration",
    "interface_declaration", "enum_declaration", "struct_declaration",
    "impl_item", "trait_item", "type_alias", "type_alias_declaration",
    "decorated_definition",  # Python decorators wrap function/class
})
















CODE_LEXICAL_MAX_LIMIT = 50    # hard cap on returned results
CODE_LEXICAL_TEXT_CAP = 700    # per-result chunk-text cap (chars)


_DEGRADED_LOG_STATE: "dict[tuple[str, str], str]" = {}
_DEGRADED_LOG_LOCK = threading.Lock()


def _log_degradation_transition(root: Path, tool: str, fallback_reason: "str | None") -> None:
    """Persist search degradation to the store log ONCE per (tool, reason)
    TRANSITION — never per query (1seaq P2: an outage must not flood the
    bounded log). Recovery (reason back to None) is logged too, closing the
    episode. In-band response diagnostics remain the primary signal."""
    if not isinstance(root, Path):
        return  # unit tests pass mock roots; never fabricate paths from them
    key = (str(root), tool)
    current = fallback_reason or ""
    # Release-review fix (round 2): check + PERSIST + mark are one critical
    # section — persisting outside the lock let two transitions land in the
    # log in the opposite order of the in-memory state (the tail reported
    # degradation while the state said recovered). store_log is a bounded
    # local append; holding the lock across it is cheap and makes the log
    # order match the state order by construction.
    with _DEGRADED_LOG_LOCK:
        if _DEGRADED_LOG_STATE.get(key, "") == current:
            return
        try:
            iss = _load_script("index_state_store")
            index_dir = root / ".wavefoundry" / "index"
            msg = (
                f"search degradation: {tool} entered fallback_reason={current}"
                if current else f"search degradation: {tool} recovered (healthy path)"
            )
            if iss.store_log(index_dir, msg):  # release-review fix: store_log
                # swallows filesystem failures internally — only a True return
                # means the line durably appended; anything else stays
                # unmarked so the next query retries.
                _DEGRADED_LOG_STATE[key] = current
        except Exception:
            pass  # unmarked: the next query retries the persist


# ── Probed FTS serving (1wpag, wave 1wpif) ──────────────────────────────────
#
# ONE chokepoint serves every FTS read the public tools make: code_lexical,
# the hybrid FTS half of code_search/code_ask (_fts5_lexical_search,
# _lexical_candidates), and the degraded fallbacks (_fts_degraded_serve). The
# paths therefore cannot re-diverge into a silent healthy zero. The serving
# decision is an O(1) read of an in-process verdict cache keyed by the 1sed7
# build-state token: the full probe (liveness, row/shadow parity, keyed
# payload digest) runs ONCE per build-state transition per table, or once
# after a serving error, and is then cached, so a warmed read performs no
# COUNT(*), no quick_check, and no corpus scan. Damage yields a typed failure
# and at most SCHEDULES healing through the sanctioned background refresh
# (never inline); healing executes only under the build lock via the ordinary
# reconcile path (index_state_store.reconcile_chunk_index), which also writes
# the once-per-table-per-epoch heal marker. The public query path performs no
# store writes.

_FTS_SERVE_LOCK = threading.Lock()
_FTS_SERVE_STATE: "dict[str, dict[str, Any]]" = {}
_FTS_DETAIL_CAP = 240
# Verdict reasons that mean the table is DAMAGED (heal-eligible). Everything
# else is healthy, not promised (fts_disabled), or not-yet-built.


def _path_prefix_pattern(candidate: str) -> "re.Pattern[str] | None":
    """A separator- and case-insensitive matcher for one absolute path prefix.

    Wave 1wpif cycle-3 (SEC-RV2-1) replaced literal prefix matching, which
    missed the repr-doubled, forward-slash, mixed-separator and case-differing
    spellings of the same root. Cycle-4 (SEC-RV3-1) adds the BOUNDARY the first
    version lacked: without it a root that is a string prefix of a sibling
    directory matched inside it, so on a machine where this framework sits
    beside a target repository, `.../wavefoundry-target/x` came out as
    `-target/x` -- a path that exists nowhere and reads as if it were inside
    this repository. Over-matching is as much a defect as under-matching. The
    match must therefore end at a separator run or at a character that cannot
    continue a path segment.
    """
    segments = [seg for seg in re.split(r"[\\/]+", candidate) if seg]
    if not segments:
        return None
    body = r"[\\/]*".join(re.escape(seg) for seg in segments)
    return re.compile(
        r"[\\/]*" + body + r"(?:[\\/]+|(?![\w.\-]))",
        re.IGNORECASE,
    )


def _strip_path_prefix(text: str, candidate: str, heading: str, standalone: str) -> str:
    """Strip one path prefix in every spelling.

    ``heading`` replaces the prefix when a relative path follows (empty for the
    repository root, so the remainder reads repo-relative; ``~/`` for the home
    directory, so the remainder stays recognisable as a home-relative path).
    ``standalone`` replaces it when the prefix stood alone.
    """
    pattern = _path_prefix_pattern(candidate)
    if pattern is None:
        return text
    return pattern.sub(
        lambda m: heading if m.end() < len(m.string) and (
            m.string[m.end()].isalnum() or m.string[m.end()] in "._-"
        ) else standalone,
        text,
    )


def _bounded_failure_detail(root: Path, text: Any) -> str:
    """A7 (1wpag): typed-failure ``detail`` strings are bounded and
    path-sanitized: repo-relative (neither the root prefix nor the home
    directory leaves the process), whitespace-collapsed, and capped at
    ``_FTS_DETAIL_CAP`` characters.

    Both the root and the home directory go through the same spelling-tolerant
    matcher. Wave 1wpif cycle-4 (SEC-RV3-2): the home branch was a literal,
    case-sensitive ``replace`` one line below the repaired root branch, so it
    still leaked the real home directory in exactly the three spellings the
    root branch had just been fixed for, and the trailing separator
    normalization turned those misses back into readable absolute paths. The
    docstring's promise covers the home directory unconditionally, so it is
    now enforced by the same mechanism.
    """
    s = " ".join(str(text or "").split())
    roots: list[str] = []
    for candidate in (str(root), str(Path(root).resolve()) if root else ""):
        if candidate and candidate not in (".", "/") and candidate not in roots:
            roots.append(candidate)
    try:
        home = str(Path.home())
        if home and home != "/" and home not in roots:
            roots.append(home)
    except Exception:
        home = ""
    # Longest first, so a root nested under the home directory is stripped as a
    # root rather than being half-consumed by the home match.
    for candidate in sorted(roots, key=len, reverse=True):
        is_home = bool(home) and candidate == home
        s = _strip_path_prefix(
            s, candidate, "~/" if is_home else "", "~" if is_home else ".")
    s = s.replace("\\", "/")
    if len(s) > _FTS_DETAIL_CAP:
        s = s[:_FTS_DETAIL_CAP - 3] + "..."
    return s


def _fts_serve_entry(root: Path, token: Any) -> dict[str, Any]:
    """The per-root cache entry for ``token``; a changed token starts a fresh
    entry (verdicts, coverage, and the heal-request set all reset)."""
    key = str(root)
    with _FTS_SERVE_LOCK:
        entry = _FTS_SERVE_STATE.get(key)
        if entry is None or entry.get("token") != token:
            entry = {"token": token, "verdicts": {}, "coverage": {}, "scheduled": set()}
            _FTS_SERVE_STATE[key] = entry
        return entry


def _fts_invalidate_serving_state(root: "Path | None" = None) -> None:
    """Drop the cached verdicts (all roots, or one). Tests and explicit
    maintenance only; the cache otherwise turns over with the epoch."""
    with _FTS_SERVE_LOCK:
        if root is None:
            _FTS_SERVE_STATE.clear()
        else:
            _FTS_SERVE_STATE.pop(str(root), None)


def _fts_serving_verdict(
    root: Path, table: str, *, epoch_state: Any = "__compute__", refresh: bool = False,
) -> dict[str, Any]:
    """Epoch-cached FTS verdict for one table (read-compare-only).

    Cache hit: one dict lookup, no store access. Cache miss (first read in a
    build-state epoch, or ``refresh=True`` after a serving error): ONE bounded
    probe via ``index_state_store.fts_state_verdict`` (liveness, parity, keyed
    digest), then cached for the epoch. Never writes to the store.
    """
    if epoch_state == "__compute__":
        epoch_state = _epoch_state(root)
    entry = _fts_serve_entry(root, epoch_state)
    if not refresh:
        cached = entry["verdicts"].get(table)
        if cached is not None:
            return cached
    try:
        iss = _load_script("index_state_store")
        verdict = dict(iss.fts_state_verdict(root / ".wavefoundry" / "index", table))
    except Exception as exc:  # noqa: BLE001 - honesty rule: never silently healthy
        verdict = {
            "table": table, "ok": False, "reason": "probe_failed", "live": False,
            "digest": "unavailable", "fts_rows": None, "registry_rows": None,
            "heal_attempt": None, "detail": _bounded_failure_detail(root, exc),
        }
    verdict["epoch"] = list(epoch_state) if isinstance(epoch_state, (tuple, list)) else None
    with _FTS_SERVE_LOCK:
        entry["verdicts"][table] = verdict
    return verdict


def _fts_serving_coverage(
    root: Path, tables: "tuple[str, ...]" = ("docs", "code"), *, epoch_state: Any = "__compute__",
) -> dict[str, Any]:
    """Epoch-cached chunk-index coverage for the requested tables, cached per
    table at the probe boundary and never recomputed per public query (AC-8).

    1wpag delivery repair (PERF-DEL-3): the SAME compare ``index_health``
    reports, from the shared ``_chunk_index_coverage`` producer, but WITHOUT
    the ``_state_store_health_summary`` wrapper whose ``probe_state_store``
    structural quick_check measured 674 ms on this repository's store and
    re-established for the same epoch what ``fts_state_verdict`` had just
    established (liveness, parity, keyed digest). The compare uses SQLite
    vector population counts and one indexed registry ``count(*)`` per table.
    Tables without live coverage fall back to the counts recorded at the last
    successful reconcile, so degraded ``index_missing`` envelopes still carry
    coverage."""
    if epoch_state == "__compute__":
        epoch_state = _epoch_state(root)
    entry = _fts_serve_entry(root, epoch_state)
    cached = dict(entry.get("coverage") or {})
    missing = tuple(t for t in tables if t not in cached)
    if missing:
        cached.update(_chunk_index_coverage(root, missing))
        still_missing = [t for t in missing if t not in cached]
        if still_missing:
            try:
                iss = _load_script("index_state_store")
                index_dir = root / ".wavefoundry" / "index"
                for table in still_missing:
                    vector_rows, registry_rows = iss.chunk_sync_counts(index_dir, table)
                    if registry_rows is not None:
                        cached[table] = {
                            "vector_rows": vector_rows,
                            "registry_rows": registry_rows,
                        }
            except Exception:  # noqa: BLE001 - advisory only
                pass
        with _FTS_SERVE_LOCK:
            entry["coverage"] = cached
    return {t: cached[t] for t in tables if t in cached}


def _stored_language_names(
    root: Path, table: str, *, epoch_state: Any = "__compute__",
) -> "frozenset | None":
    """Epoch-cached DISTINCT stored ``language`` values for one table (1wpah
    delivery repair, PERF-DEL-4), or None when the store cannot answer.

    None means UNKNOWN, never "empty": an unreadable store, an FTS-less
    interpreter, or a table whose FTS verdict is not healthy must never be
    read as proof that a language has no rows. Cached in the same
    build-state-keyed entry as the serving verdicts, so it turns over with
    the epoch and costs one bounded read per epoch per table.
    """
    if epoch_state == "__compute__":
        epoch_state = _epoch_state(root)
    entry = _fts_serve_entry(root, epoch_state)
    cached = entry.get("languages") or {}
    if table in cached:
        return cached[table]
    vocabulary: "frozenset | None" = None
    verdict = _fts_serving_verdict(root, table, epoch_state=epoch_state)
    if verdict.get("ok") and verdict.get("reason") != "fts_disabled":
        try:
            iss = _load_script("index_state_store")
            vocabulary = iss.stored_language_vocabulary(
                root / ".wavefoundry" / "index", table,
            )
        except Exception:  # noqa: BLE001 - unknown, not empty
            vocabulary = None
    with _FTS_SERVE_LOCK:
        entry.setdefault("languages", {})[table] = vocabulary
    return vocabulary


def _fts_schedule_heal(root: Path, table: str, verdict: dict[str, Any], *, epoch_state: Any) -> dict[str, Any]:
    """At most SCHEDULE healing for a damaged table (A2: the query path never
    heals). Reuses the sanctioned single-flight background refresh; the
    indexer's ordinary reconcile path heals under the build lock. Suppressed
    when the lock owner's heal marker already names the published epoch's
    attempt (one heal per damaged table per epoch: a re-damaged table keeps
    its typed failure until the next epoch), and requested at most once per
    table per epoch from this process."""
    entry = _fts_serve_entry(root, epoch_state)
    out: dict[str, Any] = {"scheduled": False, "suppressed": None}
    attempt = epoch_state[0] if isinstance(epoch_state, (tuple, list)) and epoch_state else None
    marker = verdict.get("heal_attempt")
    if attempt and marker and str(marker) == str(attempt):
        out["suppressed"] = "already_healed_this_epoch"
        return out
    with _FTS_SERVE_LOCK:
        if table in entry["scheduled"]:
            out["suppressed"] = "already_requested"
            return out
        entry["scheduled"].add(table)
    try:
        out["scheduled"] = bool(_start_background_index_refresh(root, "project"))
    except Exception:  # noqa: BLE001 - scheduling is best-effort
        out["scheduled"] = False
    if not out["scheduled"]:
        out["suppressed"] = "refresh_not_started"
    return out


def _fts_probed_fetch(
    root: Path,
    tables: "tuple[str, ...]",
    query: str,
    limit: int,
    *,
    kind: "str | None" = None,
    tags: "list | None" = None,
    epoch_state: Any = "__compute__",
    languages: "Iterable[str] | None" = None,
    include_coverage: bool = True,
) -> dict[str, Any]:
    """The shared probed-serving chokepoint (1wpag, AC-3).

    Returns a TYPED result: ``{available, failure_reason, results, coverage,
    detail, damage, heal, lexical_disabled}``. ``results`` are raw
    ``fts_search`` rows with a ``table`` key, best-first per table (callers
    shape them). ``failure_reason`` is ``store_absent`` (not built) or
    ``query_failed`` (damage / serving error); ``damage`` maps table ->
    verdict reason and ``heal`` maps table -> the schedule outcome.
    A table whose verdict is ``fts_disabled`` (FTS5-less interpreter) is not
    promised: it contributes no rows and sets ``lexical_disabled``.
    ``languages`` (wave 1wpif, 1wpah) is the allowlisted language set pushed
    into the FTS5 ``WHERE`` as bound parameters (callers resolve it through
    ``_language_filter_names``; user input never reaches this parameter
    unresolved). Every per-table query is recorded against the active
    accounting ledger as ``<table>_lexical``.

    ``include_coverage`` (delivery repair PERF-DEL-3) is False for the two
    hybrid halves that never read ``coverage`` (``_fts5_lexical_search``,
    ``_lexical_candidates``), so the first hybrid ``code_search`` / ``code_ask``
    in an epoch does no coverage work at all; ``code_lexical`` and the
    degraded fallbacks, which report it, keep the default.
    """
    index_dir = root / ".wavefoundry" / "index"
    out: dict[str, Any] = {
        "available": False, "failure_reason": None, "results": [], "coverage": {},
        "detail": None, "damage": {}, "heal": {}, "lexical_disabled": False,
    }
    try:
        iss = _load_script("index_state_store")
        present = bool(iss.state_store_path(index_dir).exists())
    except Exception:  # noqa: BLE001
        iss, present = None, False
    if iss is None or not present:
        out["failure_reason"] = _REASON_STORE_ABSENT
        return out
    if epoch_state == "__compute__":
        epoch_state = _epoch_state(root)
    tables = tuple(tables)

    def _coverage_for() -> dict[str, Any]:
        if not include_coverage:
            return {}
        return _fts_serving_coverage(root, tables, epoch_state=epoch_state)

    live_tables: list[str] = []
    for table in tables:
        verdict = _fts_serving_verdict(root, table, epoch_state=epoch_state)
        reason = verdict.get("reason")
        if verdict.get("ok"):
            if reason == "fts_disabled":
                out["lexical_disabled"] = True
            else:
                live_tables.append(table)
            continue
        # The store verdict's not-built reason is spelled with the public
        # fallback-reason token on purpose (one vocabulary, consumed via the
        # alias per the 1seax constants pin).
        if reason in (_REASON_STORE_ABSENT, "unknown_table"):
            out["failure_reason"] = _REASON_STORE_ABSENT
            return out
        out["damage"][table] = reason
        out["heal"][table] = _fts_schedule_heal(root, table, verdict, epoch_state=epoch_state)
    if out["damage"]:
        out["failure_reason"] = _REASON_QUERY_FAILED
        out["detail"] = _bounded_failure_detail(
            root,
            "; ".join(
                f"FTS table for '{t}' failed its integrity probe ({r})"
                for t, r in sorted(out["damage"].items())
            ) + " (store damage; the next ordinary build heals it under the build lock)",
        )
        out["coverage"] = _coverage_for()
        return out
    rows: list[dict[str, Any]] = []
    language_list = sorted({str(n) for n in (languages or []) if n}) or None
    try:
        for table in live_tables:
            table_rows = iss.fts_search(
                index_dir, table, query, limit=limit,
                kind=(kind or None), tags_any=(tags or None), strict=True,
                languages=language_list,
            )
            _ledger_record(f"{table}_lexical", query, limit, len(table_rows))
            for r in table_rows:
                r["table"] = table
                rows.append(r)
    except Exception as exc:  # noqa: BLE001 - serving error: ONE bounded re-probe, typed failure, at most a heal request
        for table in live_tables:
            verdict = _fts_serving_verdict(root, table, epoch_state=epoch_state, refresh=True)
            if not verdict.get("ok") and verdict.get("reason") in _FTS_DAMAGE_REASONS:
                out["damage"][table] = verdict.get("reason")
                out["heal"][table] = _fts_schedule_heal(root, table, verdict, epoch_state=epoch_state)
        out["failure_reason"] = _REASON_QUERY_FAILED
        out["detail"] = _bounded_failure_detail(root, exc)
        out["coverage"] = _coverage_for()
        return out
    out["available"] = True
    out["results"] = rows
    out["coverage"] = _coverage_for()
    return out


def _lexical_undercoverage_diagnostic(
    root: Path, tables: "tuple[str, ...]", *, epoch_state: Any = "__compute__",
) -> "dict[str, Any] | None":
    """AC-7 (1wpag): the typed lexical-undercoverage diagnostic a HEALTHY
    hybrid response carries when the FTS half is damaged. Reads the same
    epoch-cached verdicts the chokepoint used (O(1) on a warmed epoch); None
    when every table is healthy, not promised, or not yet built."""
    if os.environ.get(LEXICAL_FUSION_DISABLE_ENV):
        return None
    damaged: dict[str, str] = {}
    for table in tables:
        verdict = _fts_serving_verdict(root, table, epoch_state=epoch_state)
        if not verdict.get("ok") and verdict.get("reason") in _FTS_DAMAGE_REASONS:
            damaged[table] = str(verdict.get("reason"))
    if not damaged:
        return None
    return _diagnostic(
        "lexical_undercoverage",
        "Semantic results are healthy, but the lexical (FTS5) half of this hybrid "
        "query is unavailable: "
        + "; ".join(f"{t}: {r}" for t, r in sorted(damaged.items()))
        + ". Exact-token recall is missing from these results until the derived FTS "
        "state heals under the build lock on the next ordinary build (requested "
        "automatically, one heal per table per epoch); index_health shows the "
        "per-table verdict.",
        recovery_tools=["index_health", "index_build"],
        recovery_usage="index_health()",
    )


def _fts_degraded_serve(
    root: Path,
    tables: "tuple[str, ...]",
    query: str,
    top_n: int,
    kind: "str | None" = None,
    tags: "list | None" = None,
    language_names: "frozenset | None" = None,
    max_per_file: "int | None" = None,
) -> dict[str, Any]:
    """The shared typed FTS serving path (wave 1seav / 1seaq).

    Serves BM25 results from the index-state store's FTS5 tables for the
    degraded-search fallbacks, with the FULL filter contract: ``kind`` is
    applied inside the FTS query, ``tags`` row-carried (any-of), an
    allowlisted ``language_names`` set (single name or category set) pushed
    into the FTS query as bound parameters (wave 1wpif, 1wpah; a value
    outside the allowlist stays a row-level guard), and ``max_per_file`` as
    a post-group cap served through the bounded refill: per table the
    monotonic ``REFILL_WINDOWS``, at most ``REFILL_MAX_QUERIES_PER_SOURCE``
    queries and ``REFILL_MAX_ROWS_PER_SOURCE`` examined rows per public
    call, exiting as soon as ``top_n`` capped rows exist, when every table
    is exhausted (``FILL_REASON_EXHAUSTED``), or at the ceiling
    (``FILL_REASON_CEILING``). Returns a TYPED result —
    ``{"available": bool, "failure_reason": None | a store-absent or
    query-failed member of ``public_contract.LEXICAL_FALLBACK_REASONS``,
    "results": [...], "coverage": {...}}`` plus ``fill`` when a refill ran —
    so a caught exception maps to the query-failed reason and is
    distinguishable from a genuine zero-hit (replacing the old
    collapse-to-``[]`` at this seam).

    Epoch discipline: callers decide WHETHER to serve from the CAPTURED
    1sed7 state token; this function reads the token only as the key of the
    probed-serving verdict cache (1wpag), never as a serve decision.
    """
    names = frozenset(str(n) for n in language_names) if language_names else None
    pushdown = _language_pushdown_ok(names) if names else False
    languages = sorted(names) if (names and pushdown) else None
    per_file_cap = int(max_per_file) if (max_per_file and int(max_per_file) > 0) else None
    refill = per_file_cap is not None or (names is not None and not pushdown)
    windows = _refill_windows(top_n) if refill else (max(1, int(top_n)),)
    fill: dict[str, Any] = {
        "requested": int(top_n), "returned": 0, "rounds": 0, "windows": [], "reason": None,
        "constraints": {
            "max_per_file": per_file_cap,
            "language": sorted(names) if names else None,
            "language_pushdown": bool(pushdown) if names else None,
        },
    }
    rows_by_table: dict[str, list[dict[str, Any]]] = {}
    open_tables: list[str] = list(tables)
    coverage: dict[str, Any] = {}
    hits: list[dict[str, Any]] = []
    reached_ceiling = False
    for round_no, window in enumerate(windows, start=1):
        fill["rounds"] = round_no
        fill["windows"].append(int(window))
        if open_tables:
            # 1wpag: ONE probed-serving chokepoint, shared with code_lexical and
            # the hybrid FTS half. Store presence, the epoch-cached per-table
            # verdict (every requested table must be live: a broken fts_code
            # beside a healthy fts_docs fails the whole serve), the strict
            # fetch, the serving-error re-probe, the bounded path-sanitized
            # detail, and the at-most-schedule heal request all live there.
            fetch = _fts_probed_fetch(
                root, tuple(open_tables), query, window, kind=kind, tags=tags, languages=languages,
            )
            coverage.update(dict(fetch.get("coverage") or {}))
            if not fetch.get("available"):
                failed: dict[str, Any] = {
                    "available": False,
                    "failure_reason": fetch.get("failure_reason") or _REASON_QUERY_FAILED,
                    "results": [], "coverage": coverage,
                }
                if fetch.get("detail"):
                    failed["detail"] = fetch["detail"]
                return failed
            fetched: dict[str, list[dict[str, Any]]] = {t: [] for t in open_tables}
            for r in fetch.get("results") or []:
                fetched.setdefault(str(r.get("table") or ""), []).append(r)
            # A table that returned fewer rows than its window is exhausted
            # (nested windows cannot grow it) and is not queried again.
            for t in list(open_tables):
                rows_by_table[t] = fetched.get(t, [])
                if len(rows_by_table[t]) < window:
                    open_tables.remove(t)
        hits = []
        for table_rows in rows_by_table.values():
            for r in table_rows:
                table = str(r.get("table") or "")
                hits.append({
                    "id": r.get("id", ""),
                    "table": table,
                    "source": "docs" if table == "docs" else "code",
                    "path": str(r.get("path", "")).replace("\\", "/"),
                    "kind": r.get("kind") or "",
                    "language": r.get("language") or "",
                    "section": r.get("section") or "",
                    "lines": list(r.get("lines") or []),
                    "text": r.get("text", ""),
                    # bm25 is smaller-is-better; negate for the house best-first order.
                    "score": -float(r.get("bm25", 0.0)),
                })
        if names:
            hits = [h for h in hits if h.get("language") in names]
        # Wave 1wpid (requirement 3+7): when this serve spans MORE THAN ONE
        # table the merge is rank-based, because raw bm25 from independently
        # normalized tables is not comparable. A single-table serve keeps its
        # existing order exactly: with one table every row's rank equals its
        # bm25 position, so fusion is order-preserving there.
        _grouped: dict[str, list[dict[str, Any]]] = {}
        for _h in hits:
            _grouped.setdefault(str(_h.get("table") or ""), []).append(_h)
        for _rows in _grouped.values():
            _rows.sort(key=lambda h: -float(h.get("score", 0.0)))
        if len(_grouped) > 1:
            hits = _load_script("index_state_store").fuse_lexical_tables(_grouped)
        else:
            hits.sort(key=lambda h: -float(h.get("score", 0.0)))
        if per_file_cap is not None:
            per_file: dict[str, int] = {}
            capped = []
            for h in hits:
                c = per_file.get(h["path"], 0)
                if c < per_file_cap:
                    capped.append(h)
                    per_file[h["path"]] = c + 1
            hits = capped
        fill["returned"] = min(len(hits), int(top_n))
        if len(hits) >= top_n or not refill:
            break
        if not open_tables:
            fill["reason"] = FILL_REASON_EXHAUSTED
            break
    else:
        reached_ceiling = True
    if reached_ceiling and len(hits) < top_n:
        fill["reason"] = FILL_REASON_CEILING
    out: dict[str, Any] = {"available": True, "failure_reason": None, "results": hits[:top_n], "coverage": coverage}
    if refill:
        out["fill"] = fill
        _ledger_fill(fill)
    return out


def _lexical_zero_hit_note() -> dict[str, Any]:
    """The token-semantics honesty note for lexical-fallback zero hits
    (mirrors code_lexical): compound identifiers are indivisible tokens."""
