def _partition_infra(results: list[dict]) -> list[dict]:
    """Stable index-based partition: move scaffolding-layer results to the end.

    Uses enumerate to avoid false drops from dict equality comparison when two
    results share identical content (same path, text, score).
    """
    infra_idx = {
        i for i, r in enumerate(results)
        if any(seg in Path(r.get("path", "")).parts for seg in INFRASTRUCTURE_PATH_SEGMENTS)
    }
    non_infra = [r for i, r in enumerate(results) if i not in infra_idx]
    infra = [r for i, r in enumerate(results) if i in infra_idx]
    return non_infra + infra


# Test-file detection: directory segments and filename patterns across ecosystems.
# Directory check uses exact segment matching (not substring) to avoid false positives
# such as src/contest/ matching "test". Filename regex covers Python, Go, Java, C#,
# JS/TS, Swift, Kotlin, Ruby, and PHP conventions.
_TEST_DIR_SEGMENTS = frozenset(["tests", "test", "__tests__", "spec", "specs"])
_TEST_FILENAME_RE = re.compile(
    r"^test_"                                               # Python: test_foo.py
    r"|_test\.[a-z]+$"                                      # Go/Python: foo_test.go
    r"|(?:Tests?|TestCase|TestSuite|Specs?)\.[a-zA-Z]+$"    # Java/C#/Swift/Kotlin: FooTest.java
    r"|\.(?:test|spec)\.[a-z]+$"                            # JS/TS: foo.test.js, foo.spec.ts
)


def _is_test_path(path: str) -> bool:
    """Return True when path belongs to a test file across common ecosystems."""
    normalized = path.replace("\\", "/")
    parts = normalized.split("/")
    name = parts[-1] if parts else ""
    return (
        any(p.lower() in _TEST_DIR_SEGMENTS for p in parts[:-1])
        or bool(_TEST_FILENAME_RE.search(name))
    )


def _candidate_merge_key(candidate: "dict") -> tuple:
    """Identity for JOINING one retrieval candidate onto another across
    substrates (1wpah delivery repair, RED-DEL-2 / CODE-DEL-1).

    The chunk ``id`` is the identity: it is unique per file from chunker 40,
    and both substrates carry it (canonical chunk rows keep the column;
    ``_lexical_candidates`` and ``_fts5_lexical_search`` copy it out of the
    FTS row). The former ``(path, tuple(lines))`` key collapsed DISTINCT
    chunks that share coordinates — 433 docs and 17 code such groups in the
    live store — so a lexical hit on one chunk was attributed to another and
    the second chunk never reached ``_agent_candidate_select``.

    Rows with no id (the keyword pass and definition-boost injections, which
    are line hits rather than indexed chunks) fall back to the 1wngv
    canonical shape. The two spaces never alias: the tuples differ in their
    leading tag.
    """
    chunk_id = str(candidate.get("id") or "")
    if chunk_id:
        return ("id", chunk_id)
    return (
        "loc",
        str(candidate.get("path") or ""),
        tuple(candidate.get("lines") or []),
    )


def _partition_tests(results: list[dict]) -> list[dict]:
    """Stable index-based partition: move test-file citations to the end.

    Applied after reranking in the weak-artifact exact-first path so
    implementation owner files rank ahead of test fixtures.
    Uses enumerate to avoid false drops from dict equality comparison when two
    results share identical content.
    """
    test_idx = {i for i, r in enumerate(results) if _is_test_path(r.get("path", ""))}
    non_test = [r for i, r in enumerate(results) if i not in test_idx]
    test = [r for i, r in enumerate(results) if i in test_idx]
    return non_test + test


def _doc_demotion_weight(path: str, kind: str, prefixes: tuple[str, str] | None = None) -> float:
    """Return the demotion multiplier for a result based on its path and kind."""
    normalized = (path or "").replace("\\", "/")
    waves_prefix, plans_prefix = prefixes or _record_prefixes(None)
    if normalized.startswith(waves_prefix):
        return _DEMOTION_WAVES
    if normalized.startswith(plans_prefix):
        return _DEMOTION_PLANS
    if kind == "seed" or normalized.startswith(".wavefoundry/framework/seeds/"):
        return _DEMOTION_SEEDS
    parts = Path(normalized).parts
    name = Path(normalized).name.lower()
    if any(seg in parts for seg in ("journals", "reports")) or "feedback" in name or "journal" in name:
        return _DEMOTION_JRNLS
    # Wave 1p66s: reference prose — architecture docs, specs, and ADRs. ADRs live under
    # docs/architecture/decisions/ (covered by the architecture prefix); docs/specs/ added
    # explicitly. Gentler than the narrative tiers — still valid context, just not ahead of code.
    if normalized.startswith("docs/architecture/") or normalized.startswith("docs/specs/"):
        return _DEMOTION_REFDOCS
    return 1.0


# Public question types that share broad synthesis retrieval behavior. Keep every
# explanatory-like gate keyed to this tuple so a new assessment cannot silently miss
# the wider pool, source priors, infrastructure partition, or validation signal.
_EXPLANATORY_LIKE_QUESTION_TYPES = ("explanatory", "assessment")

# Wave 1p66s: code-implementation intents whose answer should lead with implementing
# source, so reference prose (specs/ADRs/architecture/narrative) is demoted below code.
_DOC_DEMOTION_INTENTS = (*_EXPLANATORY_LIKE_QUESTION_TYPES, "navigational")


def _demote_doc_results(
    results: list[dict], question_type: str, prefixes: tuple[str, str] | None = None
) -> tuple[list[dict], int]:
    """Down-weight narrative/reference doc sources for code-implementation intents so the
    implementing source is not outranked by prose (1p66s extends this from explanatory-only
    to navigational "where is X" and to architecture/spec/ADR paths). Demotion is a
    down-weight, never an exclusion — a genuinely doc-answerable result still surfaces."""
    if question_type not in _DOC_DEMOTION_INTENTS:
        return results, 0

    demotion_count = 0
    for r in results:
        weight = _doc_demotion_weight(r.get("path", ""), str(r.get("kind") or "").strip().lower(), prefixes)
        if weight < 1.0:
            r["score"] = (r.get("score") or 0.0) * weight
            demotion_count += 1

    if demotion_count:
        results.sort(key=lambda x: x.get("score") or 0.0, reverse=True)

    return results, demotion_count


def _query_names_result_path(query: str, path: str) -> bool:
    """Whether the query explicitly names a result's repository path or basename."""
    q = (query or "").casefold()
    normalized = (path or "").replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    normalized = normalized.casefold()
    name = Path(normalized).name
    return bool((normalized and normalized in q) or (name and name in q))


def _assessment_evidence_weight(path: str, query: str, prefixes: tuple[str, str] | None = None) -> float:
    """Return the assessment-only report-class versus wave-history score prior.

    The report recovery applies to every ``docs/reports/`` path; no currentness or
    freshness predicate is evaluated here."""
    normalized = (path or "").replace("\\", "/").casefold()
    if _query_names_result_path(query, normalized):
        return 1.0
    if normalized.startswith(_ASSESSMENT_EVIDENCE_PATH_PREFIX):
        return _ASSESSMENT_REPORT_RECOVERY_WEIGHT
    waves_prefix, _plans_prefix = prefixes or _record_prefixes(None)
    if normalized.startswith(waves_prefix.casefold()):
        return _ASSESSMENT_HISTORICAL_WAVE_WEIGHT
    return 1.0


def _apply_assessment_evidence_prior(
    results: list[dict], query: str, question_type: str, prefixes: tuple[str, str] | None = None
) -> tuple[list[dict], int]:
    """Prefer report-class records over historical wave records by score only.

    A path-class prior with no currentness predicate: every ``docs/reports/``
    record recovers the generic report down-weight, every ``docs/waves/`` record
    receives the historical down-weight, and a query that names the path is
    exempt. Never an exclusion."""
    if question_type != "assessment":
        return results, 0

    adjusted_count = 0
    for result in results:
        # Wave 1wscp (Requirement 9): a result with NO score is left alone.
        # `(result.get("score") or 0.0) * weight` used to write `score: 0.0`
        # onto a scoreless row, which is a synthetic score -- a number the
        # ranker never produced, presented as if it had. Ordering is unchanged
        # either way, because the sort already reads a missing score as 0.0.
        if result.get("score") is None:
            continue
        weight = _assessment_evidence_weight(result.get("path", ""), query, prefixes)
        if weight != 1.0:
            result["score"] = result["score"] * weight
            adjusted_count += 1
    if adjusted_count:
        results.sort(key=lambda item: item.get("score") or 0.0, reverse=True)
    return results, adjusted_count


# Low-information repository artifacts are useful when directly requested, but otherwise
# tend to win on literal vocabulary without answering implementation questions. This prior
# mirrors doc demotion: one bounded multiplier, never exclusion, applied before selection.
_LOW_INFORMATION_PATH_WEIGHT = 0.50
_LOW_INFORMATION_IGNORE_NAMES = frozenset({
    ".aiignore", ".dockerignore", ".eslintignore", ".gitignore", ".ignore",
    ".npmignore", ".prettierignore",
})
_LOW_INFORMATION_LOCKFILE_NAMES = frozenset({
    "cargo.lock", "composer.lock", "gemfile.lock", "go.sum", "package-lock.json",
    "pipfile.lock", "pnpm-lock.yaml", "poetry.lock", "yarn.lock",
})
_LOW_INFORMATION_MANIFEST_NAMES = frozenset({
    "build.gradle", "build.gradle.kts", "cargo.toml", "composer.json", "gemfile",
    "go.mod", "package.json", "pipfile", "pom.xml", "pyproject.toml",
    "requirements-dev.txt", "requirements.txt", "setup.cfg", "setup.py",
})
# Keep this exact set aligned with indexer.GENERATED_CODE_PREFIXES. These are rendered host
# integration surfaces, not a broad heuristic for every directory named "generated".
_LOW_INFORMATION_GENERATED_PREFIXES = (
    ".claude/hooks/", ".cursor/hooks/", ".github/hooks/", ".windsurf/",
)
_LOW_INFORMATION_CATEGORY_QUERY_TERMS = {
    "ignore_file": ("ignore file", "ignore rules", "ignore patterns"),
    "lockfile": ("lockfile", "lock file"),
    "dependency_manifest": ("dependency manifest", "package manifest"),
    "generated_surface": ("generated surface", "generated hook"),
}


def _low_information_path_category(path: str) -> str:
    """Return the bounded-prior category for *path*, or an empty string."""
    normalized = (path or "").replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    lowered = normalized.casefold()
    name = Path(lowered).name
    if any(lowered.startswith(prefix) for prefix in _LOW_INFORMATION_GENERATED_PREFIXES):
        return "generated_surface"
    if name in _LOW_INFORMATION_IGNORE_NAMES:
        return "ignore_file"
    if name in _LOW_INFORMATION_LOCKFILE_NAMES or name.endswith(".lock"):
        return "lockfile"
    if name in _LOW_INFORMATION_MANIFEST_NAMES:
        return "dependency_manifest"
    return ""


def _query_names_low_information_artifact(query: str, path: str, category: str) -> bool:
    """Whether *query* directly asks about this low-information artifact or category."""
    q = (query or "").casefold()
    normalized = (path or "").replace("\\", "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    normalized = normalized.casefold()
    name = Path(normalized).name
    if (normalized and normalized in q) or (name and name in q):
        return True
    return any(term in q for term in _LOW_INFORMATION_CATEGORY_QUERY_TERMS.get(category, ()))


def _low_information_path_weight(path: str, query: str) -> float:
    """Return a query-aware path prior; direct artifact questions are never penalized."""
    category = _low_information_path_category(path)
    if not category or _query_names_low_information_artifact(query, path, category):
        return 1.0
    return _LOW_INFORMATION_PATH_WEIGHT


def _demote_low_information_results(results: list[dict], query: str) -> tuple[list[dict], int]:
    """Down-weight low-information paths without removing them from the candidate pool."""
    demotion_count = 0
    for result in results:
        weight = _low_information_path_weight(result.get("path", ""), query)
        if weight < 1.0:
            result["score"] = (result.get("score") or 0.0) * weight
            demotion_count += 1
    if demotion_count:
        results.sort(key=lambda item: item.get("score") or 0.0, reverse=True)
    return results, demotion_count


# Wave 1p66r (downstream finding): English interrogatives / leading question words that
# the bare-word symbol fallbacks below would otherwise pick as a "symbol" (e.g. a capitalized
# "Which"/"Where") — symbol-first injection then keyword-boosts off-topic citations above the
# relevance floor and DEFEATS abstention (the lowercase form, not matched by the capitalized
# fallback, abstains correctly). Skip these so a capitalized question abstains like its lowercase
# form; an actual symbol later in the question is still found (re.findall, not re.search).
_QUESTION_NONSYMBOLS = frozenset({
    # interrogatives + auxiliaries
    "which", "where", "what", "when", "why", "how", "who", "whose", "whom",
    "does", "do", "did", "is", "are", "was", "were", "can", "could", "should",
    "would", "will", "the", "this", "that", "these", "those",
    # conversational lead-ins ("Tell me about how X works", "Show/Explain/Describe/Walk …",
    # "I want to understand …") — capitalized at sentence start, they'd otherwise be picked as
    # symbols by the capitalized fallback, same class as the interrogative bug.
    "tell", "show", "explain", "describe", "walk", "give", "list", "find", "please",
    "about", "me", "through", "understand", "want", "need", "into", "regarding", "also",
})


def _extract_question_symbol(question: str) -> Optional[str]:
    """Extract the primary code symbol from a question for symbol-first injection."""
    m = re.search(r'`([^`]+)`', question)
    if m:
        sym = m.group(1).strip()
        if sym:
            return sym
    m = re.search(r'\b(\w+(?:(?:\.|::|->)\w+)+)\b', question)
    if m:
        qualified = m.group(1)
        sym = re.split(r'\.|::|->', qualified)[-1]
        if sym:
            return sym
    m = re.search(r'@(\w+)', question)
    if m:
        return '@' + m.group(1)
    m = re.search(r'\b(_\w+)\b', question)
    if m:
        return m.group(1)
    m = re.search(r'\b([A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+)\b', question)
    if m:
        return m.group(1)
    # Bare-word fallbacks (snake_case, camelCase, Capitalized) can match plain English words —
    # iterate and skip interrogatives/leading stopwords so "Which …"/"How does Foo work" yields
    # the real symbol (or nothing) rather than the question word.
    for pat in (
        r'\b([a-z][a-z0-9]+(?:_[a-z0-9]+)+)\b',
        r'\b([a-z][a-z0-9]*(?:[A-Z][a-zA-Z0-9]*)+)\b',
        r'\b([A-Z][a-zA-Z0-9]{3,})\b',
    ):
        for cand in re.findall(pat, question):
            if cand.lower() not in _QUESTION_NONSYMBOLS:
                return cand
    return None


# Artifact-anchored question detection. Concrete file/path cues are strong enough to
# anchor directly; symbol-like cues remain weak and require either an implementation
# verb or explicit config/tool context so "where is <symbol>" stays navigational.
_ARTIFACT_VERBS = frozenset([
    "generated", "generate", "generates",
    "derived", "derive", "derives",
    "stamped", "stamp", "stamps",
    "computed", "compute", "computes",
    "encoded", "encode", "encodes",
    "written", "writes", "write",
])
_ARTIFACT_CONTEXT_SIGNALS = (
    "config key", "configuration key", "mcp tool", "cli tool",
)
_ARTIFACT_PATH_CUE_RE = re.compile(
    # The concrete-path alternative is tried FIRST: a dot-directory path such as
    # `.wavefoundry/framework/scripts/indexer.py` must yield the whole path, not
    # its leading segment (cycle-2 review, CODE-DEL-1). Its final segment must
    # carry a dotted, lettered suffix, so prose slash pairs (`input/output`,
    # `and/or`) and numeric ratios (`3/4.5`) are not cues (reverification, RV-2).
    r"(?:[\w.-]+[/\\])+[\w-]+\.(?=[\w.-]*[a-z])[\w.-]+"   # concrete relative path
    # Dotfile or named extension (`.aiignore`, `.py`): case-sensitive lowercase
    # letter after the dot, so `.NET` and decimals such as `.5` are not cues.
    r"|(?<![\w.])(?-i:\.[a-z][a-z0-9][\w.-]*)"
    r"|\b[\w-]+\.(?:py|toml|json|md|yaml|yml|js|ts|tsx|jsx|lock|xml|cfg|ini)\b",
    re.IGNORECASE,
)
# A question that names a file as its OBJECT rather than as the answer ("how does
# the framework restore the .gitignore block", "which function renders .aiignore",
# "which tests cover chunker.py") keeps owner-row injection and the artifact type
# but does not pin the file at rank one over reranked evidence (cycle-2 review,
# ARCH-SEAT-5 / RED-DEL-2). "How does pyproject.toml define X" keeps the pin: the
# named artifact is the subject, with or without a leading article ("how does the
# .aiignore file exclude paths"; reverification, RED-RV-3), a single noun between
# article and name ("the file .aiignore"; RV3-3), or a multi-segment path as the
# subject ("how does docs/agents/guru.md describe retrieval"; RV3-1).
_MECHANISM_FRAME_RE = re.compile(
    r"^\s*(?:how\s+(?:does|do|is|are|did|was|were)\s+"
    r"(?!(?:(?:the|this|that|our|a|an)\s+)?(?:[\w-]+\s+)?[`'\"]?[\w./\\-]*\.[a-z])"
    r"|why\b"
    r"|which\s+(?:function|method|class|module|test|tests|code|component|helper)s?\b"
    r"|who\b"
    r"|what\s+(?:calls|uses|reads|writes|renders|generates|restores|produces|consumes|creates|updates)\b)",
    re.IGNORECASE,
)


def _mechanism_framed_question(question: str) -> bool:
    """Whether a direct-artifact question asks about the mechanism around the file."""
    return _MECHANISM_FRAME_RE.search(question or "") is not None
_ARTIFACT_SYMBOL_CUE_RE = re.compile(
    r"\+[a-z0-9]{4,5}"                             # version suffix like +2vr8
    r"|[A-Z][a-z]+[A-Z]\w+"                        # CamelCase identifier like BuildPrefix
    r"|[a-z]{3,}_[a-z]{2,}\w*"                     # snake_case identifier like build_prefix
)
# Assessment intent needs a review FRAME, not a bare noun: "how does the chunker
# handle a gap between sections?" is explanatory (cycle-2 review, RC-SEAT-2).
_ASSESSMENT_SIGNAL_RE = re.compile(
    r"^\s*(?:please\s+)?(?:review|assess|audit|evaluate)\b"
    r"|^\s*(?:where|what)\s+are\s+(?:the\s+)?(?:[\w-]+\s+){0,3}"
    r"(?:gaps?|weaknesses|opportunities|shortcomings|concerns|issues)\b"
    r"|\b(?:gaps?|weaknesses|opportunities|shortcomings)\s+"
    r"(?:in|of|with|around|across|to\s+improve)\b"
    r"|\b(?:biggest|main|major|key|remaining|current|potential|possible)\s+"
    r"(?:concerns|issues)\b"
    r"|\b(?:concerns|issues)\s+(?:exist\s+)?(?:with|in|about|around)\b",
    re.IGNORECASE,
)
# An explanatory lead ("how does X handle a gap in Y", "why does Z fail") keeps a
# mechanism question explanatory even when an assessment noun appears later.
_EXPLANATORY_LEAD_RE = re.compile(
    r"^\s*(?:how\s+(?:does|do|is|are|did|was|were)\b|why\b|explain\b|describe\b|what\s+happens\b)",
    re.IGNORECASE,
)


def _extract_direct_artifact_cue(question: str) -> str:
    """Return an unambiguous file/path artifact cue, or an empty string."""
    for match in _ARTIFACT_PATH_CUE_RE.finditer(question):
        # A match that stops at a path separator is a truncated prefix of a longer
        # path (a dot-directory before an extensionless segment such as
        # `.wavefoundry/bin/wf`, or `src/dir.v2/file`): a directory is not a file
        # cue (reverification, RV3-2).
        end = match.end()
        if end < len(question) and question[end] in "/\\":
            continue
        return match.group(0).rstrip(".,;:!?")
    return ""


def _extract_artifact_cue(question: str) -> str:
    """Return the first concrete artifact cue token in question, or empty string."""
    direct = _extract_direct_artifact_cue(question)
    if direct:
        return direct
    m = _ARTIFACT_SYMBOL_CUE_RE.search(question)
    return m.group(0) if m else ""


def _direct_artifact_owner_candidate(cue: str, candidates: list[dict]) -> Optional[dict]:
    """Return the strongest indexed chunk owned by a directly named path/basename.

    A path cue may be repository-relative or a distinctive suffix. A filename cue
    matches only a basename; extension-only cues such as ``.py`` therefore never pin.
    The caller preserves broad hybrid retrieval and uses this only as a final stable
    ordering correction.
    """
    normalized_cue = (cue or "").strip().replace("\\", "/")
    while normalized_cue.startswith("./"):
        normalized_cue = normalized_cue[2:]
    normalized_cue = normalized_cue.casefold()
    if not normalized_cue:
        return None

    cue_has_path = "/" in normalized_cue
    cue_name = Path(normalized_cue).name
    if not cue_has_path and cue_name in {
        ".py", ".toml", ".json", ".md", ".yaml", ".yml", ".js", ".ts",
        ".tsx", ".jsx", ".lock", ".xml", ".cfg", ".ini",
    }:
        # A bare extension names a class of artifacts, not one owner.
        return None

    exact_matches: list[dict] = []
    suffix_matches: list[dict] = []
    for candidate in candidates:
        path = str(candidate.get("path") or "").replace("\\", "/")
        while path.startswith("./"):
            path = path[2:]
        lowered = path.casefold()
        if not lowered:
            continue
        if lowered == normalized_cue:
            exact_matches.append(candidate)
        elif cue_has_path and lowered.endswith("/" + normalized_cue):
            suffix_matches.append(candidate)
        elif not cue_has_path and Path(lowered).name == cue_name:
            suffix_matches.append(candidate)

    eligible = exact_matches or suffix_matches
    if not eligible:
        return None
    return max(eligible, key=lambda item: float(item.get("score") or 0.0))


_ENUMERATION_RE = re.compile(
    # A collection word (which/what/all/every/each) followed (within a short span) by a
    # set-membership verb. Requires BOTH so "what IS the value of X" (a single-value lookup)
    # does not match — only genuine "which/what/all … are/registered/defined/…" enumerations.
    r"\b(?:which|what|all|every|each)\b.{0,40}"
    r"\b(?:are|registered|defined|declared|supported|available|exist|configured|"
    r"implemented|handled|subscribed|listed|enabled)\b",
    re.IGNORECASE | re.DOTALL,
)
_ENUMERATION_LEAD_RE = re.compile(r"^\s*(?:list|enumerate|how many)\b", re.IGNORECASE)


def _is_enumeration_query(question: str) -> bool:
    """Wave 1p66t: heuristic for "enumerate all X" intent ("which handlers are registered",
    "list all providers", "what events are subscribed", "how many ..."). Enumerations need the
    full set, not a reranked top-k — so we widen retrieval and flag incompleteness rather than
    silently truncate. Conservative: a plain "where is X" / "how does X work" is NOT enumeration."""
    q = (question or "").strip()
    if not q:
        return False
    if _ENUMERATION_LEAD_RE.search(q):
        return True
    return bool(_ENUMERATION_RE.search(q))


# Wave 1wscp requirement 6: the constant-value routing contract's two halves.
# BOTH must match, so "the value of a well-designed abstraction" (no upper-snake
# token) and "MAX_RETRIES is used by the scheduler" (no value question) stay
# explanatory.  The upper-snake shape requires at least one underscore and two
# segments, so a bare acronym like `API` or a sentence-initial word cannot match.
_CONSTANT_VALUE_QUERY_RE = re.compile(
    r"\b(?:what(?:'s|\s+is|\s+are)?|current)\s+(?:the\s+)?(?:current\s+)?value\s+(?:of|is|for)\b"
    r"|\bvalue\s+of\s+(?=[A-Z][A-Z0-9]*_)",
    re.IGNORECASE,
)
_UPPER_SNAKE_RE = re.compile(r"\b[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+\b")


def _classify_question(question: str) -> str:
    """Return the public five-value heuristic question type."""
    q = question.lower()
    navigational_signals = ["where is", "where are", "where can i find", "which file", "what file", "find the", "find where", "locate the", "path to"]
    instructional_signals = ["how do i", "how to", "steps to", "how can i", "how should i", "how would i"]
    artifact_cue = _extract_artifact_cue(question)
    if _extract_direct_artifact_cue(question):
        return "artifact_anchored"
    if artifact_cue and (
        any(verb in q for verb in _ARTIFACT_VERBS)
        or any(signal in q for signal in _ARTIFACT_CONTEXT_SIGNALS)
    ):
        return "artifact_anchored"
    for sig in instructional_signals:
        if sig in q:
            return "instructional"
    if _ASSESSMENT_SIGNAL_RE.search(question) and not _EXPLANATORY_LEAD_RE.search(question):
        return "assessment"
    for sig in navigational_signals:
        if sig in q:
            return "navigational"
    # Wave 1wscp requirement 6: the documented constant-value routing contract.
    # "What is the value of MAX_RETRIES?" reads as explanatory because it opens
    # with "what is", but the answer is one declaration at a known symbol, which
    # is a navigational contract: it preserves the exact declaration at rank one
    # and points the caller at `code_constants`.  Deliberately narrow -- it fires
    # only when the question BOTH asks for a value AND names an upper-snake
    # constant, so ordinary explanatory prose containing the word "value" is
    # untouched.  Measured motivation: both standing constant-value fixtures
    # classified explanatory against an expected navigational, with retrieval
    # already perfect, which is adjudicated `classifier_contract_mismatch`.
    if _CONSTANT_VALUE_QUERY_RE.search(question) and _UPPER_SNAKE_RE.search(question):
        return "navigational"
    return "explanatory"


def _heuristic_confidence(citations: list[dict], reranked: bool = False) -> str:
    """Coarse confidence for the response.

    Count alone is misleading: an off-topic query still returns many candidates. Wave 1p52p: when the
    cross-encoder ran (``reranked=True`` on GPU FP16 or CPU INT8), every citation carries the UNIFIED
    cross-encoder relevance ``sigmoid(logit)`` ∈ [0,1] — comparable across docs+code — so we gate
    "high" on a genuinely relevant top score and flag a clearly-weak band "low" around the model's
    native ~0.5 relevance boundary. Without a reranker (explicitly disabled or unbuildable), the
    per-citation scores are raw cosines from the single shared embedder: uncalibrated similarity,
    NOT a trustworthy relevance band, so confidence is CAPPED at "medium" ("low" with zero citations); "high" is never
    claimed without the cross-encoder. In lexical_fallback mode the caller further caps to "low"
    (BM25 exact-token ordering). Still coarse — the per-citation scores carry the fine signal.
    """
    return _confidence_with_basis(citations, reranked)[0]


# Wave 1wscp (requirement 5): the machine-readable bases a confidence band may
# rest on.  Exposed publicly so a caller can tell WHY a band was claimed rather
# than inferring it from the score list.
SELECTION_REASON_DEFINITION = "definition"
SELECTION_REASON_RERANKED = "reranked"
SELECTION_REASON_VECTOR = "vector_similarity"
SELECTION_REASON_LEXICAL = "lexical_bm25"
SELECTION_REASON_KEYWORD = "keyword_pass"


def _assign_selection_reasons(citations: list[dict], definition_boosted: list[str],
                              *, reranked: bool, lexical_fallback: bool) -> None:
    """Stamp each citation with why IT is in the list (wave 1wscp requirement 5).

    Every value must be true of the citation it sits on, so the reasons are
    derived from per-row evidence rather than from the response mode alone.
    The ``definition`` reason is the strictest: a definition boost firing is not
    enough, because the boost names a symbol and does not by itself prove which
    row ended up carrying that symbol's declaration.  The row must ALSO name the
    boosted symbol in its section breadcrumb or excerpt.  Without that check a
    boost that promoted some other row would license an unearned exact-owner
    confidence band on a weak lead.
    """
    boosted_symbols = [
        label.split(":", 1)[1].strip()
        for label in (definition_boosted or [])
        if isinstance(label, str) and label.startswith("symbol:") and ":" in label
    ]
    for citation in citations:
        reason = SELECTION_REASON_VECTOR
        if lexical_fallback:
            reason = SELECTION_REASON_LEXICAL
        elif citation.get("kind") == "keyword":
            reason = SELECTION_REASON_KEYWORD
        elif reranked:
            reason = SELECTION_REASON_RERANKED
        if boosted_symbols:
            haystack = f"{citation.get('section') or ''}\n{citation.get('excerpt') or ''}"
            if any(symbol and symbol in haystack for symbol in boosted_symbols):
                reason = SELECTION_REASON_DEFINITION
        citation["selection_reason"] = reason


CONFIDENCE_BASIS_SEMANTIC_LEAD = "semantic_lead"
CONFIDENCE_BASIS_EXACT_OWNER = "exact_owner"
CONFIDENCE_BASIS_NO_CITATIONS = "no_citations"
CONFIDENCE_BASIS_UNRANKED = "unranked_similarity"
CONFIDENCE_BASIS_LEXICAL_FALLBACK = "lexical_fallback"


def _confidence_with_basis(citations: list[dict], reranked: bool = False,
                           *, exact_owner: bool = False) -> tuple[str, str]:
    """Confidence band plus the machine-readable basis it rests on.

    Wave 1wscp requirement 5.  The band now describes the LEAD -- the citation
    ``answer`` actually points at -- not the maximum score anywhere in the list.
    Closed wave 1seaw demonstrated the failure this repairs: a weak rank-one
    citation paired with envelope ``confidence="high"`` because some lower-ranked
    row scored well.  A reader trusts the band as a statement about the evidence
    they were handed first, so reading it off a row they may never look at is a
    false claim about the wrong thing.

    ``exact_owner`` is the documented exception.  When the lead was placed by
    exact symbol resolution rather than by semantic similarity, its cross-encoder
    score is not the relevant signal: the declaration IS the answer, and a low
    semantic score against a short declaration chunk says nothing about
    correctness.  That basis is reported explicitly so the high band is
    auditable rather than unexplained.
    """
    if not citations:
        return "low", CONFIDENCE_BASIS_NO_CITATIONS
    n = len(citations)
    if reranked:
        # The LEAD's score, not the list maximum.
        lead = citations[0].get("score") or 0.0
        if exact_owner:
            return "high", CONFIDENCE_BASIS_EXACT_OWNER
        if n >= 2 and lead >= CONF_AGENT_RERANK_HIGH:
            return "high", CONFIDENCE_BASIS_SEMANTIC_LEAD
        if lead < CONF_AGENT_RERANK_LOW:
            return "low", CONFIDENCE_BASIS_SEMANTIC_LEAD
        return "medium", CONFIDENCE_BASIS_SEMANTIC_LEAD
    return "medium", CONFIDENCE_BASIS_UNRANKED


    # Wave 1p66r: no-reranker path. The per-citation scores are raw cosines from the
    # single shared embedder, uncalibrated similarity rather than a calibrated
    # relevance band, so an absolute floor here is
    # miscalibrated and the prior count-based "high" was relevance-blind (the
    # per-index floor guarantees n >= 2 on any non-empty index → always "high").
    # Cap at "medium": without the cross-encoder we cannot certify a "high"
    # relevance band, but a non-empty retrieval is still a usable lead. The
    # fine-grained relevance signal lives in the abstention floor on the
    # post-rerank scores; here we simply never over-claim.
    return "medium"


def _tokenize_identifier(name: str) -> list[str]:
    """Split an identifier on snake_case + camelCase + acronym + digit boundaries, lowercased.
    `RERANKER_MODEL` → [reranker, model]; `MaxRetries` → [max, retries]; `apiURL` → [api, url]."""
    s = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", name)      # camelCase → camel Case
    s = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", s)      # HTTPServer → HTTP Server
    s = s.replace("_", " ")
    return [t.lower() for t in re.findall(r"[A-Za-z0-9]+", s)]


def _query_content_terms(query: str) -> set[str]:
    """Query tokens (len > 1) minus function-word stopwords. Each word is ALSO camel/snake-split
    (wave 1p4lr) so a query that NAMES a camelCase/PascalCase symbol — ``ParseConfig``, ``WaveIndex``
    — yields its sub-tokens (parse, config / wave, index) to match a definition's name tokens; snake
    and UPPER_SNAKE names already split on ``_``. The joined form is kept too (harmless superset)."""
    terms: set[str] = set()
    for word in re.findall(r"[A-Za-z0-9_]+", query):
        for sub in (word, *_tokenize_identifier(word)):
            s = sub.lower()
            if len(s) > 1 and s not in _QUERY_STOPWORDS:
                terms.add(s)
    return terms


def _definition_qname(candidate: dict) -> Optional[str]:
    """Wave 1p4lr: the declared symbol name (qualified, e.g. ``Config.connect``) of a DEFINITION
    chunk, or ``None`` when the candidate is not a code definition. A definition is a CONSTANT
    (1p4mf ``" [const]"`` marker) OR a ``kind="code"`` chunk whose id/breadcrumb leaf is a declared
    symbol — function, method, class, interface, type, enum, const — across EVERY language the
    chunker chunks (Python/JS/TS/Java/Kotlin/C#/Go/Rust/Swift/Ruby/PHP; the chunker emits one code
    chunk per declaration with a ``stem > Qname`` breadcrumb + ``path::Qname`` id). Imports,
    code-summaries, doc/seed chunks, and dunder pseudo-symbols (``__imports__``/``__decl__``/
    ``__namespace__``) are NOT definitions."""
    section = str(candidate.get("section") or "")
    is_const = section.endswith(_CONST_SECTION_SUFFIX)
    if not is_const and str(candidate.get("kind") or "") != "code":
        return None
    cid = str(candidate.get("id") or "")
    if "::" in cid:
        qname = cid.rsplit("::", 1)[-1]
    elif " > " in section:
        qname = section.rsplit(" > ", 1)[-1]
    else:
        return None
    qname = qname.replace(_CONST_SECTION_SUFFIX, "").strip()
    # Wave 1p4lr (delivery review C1): an oversized declaration is split into chunks whose id
    # carries a ``:L<start>-L<end>`` suffix and whose breadcrumb leaf carries a `` (part N/M)`` tail.
    # Both inject tokens (``l1274``, ``part``…) that can NEVER appear in a natural-language query, so
    # the all-tokens match in ``_definition_match_boost`` would always fail — silently disabling the
    # boost for every large symbol (e.g. ``WaveIndex.search_combined``). Strip them so the boost sees
    # the real declared name.
    qname = re.sub(r":L\d+-L\d+$", "", qname)
    qname = re.sub(r"\s*\(part \d+/\d+\)$", "", qname).strip()
    leaf = qname.rsplit(".", 1)[-1]
    if not qname or leaf in ("imports", "__imports__") or leaf.startswith("__"):
        return None
    return qname


def _definition_match_boost(query_terms: set[str], candidate: dict) -> float:
    """Wave 1p4lr: DEFINITION_MATCH_BOOST when the candidate is a DEFINITION chunk (constant,
    function/method, or class/interface/type/enum — see ``_definition_qname``) whose declared name
    the query NAMES; else 1.0. Language-agnostic: detection is the chunk's declaration shape and the
    casing-agnostic camel/snake tokenizer, so it covers every chunked language. The query NAMES the
    symbol when EITHER the full QUALIFIED name's tokens are all present (``how does Config connect
    work`` → {config, connect}) OR — for a multi-token LEAF — the leaf name alone is present (``how
    does search_combined work`` → {search, combined}; a natural-language method/function query rarely
    repeats the enclosing class — delivery-review C3). The ≥2-token guard on whichever set fires
    keeps a single common word from over-boosting; a single-token leaf (e.g. ``connect``) still needs
    its qualified context. The bounded multiplier lifts a name-matching definition — a short constant
    (``what value/model/flag is X``) or the very function/class the query names — into the returned
    set WITHOUT re-imposing any casing rule, firing only on a real name match, not coincidental term
    overlap."""
    qname = _definition_qname(candidate)
    if qname is None:
        return 1.0
    segs = qname.split(".")
    qualified_tokens = [t for seg in segs for t in _tokenize_identifier(seg) if len(t) > 1]
    leaf_tokens = [t for t in _tokenize_identifier(segs[-1]) if len(t) > 1]
    if len(qualified_tokens) >= 2 and all(t in query_terms for t in qualified_tokens):
        return DEFINITION_MATCH_BOOST
    if len(leaf_tokens) >= 2 and all(t in query_terms for t in leaf_tokens):
        return DEFINITION_MATCH_BOOST
    return 1.0


def code_ask_response(index: "WaveIndex", root: Path, question: str, rerank: str = "agent", epoch_state: Any = "__compute__") -> dict[str, Any]:
    """Mechanical routing: broad retrieval pass → targeted pass → assemble structured response.

    Wave 1p52p: ONE ranking path — agent candidate selection with a
    rerank-FIRST cross-encoder. ``rerank="local"`` is a deprecated alias for
    the identical path (the old local/RRF pipelines are removed); citations
    are labeled, deduped, full-chunk in both spellings.

    1wpah delivery repair (ledger hygiene): the accounting ledger's ContextVar
    scope is opened and closed here in a try/finally (``_ledger_scope``), the
    way ``code_search_response`` already did it. The body's inline reset sat
    on the single success path, so every early return from it — invalid
    arguments, a degraded envelope, an unexpected exception — leaked the scope
    into the caller's context, where later substrate queries would keep
    recording into a finished call's ledger.
    """
    with _ledger_scope() as _ledger:
        return _code_ask_response_body(index, root, question, rerank, epoch_state, _ledger)


def _code_ask_response_body(
    index: "WaveIndex", root: Path, question: str, rerank: str, epoch_state: Any,
    _ledger: dict[str, Any],
) -> dict[str, Any]:
    """``code_ask_response`` inside its accounting-ledger scope. Separated only
    so the scope is closed in a finally; every early return below is a public
    ``code_ask`` envelope."""
    t_start = time.monotonic()

    question = question.strip()
    if not question:
        return _response("error", {"question": question, "search_mode": None, "fallback_reason": None}, diagnostics=[_diagnostic("invalid_arguments", "question must be a non-empty string.")], next_tools=[], usage="")

    # Wave 1p52p: code_ask has a single ranking path (agent selection + rerank-FIRST cross-encoder).
    # The ``rerank`` param is retained for API back-compat: "agent" (default) and the deprecated alias
    # "local" both route through the one path (search_combined ignores the value). Other values error.
    rerank = (rerank or "agent").strip().lower()
    if rerank not in ("agent", "local"):
        return _response("error", {"question": question, "rerank": rerank, "search_mode": None, "fallback_reason": None}, diagnostics=[_diagnostic("invalid_arguments", "rerank must be 'agent' (default); 'local' is a deprecated alias for the same single path.")], next_tools=["code_ask"], usage="code_ask(question='...')")

    question_type = _classify_question(question)
    gaps: list[str] = []
    citations: list[dict] = []
    # 1wpah: one accounting ledger (opened by the caller's scope) spans the
    # whole public call — the fused sources, the assessment expansion, the
    # degraded pass, and the live keyword pass.

    # Index freshness (wave 1seav / 1sbxq): the cheap cached three-state
    # verdict — per-layer last-embedded hashes + stat-fast-path walk +
    # chunker check, NEVER the O(corpus) `_layer_health` hash walk its own
    # docstring forbids on the hot path. "unknown" on any indeterminacy.
    index_freshness = _index_freshness_verdict(root)["state"]

    # Broad pass: combined semantic search with reranking
    combined_reranked = False
    vector_ms = 0
    rerank_ms = 0
    infrastructure_demoted = False
    definition_boosted: list[str] = []
    second_hop_symbols: list[str] = []
    symbol_extraction_method: str = "none"
    graph_related: Optional[dict] = None
    # 1seaq typed degradation contract: search_mode/fallback_reason are part
    # of code_ask's envelope in EVERY mode; the serve decision uses the
    # CAPTURED 1sed7 token (passed by the registration; computed once for
    # direct callers).
    search_mode = _MODE_HYBRID
    fallback_reason: "str | None" = None
    if epoch_state == "__compute__":
        epoch_state = _epoch_state(root)
    _epoch_complete = epoch_state is not None and epoch_state[1] == "complete"

    degraded_coverage: dict[str, Any] = {}

    def _degraded_citation_pass(reason: str, exc_msg: str) -> list:
        """FTS-built citations for the degraded mode (complete epoch only)."""
        nonlocal search_mode, fallback_reason, gaps, degraded_coverage
        if not _epoch_complete:
            fallback_reason = _REASON_INDEX_NOT_READY if epoch_state is not None else _REASON_STORE_ABSENT
            gaps.append(f"search index unavailable ({fallback_reason}): {exc_msg}")
            return []
        serve = _fts_degraded_serve(root, ("docs", "code"), question, 7)
        degraded_coverage = serve.get("coverage") or {}
        if not serve["available"]:
            fallback_reason = serve["failure_reason"]
            search_mode = _MODE_LEXICAL_FALLBACK  # attempted-and-failed (cross-tool consistency)
            gaps.append(f"search infrastructure failure ({serve['failure_reason']}): {exc_msg}")
            return []
        search_mode = _MODE_LEXICAL_FALLBACK
        fallback_reason = reason
        gaps.append(
            f"semantic retrieval unavailable ({reason}) — citations are BM25 exact-token "
            "matches from the published FTS layer, not semantic recall; confidence is capped"
        )
        if not serve["results"]:
            # Working-lexical zero-hit honesty (review fix): the same
            # token-semantics guidance the search tools carry.
            gaps.append(
                "zero lexical hits — tokens are matched as exact literals (compound "
                "identifiers are indivisible; substrings do not match); try the full "
                "identifier, code_keyword (live substring), or code_pattern (regex)"
            )
        return serve["results"]

    try:
        combined_results, combined_reranked, vector_ms, rerank_ms, definition_boosted, second_hop_symbols, symbol_extraction_method, graph_related = index.search_combined(
            question, top_n=7, question_type=question_type, rerank=rerank
        )
        # 1seaq: classify the exact-first artifact short-circuit honestly —
        # it returns keyword matches BEFORE semantic retrieval (a healthy
        # mode, not a fallback). The marker is the sentinel the short-circuit
        # return places in the definition_boosted slot; no DEFINITION_BOOST
        # rule may ever be labeled "artifact_anchored" (it would misclassify
        # semantic results as exact).
        if definition_boosted == ["artifact_anchored"]:
            search_mode = _MODE_EXACT
        # Detect whether the scaffolding-layer partition fired (explanatory-like questions only)
        if question_type in _EXPLANATORY_LIKE_QUESTION_TYPES and combined_reranked and combined_results:
            infra_paths = {
                r.get("path", "") for r in combined_results
                if any(seg in Path(r.get("path", "")).parts for seg in INFRASTRUCTURE_PATH_SEGMENTS)
            }
            infrastructure_demoted = bool(infra_paths)
    except SemanticModelUnavailableOfflineError as exc:
        combined_results = _degraded_citation_pass(_REASON_MODEL_UNAVAILABLE, str(exc))
    except IndexNotReadyError as exc:
        combined_results = _degraded_citation_pass(_REASON_INDEX_MISSING, str(exc))
    except Exception as exc:  # noqa: BLE001 - typed, never a bare generic gap
        combined_results = []
        fallback_reason = _REASON_QUERY_FAILED
        gaps.append(f"search infrastructure failure (query_failed): {exc}")
    _log_degradation_transition(root, "code_ask", fallback_reason)
    # 1wpag (AC-7): a healthy hybrid answer whose FTS half is damaged keeps
    # its semantic citations and carries the typed lexical-undercoverage
    # diagnostic plus a gap (O(1) epoch-cached verdict, never a probe on a
    # warmed read).
    _lexical_undercoverage: "dict[str, Any] | None" = None
    if fallback_reason is None and search_mode == _MODE_HYBRID:
        _lexical_undercoverage = _lexical_undercoverage_diagnostic(root, ("docs", "code"), epoch_state=epoch_state)
        if _lexical_undercoverage is not None:
            gaps.append(
                "lexical undercoverage: the FTS5 half of hybrid retrieval is unavailable "
                "(derived FTS state failed its integrity probe); citations are semantic-only "
                "until the next ordinary build heals it, so exact-token recall may be missing"
            )

    def _to_citation(r: dict) -> dict:
        path = r.get("path", "")
        lines = r.get("lines") or []
        line_range = f":{lines[0]}-{lines[1]}" if len(lines) == 2 else ""
        # Wave 1p4hj: return the FULL chunk text (reranker parity — the unit
        # the cross-encoder ranks on, not a 300-char sliver). Release-review
        # fix: "local" is a documented alias of the same single path, so it
        # gets the identical excerpt (the old 300-char truncation is gone).
        full = r.get("text") or ""
        cit = {
            "ref": f"{path}{line_range}",
            "path": path,
            "lines": lines,
            "excerpt": full,
            "score": r.get("score"),
            "kind": r.get("kind"),
        }
        # Wave 1seaw (1seas): expose the chunk's section path so a docs citation
        # names its heading structurally (the same value docs_search returns),
        # not only through the breadcrumb baked into the excerpt.
        if isinstance(r.get("section"), str) and r.get("section"):
            cit["section"] = r.get("section")
        # Release-review fix: "local" is a documented alias of "agent" — the
        # source metadata is part of the citation contract in both.
        if r.get("source") is not None:
            cit["source"] = r.get("source")
        if r.get("sources"):
            cit["sources"] = r.get("sources")
        return cit

    broad_hits = combined_results
    # Wave 1p52p: code_ask is always the agent path, which applied the doc-type demotion PRE-selection
    # (so the relevance drop-off could trim the demoted narrative tail) — don't double-apply here; just
    # report how many of the returned candidates carry the demotion weight.
    demotion_count = (
        sum(1 for r in broad_hits
            if _doc_demotion_weight(r.get("path", ""), str(r.get("kind") or "").strip().lower(), _record_prefixes(root)) < 1.0)
        if question_type in _DOC_DEMOTION_INTENTS else 0
    )
    partition_applied = bool(demotion_count)
    citations = []
    for final_rank, r in enumerate(broad_hits, start=1):
        # Wave 1p4hj: agent-mode's text budget (AGENT_TEXT_BUDGET_CHARS) is enforced
        # inside the candidate selection (_agent_candidate_select), which packs by
        # relevance within the budget AND honors the per-index floor — so there's no
        # post-hoc tail-trim to do here (a response-side trim would re-cut the floor
        # when the floor itself is near budget). Just build the citations.
        citation = _to_citation(r)
        citation["final_rank"] = final_rank
        citations.append(citation)

    # Targeted pass: keyword and structural lookup when broad pass is thin.
    # Review fix: SUPPRESSED in lexical fallback — mixing live code_keyword
    # citations into an envelope labeled lexical_fallback would violate the
    # mode contract (the citations would not all be FTS-published data).
    if len(citations) < 2 and search_mode != _MODE_LEXICAL_FALLBACK and not (
        fallback_reason in (_REASON_QUERY_FAILED, _REASON_STORE_ABSENT, _REASON_INDEX_NOT_READY)
    ):
        # (release-review fix: the live keyword pass must not mask an
        # infrastructure failure with "Based on indexed sources" — during a
        # store/model outage the honest envelope is the failure itself.)
        try:
            _kw_query = question.split()[0] if question.split() else question
            kw_resp = code_keyword_response(root, _kw_query)
            # 1wpah: the live keyword pass is the fifth substrate source when it fires.
            _ledger_record(
                KEYWORD_SUBSTRATE_SOURCE, _kw_query, KEYWORD_PASS_WINDOW,
                len((kw_resp.get("data") or {}).get("results") or []) if kw_resp.get("status") == "ok" else 0,
            )
            if kw_resp.get("status") != "ok":
                gaps.append("keyword search failed")
            else:
                kw_results = kw_resp.get("data", {}).get("results", [])[:3]
                for r in kw_results:
                    _kw_path = r.get("path", "")
                    citations.append({
                        "ref": f"{_kw_path}:{r.get('line', '')}",
                        "path": _kw_path,
                        "lines": [r.get("line"), r.get("line")],
                        "excerpt": r.get("snippet", ""),
                        "score": None,
                        "kind": "keyword",
                        # Release-review fix: citation source parity — the
                        # same path-based labeling the exact-first pass uses.
                        "source": "docs" if (_kw_path.startswith("docs/") or "/docs/" in _kw_path or _kw_path.endswith(".md")) else "code",
                    })
        except Exception:
            gaps.append("keyword search unavailable")

    if not citations:
        gaps.append(f"no indexed evidence found for: {question!r}")

    for final_rank, citation in enumerate(citations, start=1):
        citation["final_rank"] = final_rank

    # 1ro43: per-citation freshness annotation (batched; silent absence; the
    # helper skips live_fallback — code_ask never serves that mode, but the
    # guard is uniform). Drift partition only on the healthy reranked path;
    # `final_rank` is re-stamped when it fires so rank matches output order.
    _annotate_freshness(citations, index.root, search_mode=search_mode)
    drift_demoted_count = 0
    if combined_reranked and search_mode in ("semantic", "hybrid"):
        drift_demoted_count = _partition_drift(citations)
        if drift_demoted_count:
            for final_rank, citation in enumerate(citations, start=1):
                citation["final_rank"] = final_rank

    # Wave 1p66r: relevance-gated abstention. The per-index anti-starvation floor
    # always returns ~6 citations even when every cross-encoder score is ~0.001
    # (zero-signal retrieval), which previously read as confident evidence. When
    # the reranker ran, mark each sub-floor citation `weak` (a navigation lead, not
    # answer-bearing) and — if even the BEST candidate is below the relevance floor
    # — surface an explicit "no confident match" gap so a consumer does not treat
    # the result as load-bearing. Citations are still returned (anti-starvation
    # preserved) and fidelity is untouched — this only labels weak results honestly.
    # No absolute floor in the no-reranker path: raw single-embedder cosine is
    # uncalibrated similarity, not a calibrated band (see `_heuristic_confidence`),
    # so the no-reranker confidence cap is the signal there.
    # Wave 1wscp requirement 5: stamp every returned citation with why it is in
    # the list, after the final ordering has settled so the reason describes the
    # row's published position rather than an intermediate one.
    _assign_selection_reasons(
        citations, definition_boosted,
        reranked=bool(combined_reranked),
        lexical_fallback=search_mode == _MODE_LEXICAL_FALLBACK)

    if citations and combined_reranked:
        top_score = max((c.get("score") or 0.0) for c in citations)
        for c in citations:
            if (c.get("score") or 0.0) < CONF_AGENT_RERANK_LOW:
                c["weak"] = True
        if top_score < CONF_AGENT_RERANK_LOW:
            gaps.append(
                "no confident match — all retrieval scores are below the relevance "
                "floor; treat the citations as weak navigation leads and verify with "
                "code_keyword / code_search / grep before relying on them"
            )
    elif citations and not combined_reranked and search_mode != "lexical_fallback" and fallback_reason is None:
        # (1seav review fix: in lexical fallback the ranking is BM25 by
        # design, confidence is already capped low, and the cause is stated
        # in the degraded-mode gap — the reranker-unavailable text would
        # misdiagnose "vector-only" and misdirect to reranker setup.)
        # Wave 1p66r: the cross-encoder is the single intended ranking path; a
        # False here means it did not run (disabled via WAVEFOUNDRY_DISABLE_RERANKER
        # or the reranker model could not be built/loaded), so ranking is vector-only
        # and degraded. Make that degradation LOUD rather than silently returning
        # count-capped confidence — a healthy install always reranks.
        gaps.append(
            "reranker unavailable — ranking is vector-only and degraded; the "
            "cross-encoder did not run (disabled via WAVEFOUNDRY_DISABLE_RERANKER, "
            "or the reranker model could not be built/loaded). Confidence is capped "
            "at 'medium'; verify the reranker setup if you expect reranking."
        )

    # Wave 1p66t: enumeration intent ("which/all X are …") — semantic retrieval returns a reranked
    # top-k, which under-counts a full set. Retrieval was widened (text budget), but flag that the
    # list may be incomplete and route to an exact pass rather than implying completeness.
    if citations and _is_enumeration_query(question):
        gaps.append(
            "enumeration query — citations are a ranked sample and may be INCOMPLETE; for the full "
            "set use an exact pass (code_keyword / code_references / code_pattern) or grep."
        )

    # Wave 1wscp requirement 5: the band describes the LEAD, and the basis it
    # rests on is published rather than left for the caller to infer.  The
    # exact-owner exception applies only when the LEAD ITSELF was placed by
    # symbol resolution -- a definition boost that promoted some lower-ranked
    # row does not license a high band for a weak lead.
    _lead_selection = (citations[0].get("selection_reason") if citations else None)
    _lead_is_exact_owner = _lead_selection == SELECTION_REASON_DEFINITION
    confidence, confidence_basis = _confidence_with_basis(
        citations, combined_reranked, exact_owner=_lead_is_exact_owner)
    # 1seaq: degraded (lexical-fallback) citations are exact-token matches,
    # not cross-encoder-ranked semantic recall — cap the confidence.
    if search_mode == "lexical_fallback" and confidence in ("high", "medium"):
        confidence = "low"
        confidence_basis = CONFIDENCE_BASIS_LEXICAL_FALLBACK

    # Assemble answer text from top citations
    _infra_failure = fallback_reason in (_REASON_QUERY_FAILED, _REASON_STORE_ABSENT, _REASON_INDEX_NOT_READY)
    if citations:
        top = citations[0]
        answer = f"Based on indexed sources: see {top['ref']}."
        if len(citations) > 1:
            answer += f" Additional evidence in {', '.join(c['ref'] for c in citations[1:3])}."
    elif _infra_failure:
        # Review fix: an infrastructure failure must never read as corpus
        # absence — an agent synthesizing from `answer` would conclude
        # "not covered" when the truth is "retrieval was unavailable".
        answer = (
            f"Search infrastructure failure ({fallback_reason}) — retrieval was "
            "unavailable, so the absence of citations says NOTHING about corpus "
            "coverage. Check index_health and retry."
        )
    elif search_mode == "lexical_fallback":
        # Release-review fix: a WORKING lexical zero-hit is an exact-token
        # miss, not evidence of absence — semantic recall was unavailable.
        answer = (
            "No exact-token matches in the lexical fallback (semantic recall was "
            "unavailable). This is NOT evidence the topic is uncovered — compound "
            "identifiers are indivisible tokens; try the full identifier, "
            "code_keyword, or code_pattern, or retry when the semantic path recovers."
        )
    else:
        answer = f"No indexed evidence found for this question. The topic may not be covered in the current index or may use different terminology."

    _retrieval_accounting = _ledger_summary(CODE_ASK_SUBSTRATE_SOURCES, _ledger)
    total_ms = round((time.monotonic() - t_start) * 1000)
    _wf_log(f"[wavefoundry] code_ask timing: total={total_ms}ms vector={vector_ms}ms rerank={rerank_ms}ms")

    data: dict[str, Any] = {
        "question": question,
        "question_type": question_type,
        "answer": answer,
        "citations": citations,
        "confidence": confidence,
        # Wave 1wscp requirement 5: the band is a public trust claim, so the
        # basis it rests on ships with it rather than being inferable only by
        # re-deriving the score list.
        "confidence_basis": confidence_basis,
        "gaps": gaps,
        "index_freshness": index_freshness,
        "search_mode": search_mode,
        "fallback_reason": fallback_reason,
        **({"coverage": degraded_coverage} if (degraded_coverage or search_mode == "lexical_fallback" or fallback_reason is not None) else {}),
        "reranked": combined_reranked,
        # Wave 1p52p: code_ask has a single ranking path — agent selection with a rerank-FIRST
        # cross-encoder. ``rerank_mode`` is always "agent"; the ``reranked`` bool tells whether the
        # cross-encoder actually ran (True; GPU FP16 or CPU INT8) or reranking was explicitly disabled /
        # unbuildable (False). The former "local"/"rrf_fallback" modes were removed.
        "rerank_mode": "agent",
        "partition_applied": partition_applied,
        "demotion_count": demotion_count,
        "total_ms": total_ms,
        "vector_ms": vector_ms,
        "rerank_ms": rerank_ms,
        # 1wpah: per-source substrate accounting and the stated public-call ceiling.
        "retrieval_accounting": _retrieval_accounting,
    }
    if infrastructure_demoted:
        data["infrastructure_demoted"] = True
    if drift_demoted_count:
        # 1ro43: distinct from `partition_applied` (doc-type SCORE demotion,
        # 1p52p) — the drift partition is order-only and reason-tagged
        # per-citation; never overload the existing flag's meaning.
        data["drift_partition_applied"] = True
        data["drift_demoted_count"] = drift_demoted_count
    if definition_boosted:
        data["definition_boosted"] = definition_boosted
    if second_hop_symbols:
        data["second_hop_symbols"] = second_hop_symbols
    if symbol_extraction_method != "none":
        data["symbol_extraction_method"] = symbol_extraction_method
    # Wave 1p4hu: structural matches grouped by relationship to the query symbol (callers / readers /
    # importers / related), separate from the textual citations. Present only in agent mode when the
    # graph signal resolved a symbol and found neighbors.
    if graph_related and any(graph_related.get(k) for k in _GRAPH_RELATED_SIGNAL_KEYS):
        data["graph_related"] = graph_related

    # doc-code joins the prose-docs kinds here (1whup): a fenced example in a
    # guide goes stale exactly like the prose around it, so an explanatory
    # answer led by one carries the same code-validation duty.
    if question_type in _EXPLANATORY_LIKE_QUESTION_TYPES and citations and citations[0].get("kind") in ("doc", "doc-summary", "doc-code"):
        data["validation_required"] = True

    next_tools = ["code_read", "docs_search"]
    if citations:
        top_path = citations[0].get("path", "")
        if top_path:
            try:
                with (root / top_path).open(encoding="utf-8", errors="replace") as _f:
                    line_count = sum(1 for _ in _f)
                if line_count > 300:
                    next_tools = ["code_outline", "code_read"]
            except Exception:
                pass

    _ask_diagnostics: list[dict[str, Any]] = []
    if _lexical_undercoverage is not None:
        _ask_diagnostics.append(_lexical_undercoverage)
    if _infra_failure:  # release-review fix: attached regardless of citations
        _ask_diagnostics.append(_diagnostic(
            "search_infrastructure_failure",
            f"Retrieval was unavailable ({fallback_reason}); zero citations here does "
            "not mean the topic is uncovered. Check the index state and retry.",
            recovery_tools=["index_health"],
            recovery_usage="index_health()",
        ))
    return _response(
        "ok",
        data,
        diagnostics=_ask_diagnostics,
        next_tools=next_tools,
        usage=f"code_read(path={citations[0]['path']!r}, start_line={citations[0]['lines'][0] if citations[0]['lines'] else 1})" if citations else "code_search(query=...)",
    )


# ---------------------------------------------------------------------------
# Implementation version (refreshed on importlib.reload)
# ---------------------------------------------------------------------------

# Wave 1u2b0: the retired frozen SERVER_RUNNER_VERSION = "1" alias is deliberately NOT defined
# here. The runner identity is a capture-at-launch content hash owned by server.py (which computes
# it via compute_runner_identity below); a literal here would silently diverge behind server.py's
# module __getattr__ fallback. A standalone server_impl with no runner process reports null.

_RUNNER_IDENTITY_HEX_LEN = 12
# Derived from the length constant on purpose: a hardcoded repetition count would silently stop
# matching real identities (disabling every staleness comparison) if the length ever changed.
_RUNNER_IDENTITY_RE = re.compile(rf"^[0-9a-f]{{{_RUNNER_IDENTITY_HEX_LEN}}}$")


def compute_runner_identity(runner_files: Iterable[str] | None) -> str | None:
    """Short content identity (first 12 sha256 hex chars) over the un-reloadable runner set.

    The thin runner (server.py) captures this at process launch over server.py and
    venv_bootstrap.py, the two files that execute at launch and are never reloaded in-process.
    wf_server_info recomputes the same hash from disk at query time and compares; opening the
    stored unresolved launch paths re-resolves symlinks, so a swapped install target is seen.
    Fail-safe by contract: returns None when the set is empty or unknown, or when any file is
    unreadable (missing, locked, or a torn mid-upgrade copy); it never raises, because
    wf_server_info is exactly the tool operators reach for mid-upgrade.
    """
    if not runner_files:
        return None
    digest = hashlib.sha256()
    for name in runner_files:
        try:
            digest.update(Path(name).read_bytes())
        except Exception:
            return None
    return digest.hexdigest()[:_RUNNER_IDENTITY_HEX_LEN]


def _read_framework_pack_version(*, scripts_dir: Path | None = None) -> str:
    scripts_dir = scripts_dir or SCRIPTS_DIR
    version_path = scripts_dir.parent / "VERSION"
    try:
        return version_path.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def _read_framework_version_at_root(root: Path) -> str:
    version_path = root.resolve() / ".wavefoundry" / "framework" / "VERSION"
    try:
        return version_path.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


SERVER_IMPL_VERSION = _read_framework_pack_version()

# Runner identity state, populated by the thin runner via set_server_runner_version at build time
# and re-populated after every in-process reload. Defaults mean "no runner process": a standalone
# server_impl reports an explicit null identity, never a fake value.
_runner_version: str = ""
_runner_files: list[str] = []

_CONTEXT_RETRIEVAL_TOOLS = frozenset(
    {
        "code_hover",
        "code_risk_score",
        "code_ask",
        "code_search",
        "code_lexical",
        "docs_search",
        "code_keyword",
        "code_pattern",
        "code_constants",
        "code_read",
        "code_outline",
        "code_definition",
        "code_references",
        "code_callhierarchy",
        "code_impact",
        "code_dependencies",
        "code_callgraph",
        "code_graph_path",
        "code_graph_community",
        "code_commit_provenance",
    }
)
_INDEXED_CONTEXT_TOOLS = frozenset(
    {"code_ask", "code_search", "code_lexical", "docs_search"}
)
_REFERENCE_ONLY_GRAPH_TOOLS = frozenset(
    {
        "code_impact",
        "code_dependencies",
        "code_callgraph",
        "code_graph_path",
        "code_graph_community",
        # Wave 1t3ek (1t15a): shipped without instrumentation; structural like its siblings.
        "code_risk_score",
    }
)
_LIFECYCLE_CONTEXT_STAGES = {
    "wf_create_wave": "plan",
    "wf_prepare_wave": "plan",
    "wf_implement_wave": "implement",
    "wf_review_wave": "review",
    "wf_close_wave": "review",
    # Tracking tools are attributed to IMPLEMENT: marking an acceptance
    # criterion or task is work done while implementing, and the wave record
    # should show that cost and saving against the implement stage rather than
    # against plan or review. They record workflow context only — no lifecycle
    # focus move and no checkpoint publication — because a checkbox flip is not
    # a lifecycle transition.
    "wf_mark_ac": "implement",
    "wf_mark_task": "implement",
}
_TRACKING_CONTEXT_TOOLS = frozenset({"wf_mark_ac", "wf_mark_task"})


def _context_data(response: dict[str, Any]) -> dict[str, Any]:
    data = response.get("data")
    if isinstance(data, dict):
        return data
    data = {}
    response["data"] = data
    return data


def _context_source_paths(
    tool_name: str, response: dict[str, Any]
) -> list[str]:
    """Extract only paths whose content-bearing fields are in the envelope.

    This is deliberately an explicit public-shape census. Recursive
    ``path``/``file`` guessing is unsafe because indexed envelopes also carry
    graph neighbors, communities, dependency scope, and other reference-only
    metadata that must never become a whole-file savings baseline.
    """

    data = response.get("data")
    if not isinstance(data, dict):
        return []
    paths: set[str] = set()

    def add_rows(
        rows_key: str,
        path_key: str,
        content_keys: tuple[str, ...],
        *,
        present_is_content: bool = False,
    ) -> None:
        rows = data.get(rows_key)
        if not isinstance(rows, list):
            return
        for row in rows:
            if not isinstance(row, dict):
                continue
            path = row.get(path_key)
            if not isinstance(path, str) or not path or path == "external":
                continue
            if present_is_content:
                content_bearing = any(key in row for key in content_keys)
            else:
                content_bearing = any(
                    row.get(key) not in (None, "") for key in content_keys
                )
            if content_bearing:
                paths.add(path)

    if tool_name == "code_ask":
        add_rows("citations", "path", ("excerpt",))
    elif tool_name in {"code_search", "docs_search"}:
        add_rows("results", "path", ("excerpt", "text"))
    elif tool_name == "code_lexical":
        add_rows("results", "path", ("text",))
    elif tool_name == "code_keyword":
        add_rows("results", "path", ("snippet", "text"))
    elif tool_name == "code_pattern":
        add_rows("matches", "file", ("text",), present_is_content=True)
    elif tool_name == "code_constants":
        add_rows("results", "file", ("value",), present_is_content=True)
    elif tool_name == "code_read":
        path = data.get("path")
        if isinstance(path, str) and path and "content" in data:
            paths.add(path)
    elif tool_name == "code_hover":
        # The hover envelope names its file under "file" (not "path") —
        # live-verified against code_hover_response; the symbol dict is the
        # content-bearing signal.
        path = data.get("file")
        if isinstance(path, str) and path and data.get("symbol"):
            paths.add(path)
    elif tool_name == "code_outline":
        path = data.get("file")
        symbols = data.get("symbols")
        if isinstance(path, str) and path and isinstance(symbols, list) and symbols:
            paths.add(path)
    elif tool_name == "code_definition":
        add_rows("definitions", "path", ("snippet",))
    elif tool_name == "code_references":
        add_rows("references", "path", ("snippet",))
    elif tool_name == "code_callhierarchy":
        outgoing = data.get("outgoing")
        if isinstance(outgoing, list):
            for row in outgoing:
                site = row.get("call_site") if isinstance(row, dict) else None
                if not isinstance(site, dict):
                    continue
                path, snippet = site.get("file"), site.get("snippet")
                if (isinstance(path, str) and path and path != "external"
                        and isinstance(snippet, str) and snippet):
                    paths.add(path)
        add_rows("incoming", "file", ("snippet",))
    elif tool_name == "code_commit_provenance":
        # The resolved wave record / change docs whose recorded reasoning
        # (Decision Log excerpt) the response surfaces in lieu of re-reading them.
        add_rows("provenance", "path", ("excerpt", "rationale"))
    return sorted(paths)


def _context_structural_paths(
    tool_name: str, response: dict[str, Any]
) -> list[str]:
    """Extract only file fields explicitly represented by graph results."""

    data = response.get("data")
    if not isinstance(data, dict):
        return []
    paths: set[str] = set()

    def add(value: Any) -> None:
        if isinstance(value, str) and value and value != "external":
            paths.add(value)

    def add_rows(value: Any, key: str) -> None:
        if not isinstance(value, list):
            return
        for row in value:
            if isinstance(row, dict):
                add(row.get(key))

    if tool_name == "code_dependencies":
        add(data.get("path"))
    elif tool_name == "code_impact":
        # Heuristic mode exposes the seed and importers; graph mode exposes
        # the bounded affected rows. Hidden neighbors never enter this census.
        add(data.get("path"))
        add_rows(data.get("importers"), "file")
        add_rows(data.get("affected"), "source_file")
    elif tool_name == "code_callgraph":
        add_rows(data.get("nodes"), "source_file")
    elif tool_name == "code_graph_path":
        add_rows(data.get("path_nodes"), "source_file")
    elif tool_name == "code_graph_community":
        add_rows(data.get("nodes"), "source_file")
    elif tool_name == "code_risk_score":
        add_rows(data.get("results"), "source_file")
    return sorted(paths)


def _context_indexed_proofs(
    root: Path,
    tool_name: str,
    response: dict[str, Any],
    *,
    epoch_stable: bool,
) -> list[context_efficiency.SourceProof]:
    paths = _context_source_paths(tool_name, response)
    if not paths:
        return []
    normalized: list[tuple[str, str]] = []
    for path in paths:
        rel = path
        try:
            candidate = Path(path)
            if candidate.is_absolute():
                rel = candidate.resolve().relative_to(root.resolve()).as_posix()
            else:
                rel = candidate.as_posix()
        except (OSError, RuntimeError, ValueError):
            rel = path
        normalized.append((path, rel))
    try:
        metadata = _load_script("index_state_store").read_build_file_meta(
            root / ".wavefoundry" / "index",
            [rel for _, rel in normalized],
        )
    except Exception:
        metadata = None
    rows = metadata if isinstance(metadata, dict) else {}
    proofs: list[context_efficiency.SourceProof] = []
    for _path, rel in normalized:
        row = rows.get(rel)
        version = (
            context_efficiency.FileVersion.from_index_meta(row)
            if isinstance(row, dict)
            else None
        )
        proofs.append(
            context_efficiency.indexed_source_proof(
                rel, version, epoch_stable=epoch_stable
            )
        )
    return proofs


def _context_current_size_proofs(
    tool_name: str, response: dict[str, Any],
) -> list[context_efficiency.SourceProof]:
    return [
        context_efficiency.SourceProof(path, "live", None)
        for path in _context_source_paths(tool_name, response)
    ]


def _context_structural_proofs(
    tool_name: str, response: dict[str, Any],
) -> list[context_efficiency.SourceProof]:
    return [
        context_efficiency.SourceProof(
            path,
            "live",
            None,
            credit_kind="structural",
        )
        for path in _context_structural_paths(tool_name, response)
    ]


def _retrieval_failure_metric(core_response: dict[str, Any]) -> dict[str, Any]:
    try:
        returned = context_efficiency.estimate_tokens_utf8(
            context_efficiency.canonical_core_json(core_response)
        )
    except Exception:
        returned = 0
    return {
        "estimated_request_tokens": 0,
        "estimated_returned_tokens": returned,
        "estimated_source_tokens": 0,
        "estimated_avoided_tokens": 0,
        "source_files_counted": 0,
        "source_files_verified": 0,
        "source_files_estimated": 0,
        "source_files_credited": 0,
        "source_credits_dropped": 0,
        "captured": False,
        "persistence": "failed",
        "method": context_efficiency.RETRIEVAL_METHOD,
    }


def _attach_retrieval_failure_context(
    tool_name: str, response: dict[str, Any]
) -> dict[str, Any]:
    """Keep every retrieval envelope shaped without buffering rejected work."""

    retrieval_tools = globals().get("_CONTEXT_RETRIEVAL_TOOLS", ())
    if tool_name in retrieval_tools:
        _context_data(response)["context_avoided"] = (
            _retrieval_failure_metric(response)
        )
    return response




def _record_retrieval_context(
    handler: "ImplHandler",
    tool_name: str,
    response: dict[str, Any],
    *,
    indexed_epoch_stable: bool = False,
    request_arguments: Any = None,
) -> dict[str, Any]:
    """Attach one fail-isolated metric at the public tool envelope."""

    if tool_name not in _CONTEXT_RETRIEVAL_TOOLS:
        return response
    # Retrieval remains available during publication, but its native CE
    # recorder must not mutate telemetry or wave projections while the
    # checkpoint is active.
    if publication_control.native_publication_block_reason(
        handler.root, "retrieval_context_telemetry"
    ) is not None:
        return response
    try:
        if tool_name in _REFERENCE_ONLY_GRAPH_TOOLS:
            proofs = _context_structural_proofs(tool_name, response)
        elif tool_name in _INDEXED_CONTEXT_TOOLS:
            proofs = _context_indexed_proofs(
                handler.root,
                tool_name,
                response,
                epoch_stable=indexed_epoch_stable,
            )
        else:
            # Exact-navigation helpers do not expose a read-bracketing
            # signature. Their contained current-file size is still a useful
            # estimate, but the metric classifies it separately from a
            # same-version verified baseline.
            proofs = _context_current_size_proofs(tool_name, response)
        metric = context_efficiency.retrieval_context_avoided(
            response,
            handler.root,
            proofs,
            request_arguments=request_arguments,
        )
        if metric.get("captured") is not True:
            public = _poisoned_or_fatal_telemetry_failure(
                handler.root, metric
            )
        else:
            public = handler.telemetry.record_retrieval(
                metric, tool_name=tool_name
            )
    except Exception:
        public = _poisoned_or_fatal_telemetry_failure(
            handler.root, _retrieval_failure_metric(response)
        )
    if public.get("fatal_persistence_failure") is True:
        return {
            "status": "error",
            "data": {
                "failed": True,
                "stage": "context_efficiency",
                "error_code": "telemetry_persistence_failed",
            },
            "diagnostics": [
                {
                    "code": "telemetry_persistence_failed",
                    "message": (
                        "The tool result was withheld because neither its "
                        "telemetry event nor the durable accounting-gap "
                        "barrier could be persisted."
                    ),
                }
            ],
            "next_tools": [],
        }
    _context_data(response)["context_avoided"] = public
    return response


def _workflow_failure_metric(core_response: dict[str, Any]) -> dict[str, Any]:
    try:
        returned = context_efficiency.estimate_tokens_utf8(
            context_efficiency.canonical_core_json(core_response)
        )
    except Exception:
        returned = 0
    return {
        "estimated_request_tokens": 0,
        "estimated_returned_tokens": returned,
        "prompt_surface_tokens": 0,
        "estimated_compaction_tokens": 0,
        "credited": False,
        "captured": False,
        "persistence": "failed",
        "method": context_efficiency.WORKFLOW_PROXY_METHOD,
        "limitation": context_efficiency.WORKFLOW_PROXY_LIMITATION,
    }


def _poisoned_or_fatal_telemetry_failure(
    root: Path, metric: dict[str, Any]
) -> dict[str, Any]:
    """Fail closed when instrumentation raises before its normal commit path."""

    payload = dict(metric)
    if context_efficiency.poison_accounting_gap(root):
        payload["persistence"] = "poisoned"
    else:
        payload["persistence"] = "failed"
        payload["fatal_persistence_failure"] = True
    payload["captured"] = False
    return payload


def _record_tracking_context(
    handler: "ImplHandler",
    tool_name: str,
    wave_id: str,
    response: dict[str, Any],
    *,
    request_arguments: Any = None,
    mode: str,
) -> dict[str, Any]:
    """Attribute an exact-item tracking tool to the implement stage.

    Deliberately narrower than ``_lifecycle_context_result``: a checkbox flip is
    not a lifecycle transition, so this moves no context-efficiency focus and
    publishes no checkpoint. It records the workflow-instruction proxy only, and
    credits it as a milestone only when the mark was actually written, so a dry
    run and a failed target resolution carry their debit without earning credit. Telemetry must never change the caller's result: a recording failure
    that is not fatal leaves the mark response exactly as produced.
    """

    if tool_name not in _TRACKING_CONTEXT_TOOLS:
        return response
    # Finding `fail-closed-wrapper-telemetry`: the mark response has already
    # refused an invalid layout, a duplicated id, or an ambiguous prefix; the
    # telemetry re-resolution must not raise what the caller already handled.
    try:
        wave_md = _find_wave_md(handler.root, wave_id)
    except (ValueError, record_paths.RecordLayoutInvalid, record_paths.AmbiguousWaveId):
        wave_md = None
    resolved = wave_md.parent.name if wave_md is not None else str(wave_id)
    # A dry run also returns status "ok" with `changed`, so the write mode is
    # part of the milestone test; otherwise previewing a mark would earn credit
    # for work that never happened.
    data = _context_data(response)
    written = (
        response.get("status") == "ok"
        and str(mode).strip().lower() in {"create", "apply"}
        and bool(data.get("changed"))
    )
    # Every write is credited, because every write saves. Doing this by hand
    # means emitting the matched item's full text TWICE — the string to find and
    # the string to replace it with — so the saving recurs per call and scales
    # with the item's length. Measured across wave 1ui1d's own 41 items:
    # hand-editing 4,084 tokens versus 791 for the tool calls, with acceptance
    # criteria saving 121 tokens each and short task lines 16. A once-per-wave
    # credit would have booked one flat number and lost that entirely.
    avoided = None
    if written:
        matched = str(data.get("matched_text") or "")
        if matched:
            avoided = 2 * context_efficiency.estimate_tokens_utf8(matched)
    return _record_workflow_context(
        handler,
        tool_name,
        resolved,
        response,
        request_arguments=request_arguments,
        milestone_completed=written,
        avoided_authoring_tokens=avoided,
    )


def _record_workflow_context(
    handler: "ImplHandler",
    tool_name: str,
    wave_id: str,
    response: dict[str, Any],
    *,
    request_arguments: Any = None,
    milestone_completed: bool,
    avoided_authoring_tokens: int | None = None,
) -> dict[str, Any]:
    """Persist debits for every reached handler; credit only a milestone."""

    try:
        metric = context_efficiency.workflow_instruction_proxy(
            response,
            handler.root,
            tool_name,
            request_arguments=request_arguments,
            avoided_authoring_tokens=avoided_authoring_tokens,
            milestone_completed=milestone_completed,
        )
        if metric.get("captured") is not True:
            public = _poisoned_or_fatal_telemetry_failure(
                handler.root, metric
            )
        else:
            public = handler.telemetry.record_workflow(
                wave_id,
                _LIFECYCLE_CONTEXT_STAGES[tool_name],
                tool_name,
                metric,
            )
    except Exception:
        public = _poisoned_or_fatal_telemetry_failure(
            handler.root, _workflow_failure_metric(response)
        )
    if public.get("fatal_persistence_failure") is True:
        return {
            "status": "error",
            "data": {
                "failed": True,
                "stage": "context_efficiency",
                "error_code": "telemetry_persistence_failed",
            },
            "diagnostics": [
                {
                    "code": "telemetry_persistence_failed",
                    "message": (
                        "The lifecycle result was withheld because neither "
                        "its telemetry event nor the durable accounting-gap "
                        "barrier could be persisted."
                    ),
                }
            ],
            "next_tools": [],
        }
    _context_data(response)["workflow_instruction_proxy"] = public
    return response


def _wave_checkpoint_floor(root: Path, wave_id: str) -> dict[str, Any]:
    wave_md = _find_wave_md(root, wave_id)
    if wave_md is None:
        return context_efficiency.empty_checkpoint(wave_id)
    # Wave 1v0lw: seam-routed; an unreadable record degrades to the empty
    # checkpoint (the historical OSError behavior, now covering decode too).
    wave_text, _read_error = _read_wave_record_text(wave_md)
    parsed = (
        context_efficiency.parse_checkpoint_block(wave_text)
        if wave_text is not None
        else None
    )
    return parsed or context_efficiency.empty_checkpoint(wave_md.parent.name)












def _implementation_review_complete(response: dict[str, Any]) -> bool:
    """Return whether an implementation review reached its public milestone."""

    if response.get("status") != "ok":
        return False
    data = response.get("data")
    if not isinstance(data, dict) or data.get("phase") != "implementation":
        return False
    if data.get("lint_passed") is not True:
        return False
    lane_results = data.get("lane_results")
    council_results = data.get("council_results")
    return (
        isinstance(lane_results, list)
        and isinstance(council_results, list)
        and all(
            isinstance(row, dict) and row.get("recorded_signoff") is True
            for row in lane_results
        )
        and all(
            isinstance(row, dict) and row.get("recorded_signoff") is True
            for row in council_results
        )
    )




def _lifecycle_milestone_completed(
    tool_name: str,
    response: dict[str, Any],
    *,
    mutating: bool,
) -> bool:
    """Return whether a mutating lifecycle call completed new milestone work."""

    if not mutating or response.get("status") != "ok":
        return False
    data = response.get("data")
    if not isinstance(data, dict):
        return False
    if tool_name == "wf_create_wave":
        return data.get("created") is True
    if tool_name == "wf_prepare_wave":
        mode = str(data.get("mode", "")).strip().lower()
        if mode == "ready":
            return data.get("readied") is True
        return data.get("transitioned_to_active") is True
    if tool_name == "wf_implement_wave":
        return data.get("transitioned_to_implementing") is True
    if tool_name == "wf_close_wave":
        return data.get("transitioned_to_closed") is True
    return False


LIFECYCLE_ENGAGED_STATUSES = frozenset({"ok", "dry_run", "ready_for_council_review"})
LIFECYCLE_NOT_ENGAGED_STATUSES = frozenset({"error", "partial"})


def _review_reached_lane_evaluation(tool_name: str, response: dict[str, Any]) -> bool:
    """A review that RAN (structured lane summary) despite an error status."""

    response_data = response.get("data")
    return (
        tool_name == "wf_review_wave"
        and isinstance(response_data, dict)
        and isinstance(response_data.get("wave_id"), str)
        and isinstance(response_data.get("lane_results"), list)
        and (response_data.get("phase") in {"prepare", "implementation"})
    )


def _classify_lifecycle_outcome(tool_name: str, response: dict[str, Any]) -> str:
    """Canonical target-engagement classifier (wave 1tmb3).

    ``engaged``: the call engaged its target wave — ``ok``, ``dry_run``,
    ``ready_for_council_review`` (a successful technical pass awaiting council
    work on exactly that wave), or a review that reached prepare/implementation
    lane evaluation. ``not_engaged``: genuine errors/rejections and partial
    writes. Anything else is ``unknown`` and FAILS CLOSED for focus with an
    ``unknown_lifecycle_outcome`` diagnostic — a new status cannot engage
    until this classifier is deliberately updated.
    """

    status = response.get("status")
    if status in LIFECYCLE_ENGAGED_STATUSES:
        return "engaged"
    if _review_reached_lane_evaluation(tool_name, response):
        return "engaged"
    if status in LIFECYCLE_NOT_ENGAGED_STATUSES:
        return "not_engaged"
    return "unknown"


def _attempt_focus_state(
    handler: "ImplHandler",
    *,
    action: str,
    wave_id: str | None = None,
    stage: str | None = None,
    new_phase: bool = False,
) -> tuple[bool, str]:
    """The SINGLE focus write path (wave 1tmb3): set and clear.

    Every focus mutation in this module goes through here — a structural
    census pins that, so a new consumer bypassing the shared primitive fails
    the suite. Returns ``(applied, error)``; it never raises.
    """

    try:
        if action == "clear":
            handler.telemetry.clear_focus()
        else:
            handler.telemetry.set_focus(
                str(wave_id), str(stage), new_phase=bool(new_phase)
            )
        return True, ""
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


def _focus_set_write_needed(
    handler: "ImplHandler", wave_id: str, stage: str, new_phase: bool
) -> bool:
    """A set is a no-op only when the exact requested state is already current."""

    try:
        current = handler.telemetry.focus
    except Exception:
        return True
    return bool(
        new_phase or current.wave_id != wave_id or current.stage != stage
    )


def _focus_clear_write_needed(handler: "ImplHandler") -> bool:
    try:
        current = handler.telemetry.focus
    except Exception:
        return True
    return bool(current.wave_id or current.stage)


def _append_response_diagnostic(response: dict[str, Any], diagnostic: dict[str, Any]) -> None:
    diagnostics = response.get("diagnostics")
    if not isinstance(diagnostics, list):
        diagnostics = []
        response["diagnostics"] = diagnostics
    diagnostics.append(diagnostic)


def _focus_write_failed_diagnostic(response: dict[str, Any], detail: str, error: str) -> None:
    """Report a needed focus write that failed, without overturning the result."""

    data = _context_data(response)
    data["focus_stage"] = None
    data["focus_error"] = error
    _append_response_diagnostic(response, _diagnostic(
        "focus_stage_not_applied",
        f"{detail}: {error}. The lifecycle result stands; retrieval done now "
        "will be attributed to the previous focus state. Retry the focus by "
        "re-running this call, or advance the next lifecycle boundary (e.g. "
        "wf_review_wave) before further retrieval.",
        recovery_tools=["wf_current_wave", "wf_review_wave"],
        recovery_usage="wf_current_wave()  # inspect focus, then retry or advance the boundary",
    ))


def _apply_lifecycle_focus_reporting(
    handler: "ImplHandler",
    tool_name: str,
    response: dict[str, Any],
    *,
    outcome: str,
    target_wave_id: str,
    target_resolved: bool,
    desired_stage: str,
    new_phase: bool,
) -> None:
    """Focus attempt plus best-effort reporting for one lifecycle response.

    Observational by contract: nothing here may overturn the core lifecycle
    result. ``unknown`` outcomes fail closed for focus; ``engaged`` outcomes
    attempt the set through the shared primitive (an engaged call whose
    target could not be resolved keeps the 1t59p hardening — focus is left
    untouched rather than pointed at an unresolved raw argument);
    ``not_engaged`` outcomes report the effective attribution destination and
    emit ``focus_target_not_engaged`` when that destination is an unrelated
    wave.
    """

    if outcome == "unknown":
        _append_response_diagnostic(response, _diagnostic(
            "unknown_lifecycle_outcome",
            f"Status {response.get('status')!r} from {tool_name} is not "
            "modeled by the canonical lifecycle-outcome classifier; "
            "context-efficiency focus was left unchanged (fail-closed). A new "
            "outcome class cannot engage focus until the classifier is "
            "deliberately updated.",
            recovery_tools=["wf_current_wave"],
            recovery_usage="wf_current_wave()  # inspect focus and wave state",
        ))
        return
    if outcome == "engaged":
        if not target_resolved:
            # Hardening (1t59p, operator-approved): NEVER set focus from an
            # unresolved wave argument — a stale-code session once focused the
            # raw string "1t6ow" (a change ID) and the resulting phantom wave
            # key made every reload/upgrade projection refuse. Focus is left
            # untouched (not nulled: a typo must not clobber a valid focus)
            # and the call's cost attributes through the normal fallbacks.
            return
        if not _focus_set_write_needed(
            handler, target_wave_id, desired_stage, new_phase
        ):
            return
        applied, error = _attempt_focus_state(
            handler,
            action="set",
            wave_id=target_wave_id,
            stage=desired_stage,
            new_phase=new_phase,
        )
        if not applied:
            _focus_write_failed_diagnostic(
                response,
                "The lifecycle call engaged its target, but context-efficiency "
                f"focus was NOT moved to stage '{desired_stage}' on wave "
                f"'{target_wave_id}'",
                error,
            )
        return
    # not_engaged: report where work will actually land instead of moving focus.
    focus = handler.telemetry.focus
    effective = context_efficiency.resolve_effective_attribution(
        handler.root, focus
    )
    data = _context_data(response)
    data["focus_attribution"] = {
        "effective": effective,
        "observed_focus": {"wave_id": focus.wave_id, "stage": focus.stage},
    }
    destination = effective.get("destination")
    source = effective.get("source")
    # Suppression requires wave AND stage match (1to7k finding
    # open-wave-fallback-stage-mismatch-suppressed): a restarted server with
    # no explicit focus resolves the sole OPEN wave at its derived stage, and
    # wave equality alone would silently bucket failed close/prepare work in
    # the wrong stage.
    suppress = (
        destination == "general"
        or (
            target_resolved
            and destination == target_wave_id
            and (
                (source == "open_wave" and effective.get("stage") == desired_stage)
                or (source == "focus" and focus.stage == desired_stage)
            )
        )
    )
    if suppress:
        return
    if target_resolved:
        target_label = f"wave '{target_wave_id}'"
    else:
        target_label = (
            "the requested wave (which did not resolve to a canonical wave "
            "record)"
        )
    if focus.wave_id:
        observed = (
            f"Observed focus (state only, not a promise of attribution): "
            f"wave '{focus.wave_id}' stage '{focus.stage}'. "
        )
    else:
        observed = "No explicit focus is set. "
    _append_response_diagnostic(response, _diagnostic(
        "focus_target_not_engaged",
        f"This call did not engage {target_label}, so context-efficiency "
        f"focus did not move. {observed}Work done now will be attributed to "
        f"'{destination}' (stage {effective.get('stage')!r}, source: "
        f"{source}). Recovery: repair the blocking condition and retry this "
        "lifecycle call so focus moves to the intended wave.",
        recovery_tools=[tool_name, "wf_current_wave"],
        recovery_usage=f"{tool_name}(wave_id=...)  # repair the blocking condition, then retry",
    ))


def _lifecycle_context_result(
    handler: "ImplHandler",
    tool_name: str,
    wave_id: str,
    response: dict[str, Any],
    *,
    focus_stage: str | None = None,
    credit: bool | None = None,
    flush: bool = False,
    transfer_general: bool = False,
    request_arguments: Any = None,
) -> dict[str, Any]:
    """Apply outcome classification, focus, reporting, proxy, flush, projection.

    Canonical processing order (wave 1tmb3): canonical-target resolution,
    engagement classification, effective-attribution classification, focus
    set/clear attempt with best-effort reporting, workflow-call recording,
    then the existing publication policy. Focus and publication remain
    DISTINCT policies: publication flushes what is already attributed, focus
    governs what happens next; the one deliberately target-engaged overlap is
    ``ready_for_council_review``, which both publishes and focuses its target.
    """

    # 1. Canonical-target resolution. Finding `fail-closed-wrapper-telemetry`:
    # the decorated response already refused an invalid layout or a duplicated
    # id; telemetry must never change the caller's result by re-raising it.
    try:
        wave_md = _find_wave_md(handler.root, wave_id)
    except (ValueError, record_paths.RecordLayoutInvalid, record_paths.AmbiguousWaveId):
        wave_md = None
    target_resolved = wave_md is not None
    if wave_md is not None:
        wave_id = wave_md.parent.name
    if credit is None:
        credit = flush
    # 2. Engagement classification (fail-closed for unknown statuses).
    outcome = _classify_lifecycle_outcome(tool_name, response)
    # 3-4. Effective attribution + focus attempt + best-effort reporting.
    if focus_stage is not None:
        try:
            _apply_lifecycle_focus_reporting(
                handler,
                tool_name,
                response,
                outcome=outcome,
                target_wave_id=wave_id,
                target_resolved=target_resolved,
                desired_stage=focus_stage,
                new_phase=bool(credit),
            )
        except Exception:
            # Reporting is observational. A wedged in-process buffer must
            # never change the already-computed lifecycle result.
            pass
    # 5. Workflow-call recording.
    response = _record_workflow_context(
        handler,
        tool_name,
        wave_id,
        response,
        request_arguments=request_arguments,
        milestone_completed=bool(credit),
    )
    reached_review = _review_reached_lane_evaluation(tool_name, response)
    if response.get("status") == "error" and not (flush and reached_review):
        # Wave 1t3ek (1t22z): a review that RAN but reports pending signoffs
        # (the normal pre-close state) still publishes the checkpoint so the
        # delivery council reads current implement-stage numbers; a review
        # that could not run at all (wave not found, validation crash) does not.
        return response
    if not flush:
        return response
    projection, flushed = _flush_context_efficiency(
        handler,
        wave_id,
        # Wave 1t3ek (1t3el): create/prepare adopt on milestone completion
        # (unchanged); a review that RAN and a mutating close also adopt, so
        # exited helper agents' buckets land on THIS wave instead of the next
        # wave's prepare.
        transfer_general=transfer_general and (bool(credit) or reached_review),
    )
    data = _context_data(response)
    data["context_efficiency_persistence"] = projection
    # 1to7k finding sealed-close-focus-clear-failure-is-silent: a needed
    # sealed-close focus clear that failed is reported through the shared
    # write-failure contract; the successful close result stands.
    focus_clear_error = projection.get("focus_clear_error")
    if focus_clear_error:
        _focus_write_failed_diagnostic(
            response,
            "The wave was closed and sealed, but context-efficiency focus "
            "was NOT cleared",
            str(focus_clear_error),
        )
    if flushed is not None and isinstance(
        data.get("workflow_instruction_proxy"), dict
    ):
        data["workflow_instruction_proxy"] = (
            context_efficiency.workflow_proxy_after_flush(
                data["workflow_instruction_proxy"],
                wave_id,
                flushed,
            )
        )
    elif isinstance(data.get("workflow_instruction_proxy"), dict):
        data["workflow_instruction_proxy"]["persistence"] = "failed"
        data["workflow_instruction_proxy"]["credited"] = False
    return response


def set_server_runner_version(v: str, runner_files: Iterable[str] | None = None) -> None:
    """Record the runner's capture-at-launch identity plus the runner-set file paths.

    Called by the thin runner (server.py) at build time and again after every in-process
    reload, so a reload never changes the reported identity; only a real process restart
    can. A standalone server_impl with no runner process never calls this and keeps the
    null-identity defaults.
    """
    global _runner_version, _runner_files
    _runner_version = v
    _runner_files = [str(f) for f in runner_files] if runner_files else []


def _runner_stale_detail() -> str:
    names = ", ".join(sorted({Path(f).name for f in _runner_files})) or "the runner files"
    return (
        f"The on-disk runner files ({names}) no longer match the copies this server process "
        "launched from. That is expected after a framework upgrade, and equally after editing "
        "those files in a development checkout. An in-process wf_reload_mcp cannot pick up "
        "runner changes: fully restart the MCP host (quit and relaunch it) to load the "
        "current runner."
    )


def version_payload(root: Path, *, server_runner_version: str | None) -> dict[str, Any]:
    framework_version = _read_framework_version_at_root(root)
    impl_version = SERVER_IMPL_VERSION
    impl_matches_disk: bool | None = None
    if framework_version and impl_version:
        impl_matches_disk = framework_version == impl_version
    # Runner staleness (wave 1u2b0): compare the capture-at-launch identity against the current
    # on-disk runner-set hash. Tri-state and fail-safe: either side unknown (no runner process,
    # unreadable or torn disk file, or a non-hash launch identity such as a pre-1.16 runner's
    # frozen "1") degrades to null, never an exception.
    launch_identity = server_runner_version or None
    disk_identity = compute_runner_identity(_runner_files)
    runner_stale: bool | None = None
    if (
        disk_identity is not None
        and launch_identity is not None
        and _RUNNER_IDENTITY_RE.match(launch_identity)
    ):
        runner_stale = launch_identity != disk_identity
    payload: dict[str, Any] = {
        "framework_version": framework_version,
        "server_runner_version": launch_identity,
        "runner_disk_identity": disk_identity,
        "runner_stale": runner_stale,
        "server_impl_version": impl_version,
        "impl_matches_disk": impl_matches_disk,
    }
    if runner_stale:
        payload["runner_stale_detail"] = _runner_stale_detail()
    return payload


def _setup_notice_key(result: Mapping[str, Any]) -> str:
    """Coalesce advice, independently of changing database/input generations."""
    return hashlib.sha256(json.dumps(
        {key: result.get(key) for key in ("status", "reasons", "actions", "startup_blocked")},
        sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()


class ImplHandler:
    """Owns per-process MCP business state (index, cache, root)."""

    def __init__(self, root: Path) -> None:
        self.root = root.resolve()
        self._setup_assessment_lock = threading.Lock()
        self._setup_loaded_identity = _SETUP_LOADED_IDENTITY
        self._setup_assessment_result = (
            globals().get("_SETUP_STARTUP_RESULT")
            if globals().get("_SETUP_STARTUP_ROOT") == self.root else None
        )
        self._setup_assessment_signature = None
        self._setup_notice_signature = (
            _setup_notice_key(self._setup_assessment_result)
            if self._setup_assessment_result is not None
            and self._setup_assessment_result.get("status") != "ready" else None
        )
        self.index = WaveIndex(self.root)
        self.cache = McpRepoCache(self.root, index=self.index)
        self.telemetry = context_efficiency.ProcessTelemetry(self.root)
        self._index_monitor_status: dict[str, Any] = {
            "configured": True, "last_checked_at": None,
            "stale": None, "triggered": False, "reason": "not_checked",
        }
        self._ce_projection_status: dict[str, Any] = {
            "configured": True, "last_checked_at": None,
            "triggered": False, "reason": "not_checked",
        }
        self._ce_projection_observed: dict[str, tuple[int, float]] = {}
        # Wave 1p5xu: in-session index-staleness monitor. Fail-safe + daemon;
        # never blocks __init__/close, swallows all errors, config-gated.
        self._monitor_stop: Any | None = None
        self._monitor_thread: Any | None = None
        self._ce_projection_stop: Any | None = None
        self._ce_projection_thread: Any | None = None
        try:
            self._start_staleness_monitor()
        except Exception:  # noqa: BLE001
            pass
        try:
            self._start_ce_projection_monitor()
        except Exception:  # noqa: BLE001
            pass

    def assess_setup(self, *, force: bool = False) -> dict[str, Any]:
        """Share one bounded assessment across monitor and explicit health calls."""
        with self._setup_assessment_lock:
            signature = setup_readiness.assessment_signature(self.root)
            if (force or self._setup_assessment_result is None
                    or self._setup_assessment_result.get("status") == "indeterminate"
                    or signature != self._setup_assessment_signature):
                result = setup_readiness.assess_setup(
                    self.root, loaded_identity=self._setup_loaded_identity,
                )
                # A changed input generation during assessment must be retried on
                # the next tick, never cached against a later healthy signature.
                self._setup_assessment_signature = signature
                self._setup_assessment_result = result
                notice_signature = _setup_notice_key(result)
                if result["status"] == "ready":
                    self._setup_notice_signature = None
                elif notice_signature != self._setup_notice_signature:
                    print(setup_readiness.format_text(result), file=sys.stderr)
                    self._setup_notice_signature = notice_signature
            return self._setup_assessment_result

    def _start_staleness_monitor(self) -> None:
        import threading

        cfg = _read_monitor_config(self.root)
        if not cfg.get("enabled", True):
            self._index_monitor_status = {
                "configured": False, "last_checked_at": None,
                "stale": None, "triggered": False, "reason": "disabled",
            }
            return
        interval = float(cfg.get("interval_seconds", _MONITOR_DEFAULT_INTERVAL_SECONDS))
        stop_event = threading.Event()
        root = self.root

        def _loop() -> None:
            while not stop_event.wait(interval):
                try:
                    self.assess_setup()
                    _maybe_refresh_if_stale(
                        root,
                        observer=lambda value: setattr(
                            self, "_index_monitor_status",
                            {"configured": True, **value},
                        ),
                    )
                except Exception:  # noqa: BLE001
                    self._index_monitor_status = {
                        "configured": True, "last_checked_at": time.time(),
                        "stale": None, "triggered": False,
                        "reason": "monitor_error",
                    }

        thread = threading.Thread(
            target=_loop, name="wavefoundry-index-monitor", daemon=True
        )
        self._monitor_stop = stop_event
        self._monitor_thread = thread
        thread.start()

    def _start_ce_projection_monitor(self) -> None:
        import threading

        cfg = _read_ce_projection_config(self.root)
        interval = float(cfg["interval_seconds"])
        stop_event = threading.Event()
        root = self.root

        def _loop() -> None:
            while not stop_event.wait(interval):
                try:
                    self._ce_projection_status = {
                        "configured": True,
                        **_maybe_project_context_efficiency(
                            root, self._ce_projection_observed
                        ),
                    }
                except Exception as exc:  # noqa: BLE001
                    self._ce_projection_status = {
                        "configured": True,
                        "last_checked_at": time.time(),
                        "triggered": False,
                        "reason": "monitor_error",
                        "error": f"{type(exc).__name__}: {exc}",
                    }

        thread = threading.Thread(
            target=_loop, name="wavefoundry-ce-projection-monitor", daemon=True
        )
        self._ce_projection_stop = stop_event
        self._ce_projection_thread = thread
        thread.start()

    def background_monitor_status(self) -> dict[str, Any]:
        return {
            "setup_readiness": self._setup_assessment_result,
            "index": {
                **dict(self._index_monitor_status),
                "alive": bool(self._monitor_thread and self._monitor_thread.is_alive()),
            },
            "context_efficiency_projection": {
                **dict(self._ce_projection_status),
                "alive": bool(
                    self._ce_projection_thread and self._ce_projection_thread.is_alive()
                ),
                "quiet_period_seconds": _read_ce_projection_config(self.root)[
                    "quiet_period_seconds"
                ],
            },
        }

    def _stop_staleness_monitor(self) -> None:
        stop_event = self._monitor_stop
        thread = self._monitor_thread
        self._monitor_stop = None
        self._monitor_thread = None
        if stop_event is not None:
            try:
                stop_event.set()
            except Exception:  # noqa: BLE001
                pass
        if thread is not None:
            try:
                thread.join(timeout=1.0)
            except Exception:  # noqa: BLE001
                pass

    def _stop_ce_projection_monitor(self) -> None:
        stop_event = self._ce_projection_stop
        thread = self._ce_projection_thread
        self._ce_projection_stop = None
        self._ce_projection_thread = None
        if stop_event is not None:
            try:
                stop_event.set()
            except Exception:  # noqa: BLE001
                pass
        if thread is not None:
            try:
                thread.join(timeout=1.0)
            except Exception:  # noqa: BLE001
                pass

    def close(self) -> None:
        try:
            self._stop_ce_projection_monitor()
        except Exception:  # noqa: BLE001
            pass
        try:
            self._stop_staleness_monitor()
        except Exception:  # noqa: BLE001
            pass
        try:
            self.telemetry.close()
        except Exception:  # noqa: BLE001
            pass
        self.cache.invalidate()
        self.index._loaded = False
        self.index._docs_vector_layer = None
        self.index._code_vector_layer = None
        self.index._proj_docs_vector_layer = None
        self.index._proj_code_vector_layer = None
        self.index._reranker = None
        self.index._memory_reranker = None
        self.index._memory_reranker_failed_model = None
        self.index._model_downloads_started = False
        self.index._loaded_meta_signature = {}
        self.index._vector_available = set()


def build_handler(root: Path) -> ImplHandler:
    return ImplHandler(root)


def _extension_provenance_for_response(root: Path) -> dict[str, Any]:
    """Loaded extension provenance with repository-relative paths (wave 1yv9l)."""
    provenance = _EXTENSION_PROVENANCE or {
        "declaration": _extension_declaration_provenance(),
        "modules": [],
    }

    def _rel(path: str) -> str:
        try:
            return Path(path).resolve().relative_to(root.resolve()).as_posix()
        except (ValueError, OSError):
            return path

    declaration = dict(provenance["declaration"])
    declaration["path"] = _rel(declaration["path"])
    modules = []
    for entry in provenance["modules"]:
        entry = dict(entry)
        entry["path"] = _rel(entry["path"])
        modules.append(entry)
    return {"declaration": declaration, "modules": modules}


def wf_server_info_response(root: Path, *, server_runner_version: str | None = None) -> dict[str, Any]:
    data = server_identity(root, server_runner_version=server_runner_version)
    data["extensions"] = _extension_provenance_for_response(root)
    diagnostics: list[dict[str, Any]] = []
    if data.get("runner_stale") is True:
        diagnostics.append(
            _diagnostic("runner_stale", str(data.get("runner_stale_detail") or _runner_stale_detail()))
        )
    return _response(
        "ok",
        data,
        diagnostics=diagnostics,
        next_tools=["wf_current_wave", "wf_help"],
        usage="wf_server_info()",
    )


def wf_gpu_doctor_response(root: Path) -> dict[str, Any]:
    """Wave 1p6et: embedding-provider / GPU capability diagnostic (read-only). Runs setup's bounded
    provider probe so the selected provider matches runtime (CoreML on Apple Silicon, etc.). The probe
    loads a model, so stdout is redirected to stderr to keep the MCP stdio stream clean."""
    import contextlib
    import sys as _sys
    import provider_policy
    import setup_index
    import cli_stdio
    # The cold ORT/DirectML probe writes native diagnostics straight to OS fd 1 — the MCP JSON-RPC
    # stdout channel — which `redirect_stdout` (Python-level) cannot intercept; on the first call
    # after a host restart that corrupts the protocol and hangs (wave 1p8vc). `redirect_stdout`
    # routes Python-level output to stderr; `cli_stdio.isolated_stdout_fd()` drops native fd-1 writes.
    # Both wrap ONLY the synchronous probe; fd 1 is restored before the framework writes the response.
    with contextlib.redirect_stdout(_sys.stderr), cli_stdio.isolated_stdout_fd():
        report = provider_policy.diagnostic_report(provider_probe=setup_index._probe_embedding_provider)
    return _response(
        "ok",
        report,
        next_tools=["index_health", "wf_server_info"],
        usage="wf_gpu_doctor()",
    )

# --- First-party tool cost accounting (wave 1t3ek / 1t3s7) -------------------
# Debit-only for the previously unmeasured surface, plus derived-artifact
# credit (avoided writing) where a tool persists textual artifacts the caller
# did not supply. Lifecycle tools (workflow proxies) and the retrieval tools
# (retrieval events) stay on their existing instrumentation.

_COST_EXEMPT_TOOLS = frozenset({
    "wf_create_wave", "wf_prepare_wave", "wf_implement_wave",
    "wf_review_wave", "wf_close_wave", "wf_reload_mcp",
    "code_ask", "code_search", "code_lexical", "docs_search",
    "code_keyword", "code_pattern", "code_constants",
    "code_read", "code_outline", "code_definition", "code_references",
    "code_callhierarchy", "code_impact", "code_dependencies",
    "code_callgraph", "code_graph_path", "code_graph_community",
    "code_commit_provenance",
    # Wave 1t3ek (1t15a): now natively retrieval-instrumented.
    "code_hover", "code_risk_score",
})


def _artifact_file_token_list(root: Path, rel_paths: Iterable[str]) -> list[int]:
    """Per-artifact token sizes for contained files — the credit contract
    floors each artifact independently, so callers get a list, not a sum."""
    tokens: list[int] = []
    for rel in rel_paths:
        if not rel:
            continue
        try:
            candidate = (root / str(rel)).resolve()
            if candidate.is_relative_to(root.resolve()) and candidate.is_file():
                tokens.append(candidate.stat().st_size // 4)
        except (OSError, ValueError):
            continue
    return tokens


def _artifact_from_review_evidence(root: Path, result: Mapping[str, Any]) -> "tuple[list[int], Optional[str]]":
    # 1t6ow live-caught repair: early returns MUST be list-typed. The 1t3ek
    # per-artifact-floor repair made the wrapper iterate raw_artifacts, so an
    # int `0` here raised TypeError inside the observational recorder and
    # silently dropped the ENTIRE debit row for every non-create response.
    data = result.get("data") if isinstance(result.get("data"), dict) else {}
    if result.get("status") == "ok" and data.get("event") == "list":
        # Operator policy (1t6ow): an identical-content repeat listing is
        # NEUTRAL — 0 credit AND 0 debit. The response hash IS the version
        # identity (the list response echoes no caller identity, so same
        # ledger version + same filters + same verbosity => same response
        # => same event id => the store's replay dedup drops the whole
        # event). A changed ledger, different filters, or any response
        # difference yields a new id and records normally.
        digest = hashlib.sha256(
            json.dumps(result, sort_keys=True, default=str).encode("utf-8")
        ).hexdigest()
        return [], f"list:{digest}"
    if result.get("status") != "ok" or data.get("mode") != "create" or data.get("replayed"):
        return [], None
    records = data.get("appended_records") or []
    if not records:
        return [], None
    digest = None
    for record in records:
        digest = record.get("request_digest") or digest
    tokens = [
        context_efficiency.estimate_tokens_utf8(
            json.dumps(record, sort_keys=True, default=str)
        )
        for record in records
    ]
    return tokens, (f"artifact:{digest}" if digest else None)


def _artifact_from_written_paths(field: str):
    def extract(root: Path, result: Mapping[str, Any]) -> "tuple[list[int], Optional[str]]":
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        if result.get("status") != "ok":
            # Same 1t6ow list-typed contract as _artifact_from_review_evidence.
            return [], None
        value = data.get(field)
        paths: list[str] = []
        if isinstance(value, list):
            for item in value:
                if isinstance(item, Mapping) and item.get("path"):
                    paths.append(str(item["path"]))
                elif isinstance(item, str):
                    paths.append(item)
        elif isinstance(value, Mapping) and value.get("path"):
            paths.append(str(value["path"]))
        elif isinstance(value, str):
            paths.append(value)
        return _artifact_file_token_list(root, paths), None
    return extract


















def _review_evidence_cost_focus(
    root: Path,
    request_payload: Mapping[str, Any],
    result: Mapping[str, Any],
) -> Optional[context_efficiency.Focus]:
    """Resolve one review-evidence call's explicit target without changing focus."""
    data = result.get("data") if isinstance(result.get("data"), Mapping) else {}
    requested_wave = request_payload.get("wave_id") or data.get("wave_id")
    if not isinstance(requested_wave, str) or not requested_wave.strip():
        return None
    try:
        wave_md = _find_wave_md(root, requested_wave)
        if wave_md is None:
            return None
        record = _read_wave_record(root, wave_md)
        if record.get("read_error"):
            # Wave 1v0lw: no focus for an unreadable record (the historical
            # OSError behavior, now covering decode too).
            return None
        status = str(record.get("status") or "").lower()
        if status in {"active", "implementing"}:
            stage = context_efficiency._derive_open_wave_stage(wave_md.parent)
        elif status == "closed":
            # The target is still passed through so _commit_event's sealed-wave
            # protection redirects the observation to the general bucket.
            stage = "review"
        elif status == "paused":
            stage = "plan"
        else:
            stage = "plan"
        phase_id = (
            context_efficiency.latest_phase_id(root, wave_md.parent.name, stage)
            or stage
        )
        return context_efficiency.Focus(wave_md.parent.name, stage, phase_id)
    except (OSError, ValueError):
        return None


# ── Lifecycle mutation lock (wave 1seax / 1seat) ─────────────────────────────
# One advisory per-root lock so two agents/sessions cannot interleave lifecycle
# writes on the same repository. OS-lock pattern (kernel-released on process
# exit — the proven index-build/test-run discipline; never a PID file). The
# lock is acquired NON-blocking around the mutating lifecycle tools at the
# registration layer; a held lock returns a structured busy response and never
# corrupts. Invisible when uncontended. Per the 1t72b TOCTOU/phantom-hold
# lessons: acquisition is a single non-blocking attempt at operation start —
# nothing ever WAITS while holding, and there is no cross-lock check-then-act.
_LIFECYCLE_MUTATION_LOCK_NAME = _lifecycle_lock_authority.LIFECYCLE_MUTATION_LOCK_REL.name
_LIFECYCLE_MUTATION_LOCK_SENTINEL = _lifecycle_lock_authority.LIFECYCLE_MUTATION_LOCK_SENTINEL

# The covered set comes from the writer CENSUS in the 1seat change doc: every
# mutating MCP tool is dispositioned there as lifecycle-lock / protected-by-
# another-lock / independent-with-rationale. This frozenset is the
# lifecycle-lock column of that census.
_LIFECYCLE_MUTATION_LOCK_TOOLS: frozenset[str] = frozenset({
    "wf_create_wave",
    "wf_add_change",
    "wf_remove_change",
    "wf_prepare_wave",
    "wf_pause_wave",
    "wf_close_wave",
    "wf_reopen_wave",
    "wf_implement_wave",
    "wf_set_handoff",
    "wf_open_gate",
    "wf_close_gate",
})


class LifecycleMutationBusy(RuntimeError):
    """Another session holds the per-root lifecycle mutation lock."""


@contextmanager
def _lifecycle_mutation_lock(root: Path):
    """Non-blocking per-root lifecycle mutation lock.

    Raises :class:`LifecycleMutationBusy` when another process holds it. The
    lock file persists as a last-owner record (like index-build.lock); the OS
    lock is the authority.
    """
    try:
        with _lifecycle_lock_authority.lifecycle_mutation_lock(root, strict=True):
            yield
    except (
        _lifecycle_lock_authority.LifecycleLockBusy,
        _lifecycle_lock_authority.LifecycleLockUnavailable,
    ) as exc:
        raise LifecycleMutationBusy(str(exc)) from exc


def _lifecycle_mutation_busy_response(tool_name: str, lock_path_hint: str) -> dict[str, Any]:
    return _response(
        "error",
        {"tool": tool_name, "busy": True, "lock": _LIFECYCLE_MUTATION_LOCK_NAME, **({"readiness_receipts": None} if tool_name == "wf_prepare_wave" else {})},
        diagnostics=[_diagnostic(
            "lifecycle_mutation_locked",
            (
                f"Another session is running a lifecycle mutation on this repository "
                f"(the {_LIFECYCLE_MUTATION_LOCK_NAME} at {lock_path_hint} is held). "
                "No state was changed. Retry once the other operation finishes; the "
                "lock is released automatically when its holder exits."
            ),
            recovery_tools=[tool_name, "wf_current_wave"],
            recovery_usage=f"{tool_name}(...) once the concurrent mutation completes",
        )],
        next_tools=[tool_name, "wf_current_wave"],
        usage=f"retry {tool_name} after the concurrent lifecycle mutation completes",
    )


def _wrap_lifecycle_mutation_lock(mcp: Any, get_handler: Any) -> None:
    """Registration-layer wrapping pass: serialize the mutating lifecycle tools.

    Wraps each census-covered tool so the whole operation runs under the
    per-root strict lock. Failure discipline: a busy or unavailable lock
    returns a structured refusal; authority-bearing mutations never run
    unguarded.
    """
    registry = getattr(getattr(mcp, "_tool_manager", None), "_tools", None)
    if not isinstance(registry, dict):
        return
    for name, tool in registry.items():
        if name not in _LIFECYCLE_MUTATION_LOCK_TOOLS:
            continue
        original = getattr(tool, "fn", None)
        if original is None or getattr(original, "_wf_mutation_locked", False):
            continue

        def _make(tool_name: str, fn: Any) -> Any:
            @functools.wraps(fn)
            def locked(*args: Any, **kwargs: Any) -> Any:
                try:
                    root = get_handler().root
                except Exception as exc:  # noqa: BLE001
                    return _response(
                        "error",
                        {"tool": tool_name, "mutation_applied": False, **({"readiness_receipts": None} if tool_name == "wf_prepare_wave" else {})},
                        diagnostics=[
                            _diagnostic(
                                "lifecycle_lock_unavailable",
                                "Cannot resolve the repository root required to prove "
                                f"lifecycle-lock ownership: {exc}",
                            )
                        ],
                        next_tools=["wf_server_info"],
                    )
                try:
                    with _lifecycle_mutation_lock(root):
                        return fn(*args, **kwargs)
                except LifecycleMutationBusy as busy:
                    return _lifecycle_mutation_busy_response(tool_name, str(busy))
            locked._wf_mutation_locked = True  # type: ignore[attr-defined]
            return locked

        tool.fn = _make(name, original)


def _wrap_upgrade_publication_guard(mcp: Any, get_handler: Any) -> None:
    """Fail every registered publisher fast while Upgrade owns project state."""

    registry = getattr(getattr(mcp, "_tool_manager", None), "_tools", None)
    if not isinstance(registry, dict):
        return
    guarded = set(publication_control.registered_publication_tool_names())
    # Wave 1yv9l: write-tier extension tools are not registered publishers, so
    # the registry lookup returns no reason for them; they consult the
    # publication checkpoint directly.
    extension_writers = {
        name for name, tier in mcp_tool_extensions.EXTENSION_TOOL_TIERS.items()
        if tier == mcp_tool_extensions.TIER_WRITE
    }
    guarded |= extension_writers
    for name, tool in registry.items():
        if name not in guarded:
            continue
        original = getattr(tool, "fn", None)
        if original is None or getattr(original, "_wf_upgrade_guarded", False):
            continue

        def _make(tool_name: str, fn: Any) -> Any:
            @functools.wraps(fn)
            def guarded_call(*args: Any, **kwargs: Any) -> Any:
                root = get_handler().root
                if tool_name in extension_writers:
                    reason = publication_control.publication_checkpoint_reason(
                        root, tool_name
                    )
                else:
                    reason = publication_control.publication_block_reason(
                        root, tool_name
                    )
                if reason is not None:
                    return _response(
                        "error",
                        {"tool": tool_name, "upgrade_in_progress": True, **({"readiness_receipts": None} if tool_name == "wf_prepare_wave" else {})},
                        diagnostics=[
                            _diagnostic(
                                "upgrade_in_progress",
                                reason.removeprefix("upgrade_in_progress: "),
                                recovery_tools=["wf_upgrade", "wf_upgrade_status"],
                                recovery_usage="wf_upgrade(phase='status')",
                            )
                        ],
                        next_tools=["wf_upgrade", "wf_upgrade_status"],
                    )
                try:
                    return fn(*args, **kwargs)
                except ProjectPublicationUnavailable as exc:
                    return _response(
                        "error",
                        {"tool": tool_name, "publication_applied": False, **({"readiness_receipts": None} if tool_name == "wf_prepare_wave" else {})},
                        diagnostics=[
                            _diagnostic(
                                "project_publication_busy",
                                str(exc),
                            )
                        ],
                        next_tools=["wf_upgrade_status", tool_name],
                    )

            guarded_call._wf_upgrade_guarded = True  # type: ignore[attr-defined]
            return guarded_call

        tool.fn = _make(name, original)


# Wave 1t3ek (1t2zq/1t15a): state files a tool demonstrably reads on the
# caller's behalf — credited through the canonical source-proof machinery
# (once-only per (wave, phase, source, version)). Tools that read nothing for
# the caller (memory_add, the wf_new_* scaffolds) are deliberately absent, as
# are full-content returners whose credit would equal their response debit
# (seed_get, wf_get_prompt). Listings credit only the live working set they
# enumerate, never closed history (see _state_sources_live_waves); memory
# views credit the capped set of record files they surface.


_ARTIFACT_EXTRACTORS: dict[str, Any] = {
    "wf_review_event": _artifact_from_review_evidence,
    "memory_propose": _artifact_from_written_paths("written"),
    "memory_add": _artifact_from_written_paths("record"),
    "memory_validate": _artifact_from_written_paths("rewrite_record"),
    "memory_backfill": _artifact_from_written_paths("written"),
    # Wave 1t72b (1t729): the renderer's changed-file manifest; dry-run and
    # failed runs expose no written list, so they credit nothing.
    "wf_sync_surfaces": _artifact_from_written_paths("written"),
    "wf_techdocs_baseline": _artifact_from_written_paths("written_paths"),
    **{
        name: _artifact_from_written_paths("path")
        for name in (
            "wf_new_feature", "wf_new_bug", "wf_new_enhancement",
            "wf_new_refactor", "wf_new_change", "wf_new_documentation",
            "wf_new_tech_debt", "wf_new_task", "wf_new_maintenance",
            "wf_new_operations",
        )
    },
}

_COST_FOCUS_EXTRACTORS: dict[str, Any] = {
    # Explicitly scoped: a parameter named wave_id is not enough to prove that
    # another tool's response belongs to that wave.
    "wf_review_event": _review_evidence_cost_focus,
}


def _wrap_first_party_tool_costs(mcp: Any, get_handler: Any) -> None:
    """Post-registration pass: wrap uninstrumented first-party tools with a
    debit recorder (plus artifact credit where an extractor exists). Purely
    observational — any failure leaves the tool untouched."""
    try:
        tm = getattr(mcp, "_tool_manager", None)
        tools = getattr(tm, "_tools", None) if tm is not None else None
        if not tools:
            return
        for name, tool in tools.items():
            if name in _COST_EXEMPT_TOOLS:
                continue
            if not any(name.startswith(prefix) for prefix in _served_tool_prefixes()):
                continue
            original = getattr(tool, "fn", None)
            if original is None or getattr(original, "_wf_cost_wrapped", False):
                continue

            def _make(tool_name: str, fn: Any) -> Any:
                @functools.wraps(fn)
                def wrapped(*args: Any, **kwargs: Any) -> Any:
                    result = fn(*args, **kwargs)
                    try:
                        handler = get_handler()
                        if publication_control.publication_checkpoint_reason(
                            handler.root, "context_efficiency"
                        ) is not None:
                            # The requested tool may be read-only and still
                            # serve its response, but its observational cost
                            # wrapper is a project-state writer and must remain
                            # silent during Upgrade.
                            return result
                        request_payload = {
                            k: v for k, v in kwargs.items() if k != "kwargs"
                        }
                        request_json = json.dumps(
                            request_payload, sort_keys=True, default=str
                        )
                        request_tokens = context_efficiency.estimate_tokens_utf8(
                            request_json
                        )
                        response_json = (
                            json.dumps(result, sort_keys=True, default=str)
                            if isinstance(result, (dict, list))
                            else ""
                        )
                        response_tokens = (
                            context_efficiency.estimate_tokens_utf8(response_json)
                            if response_json
                            else 0
                        )
                        artifact_tokens = 0
                        event_id: Optional[str] = None
                        extractor = _ARTIFACT_EXTRACTORS.get(tool_name)
                        if extractor is not None and isinstance(result, Mapping):
                            raw_artifacts, event_id = extractor(handler.root, result)
                            # Credit only what the caller did not supply,
                            # floored at zero PER ARTIFACT (the 1t3s7 contract):
                            # a request larger than every individual artifact
                            # credits nothing even when outputs sum higher.
                            artifact_tokens = sum(
                                max(0, int(raw) - request_tokens)
                                for raw in raw_artifacts
                            )
                            if event_id is None:
                                # Stable replay identity for artifact tools that
                                # carry no operation digest: an identical
                                # request producing an identical response is a
                                # replay and must not credit twice, while a
                                # different outcome (e.g. idempotent second run
                                # writing nothing) still records its debits.
                                event_id = "artifact:" + hashlib.sha256(
                                    (tool_name + "\x00" + request_json
                                     + "\x00" + response_json).encode("utf-8")
                                ).hexdigest()
                        source_proofs = None
                        state_extractor = _STATE_SOURCE_EXTRACTORS.get(tool_name)
                        if state_extractor is not None and isinstance(result, Mapping):
                            # Wave 1t3ek (1t2zq): avoided reading — live proofs
                            # for the state files this call consumed; any
                            # resolution failure credits nothing.
                            proofs = []
                            for rel in state_extractor(handler.root, result):
                                signature = context_efficiency.contained_stat_signature(
                                    handler.root, rel
                                )
                                if signature is not None:
                                    proofs.append(
                                        context_efficiency.SourceProof(
                                            path=rel,
                                            kind="live",
                                            expected=signature,
                                            boundary_stable=True,
                                        )
                                    )
                            source_proofs = proofs or None
                        focus_override = None
                        focus_extractor = _COST_FOCUS_EXTRACTORS.get(tool_name)
                        if focus_extractor is not None and isinstance(result, Mapping):
                            target_focus = focus_extractor(
                                handler.root, request_payload, result
                            )
                            if target_focus is not None:
                                current_focus = handler.telemetry.focus
                                focus_override = (
                                    current_focus
                                    if (
                                        current_focus.wave_id == target_focus.wave_id
                                        and current_focus.stage == target_focus.stage
                                    )
                                    else target_focus
                                )
                        handler.telemetry.record_tool_cost(
                            tool_name,
                            request_tokens=request_tokens,
                            response_tokens=response_tokens,
                            derived_artifact_tokens=artifact_tokens,
                            source_proofs=source_proofs,
                            focus_override=focus_override,
                            event_id=event_id or uuid.uuid4().hex,
                        )
                    except Exception:
                        pass
                    return result

                wrapped._wf_cost_wrapped = True  # type: ignore[attr-defined]
                return wrapped

            tool.fn = _make(name, original)
    except Exception:
        pass


# Registration-time call wrappers, applied innermost first: cost, then the
# lifecycle lock, then the upgrade-publication guard (wave 1y0h1). Each entry
# spells out its wrapper call so a module-level rebinding of the wrapper name
# takes effect when the chain runs; the wrappers themselves stay the only
# place a tool's callable is rebound.
MIDDLEWARE: tuple[tuple[str, Any], ...] = (
    ("cost", lambda mcp, get_handler: _wrap_first_party_tool_costs(mcp, get_handler)),
    ("lock", lambda mcp, get_handler: _wrap_lifecycle_mutation_lock(mcp, get_handler)),
    ("guard", lambda mcp, get_handler: _wrap_upgrade_publication_guard(mcp, get_handler)),
)


def render_graph_communities_markdown(payload, index, gq) -> str:
    """Markdown catalog of graph communities, Evidence/Data marked and last.

    Extracted from the resource so the partition can be tested without
    materialising a full graph and cluster artifact.
    """
    communities = payload.get("communities") or []
    if not communities:
        return "# Graph Communities\n\n*(no communities in cluster artifact)*\n"

    # Wave 1wpie: this catalog is the surface AGENTS.md tells a reader to
    # consult BEFORE code_graph_community, so presenting a machine-result
    # community identically to an architectural one re-creates in the
    # resource exactly the orientation problem the report fixed. Evidence
    # communities stay listed -- requirement 7 makes their ids
    # discoverable here -- but they are marked and ranked after production.
    # The majority rule comes from graph_query so both surfaces agree.
    shares: dict[str, float] = {}
    if gq is not None and index is not None and index.present:
        try:
            shares = {
                str(c.get("community_id") or ""): gq.community_evidence_share(index, c)
                for c in communities
            }
        except Exception:
            shares = {}
    # With no shares there is nothing to classify, so an unreachable
    # threshold keeps every community in the production list rather than
    # silently marking them all as evidence.
    majority = (getattr(gq, "EVIDENCE_COMMUNITY_MAJORITY", 0.5)
                if shares else 1.1)

    def _by_size(rows):
        return sorted(rows, key=lambda c: -int(c.get("node_count") or 0))

    production = _by_size([c for c in communities
                           if shares.get(str(c.get("community_id") or ""), 0.0) <= majority])
    evidence = _by_size([c for c in communities
                         if shares.get(str(c.get("community_id") or ""), 0.0) > majority])

    lines: list[str] = [f"# Graph Communities ({len(communities)} total)\n\n"]
    if evidence:
        lines.append(
            f"{len(production)} architectural, {len(evidence)} Evidence/Data "
            "(machine-result artifacts, listed last and marked).\n\n")

    def _emit(c: dict, *, is_evidence: bool) -> None:
        cid = str(c.get("community_id") or "")
        if not cid:
            return
        label = str(c.get("label") or "?")
        lines.append(f"## {label}\n\n")
        lines.append(f"- **community_id:** `{cid}`\n")
        lines.append(f"- **Nodes:** {int(c.get('node_count') or 0)}\n")
        lines.append(f"- **Boundary nodes:** {int(c.get('boundary_node_count') or 0)}\n")
        node_ids = c.get("node_ids") or []
        if is_evidence:
            lines.append("- **Type:** Evidence/Data (machine-result artifact, "
                         "not an architectural domain)\n")
            lines.append(
                f"- **Evidence share:** {shares.get(cid, 0.0):.0%} of members\n")
            reasons: list[str] = []
            for member in node_ids:
                reasons = index.evidence_reasons(str(member))
                if reasons:
                    break
            if reasons:
                lines.append(f"- **Why:** {'; '.join(reasons)}\n")
        if index is not None and index.present:
            ranked = sorted(
                (
                    (len(index._in.get(nid, [])) + len(index._out.get(nid, [])), nid)
                    for nid in node_ids
                ),
                key=lambda x: -x[0],
            )[:3]
            if ranked:
                lines.append("- **Top members:**\n")
                for deg, nid in ranked:
                    lines.append(f"  - `{nid}` (degree {deg})\n")
        lines.append("\n")

    for c in production:
        _emit(c, is_evidence=False)
    if evidence:
        lines.append("---\n\n## Evidence/Data communities\n\n")
        for c in evidence:
            _emit(c, is_evidence=True)
    return "".join(lines)


# --- Distribution-declared tool extensions (wave 1yv9l) ----------------------
# A downstream distribution declares extension modules in
# ``mcp_tool_extensions``. Each module registers against a staging surface that
# records every attempt; only a fully valid declaration is installed into the
# served table, ahead of the prefix contract, argument normalization and the
# MIDDLEWARE chain, so extension tools get exactly the wrappers core tools get.


class ExtensionLoadError(RuntimeError):
    """A declared extension module cannot be served; nothing is installed."""


_EXTENSION_PROVENANCE: Optional[dict[str, Any]] = None


def _file_sha256(path: Path) -> Optional[str]:
    try:
        return hashlib.sha256(path.read_bytes()).hexdigest()
    except OSError:
        return None


def _extension_declaration_provenance() -> dict[str, Any]:
    declaration_path = Path(mcp_tool_extensions.__file__).resolve()
    return {
        "path": str(declaration_path),
        "sha256": _file_sha256(declaration_path),
        "prefixes": list(mcp_tool_extensions.EXTENSION_TOOL_PREFIXES),
        "tiers": dict(sorted(mcp_tool_extensions.EXTENSION_TOOL_TIERS.items())),
    }


def _reserved_tool_name_collections() -> dict[str, frozenset[str]]:
    """Core collections that change behavior for a tool by its name (wave 1yyoj).

    A new extension tool may not take one of these names: it would silently
    inherit core wrapping, accounting, dispatch or upgrade reconciliation. The
    census test in test_extension_tool_modules classifies module-level
    assignments in scripts/ and wave_lint_lib/ whose literals include a served
    or retired tool name, or that are derived from a classified collection. A
    collection naming only unserved tools, or one inside a function, is outside
    the census; a membership test keeps these collections to served core or
    retired names.
    """
    reserved = {
        "_LIFECYCLE_MUTATION_LOCK_TOOLS": frozenset(_LIFECYCLE_MUTATION_LOCK_TOOLS),
        "_COST_EXEMPT_TOOLS": frozenset(_COST_EXEMPT_TOOLS),
        "_ARTIFACT_EXTRACTORS": frozenset(_ARTIFACT_EXTRACTORS),
        "_COST_FOCUS_EXTRACTORS": frozenset(_COST_FOCUS_EXTRACTORS),
        "_STATE_SOURCE_EXTRACTORS": frozenset(_STATE_SOURCE_EXTRACTORS),
        "publication_control.PUBLICATION_WRITER_REGISTRY": frozenset(
            publication_control.registered_publication_tool_names()
        ),
    }
    try:
        retired = _load_script("render_platform_surfaces")._RENAMED_MCP_TOOLS
    except Exception as exc:
        raise ExtensionLoadError(f"cannot load retired MCP tool names: {exc!r}") from exc
    reserved["_RENAMED_MCP_TOOLS"] = frozenset(retired)
    return reserved


def _extension_staging_surface() -> Any:
    """A throwaway FastMCP whose ``add_tool`` records every attempted name.

    ``FastMCP.tool()`` routes each decorator through ``add_tool``, so attempts
    FastMCP would silently ignore (a duplicate name) are still recorded.
    """
    from mcp.server.fastmcp import FastMCP

    class _RecordingSurface(FastMCP):
        def __init__(self) -> None:
            super().__init__("wavefoundry_extension_staging")
            self.wf_attempts: list[str] = []

        def add_tool(self, fn: Any, name: Optional[str] = None, *args: Any, **kwargs: Any) -> Any:
            self.wf_attempts.append(name or getattr(fn, "__name__", repr(fn)))
            return super().add_tool(fn, name, *args, **kwargs)

    return _RecordingSurface()


def _load_extension_module(module_name: str) -> tuple[Any, Path, str]:
    """Import a declared module from the framework scripts directory only.

    The source is located without executing it, refused unless it is a
    ``.py`` file whose resolved parent is the resolved scripts directory, and
    executed from the exact bytes that are hashed for provenance.
    """
    import importlib.machinery
    import types

    existing = sys.modules.get(module_name)
    if existing is not None and not getattr(existing, "__wf_extension__", False):
        raise ExtensionLoadError(
            f"extension module {module_name!r} collides with a module the server already imported"
        )
    scripts_dir = SCRIPTS_DIR.resolve()
    spec = importlib.machinery.PathFinder.find_spec(module_name, [str(scripts_dir)])
    origin = getattr(spec, "origin", None) if spec is not None else None
    if not origin or not str(origin).endswith(".py"):
        raise ExtensionLoadError(
            f"extension module {module_name!r} has no .py source directly in {scripts_dir}"
        )
    source_path = Path(origin).resolve()
    if source_path.parent != scripts_dir or source_path.stem != module_name:
        raise ExtensionLoadError(
            f"extension module {module_name!r} resolves to {source_path}, outside {scripts_dir}"
        )
    try:
        source = source_path.read_bytes()
    except OSError as exc:
        raise ExtensionLoadError(f"extension module {module_name!r} cannot be read: {exc}") from exc
    module = types.ModuleType(module_name)
    module.__file__ = str(source_path)
    module.__spec__ = importlib.machinery.ModuleSpec(module_name, None, origin=str(source_path))
    module.__wf_extension__ = True
    sys.modules[module_name] = module
    try:
        exec(compile(source, str(source_path), "exec"), module.__dict__)
    except BaseException as exc:
        sys.modules.pop(module_name, None)
        raise ExtensionLoadError(f"extension module {module_name!r} failed to import: {exc!r}") from exc
    return module, source_path, hashlib.sha256(source).hexdigest()


_SCHEMA_ANNOTATION_KEYS = frozenset({"title", "description", "default", "examples"})


def _normalized_parameter_schema(schema: Any, root: Mapping[str, Any], depth: int = 0) -> Any:
    """A parameter's value schema with annotations dropped and local refs resolved."""
    if depth > 20:
        return schema
    if isinstance(schema, list):
        return [_normalized_parameter_schema(item, root, depth + 1) for item in schema]
    if not isinstance(schema, Mapping):
        return schema
    ref = schema.get("$ref")
    if isinstance(ref, str) and ref.startswith("#/$defs/"):
        target = (root.get("$defs") or {}).get(ref[len("#/$defs/"):])
        if target is not None:
            return _normalized_parameter_schema(target, root, depth + 1)
    return {
        key: _normalized_parameter_schema(value, root, depth + 1)
        for key, value in schema.items()
        if key not in _SCHEMA_ANNOTATION_KEYS
    }


def _override_compatibility_problem(name: str, core_tool: Any, staged_tool: Any) -> Optional[str]:
    """Structural call-compatibility on normalized published schemas."""
    core_schema = getattr(core_tool, "parameters", None) or {}
    staged_schema = getattr(staged_tool, "parameters", None) or {}
    if staged_schema.get("additionalProperties") is not False:
        return (
            f"override {name!r} does not reject undeclared arguments; its handler must "
            "accept **kwargs and pass them to _ensure_no_extra_args"
        )
    missing = set(core_schema.get("properties", {})) - set(staged_schema.get("properties", {}))
    if missing:
        return f"override {name!r} drops parameters {sorted(missing)}"
    newly_required = set(staged_schema.get("required", [])) - set(core_schema.get("required", []))
    if newly_required:
        return f"override {name!r} newly requires parameters {sorted(newly_required)}"
    # Every replaced parameter must accept exactly the values the core tool
    # accepts; a type change would break callers that follow the core schema.
    core_props = core_schema.get("properties", {})
    staged_props = staged_schema.get("properties", {})
    changed = sorted(
        param for param in core_props
        if _normalized_parameter_schema(core_props[param], core_schema)
        != _normalized_parameter_schema(staged_props.get(param), staged_schema)
    )
    if changed:
        return f"override {name!r} changes the schema of parameters {changed}"
    return None


def _install_extension_tools(mcp: Any, get_handler: Any) -> dict[str, Any]:
    """Stage, validate and install declared extension tools; return provenance.

    Raises before touching the served table when anything is invalid.
    """
    provenance: dict[str, Any] = {
        "declaration": _extension_declaration_provenance(),
        "modules": [],
    }
    if not mcp_tool_extensions.declared():
        return provenance
    roster = _load_script("mcp_tool_roster")
    runner = set(roster.RUNNER_TOOLS)
    table = mcp._tool_manager._tools
    core_names = set(table) - runner
    mcp_tool_extensions.validate_declaration(core_tools=core_names, runner_tools=runner)
    tiers = dict(mcp_tool_extensions.EXTENSION_TOOL_TIERS)
    prefixes = tuple(mcp_tool_extensions.EXTENSION_TOOL_PREFIXES)
    reserved = _reserved_tool_name_collections()

    staging = _extension_staging_surface()
    staged_by: dict[str, str] = {}
    problems: list[str] = []
    for module_name in mcp_tool_extensions.EXTENSION_MODULES:
        module, source_path, digest = _load_extension_module(module_name)
        register = getattr(module, "register", None)
        if not callable(register):
            raise ExtensionLoadError(f"extension module {module_name!r} defines no register(mcp, get_handler)")
        start = len(staging.wf_attempts)
        served_before = dict(table)
        staged_before = dict(staging._tool_manager._tools)
        resources_before = (
            len(staging._resource_manager._resources) + len(staging._resource_manager._templates)
        )
        prompts_before = len(staging._prompt_manager._prompts)
        try:
            register(staging, get_handler)
        except Exception as exc:
            raise ExtensionLoadError(f"extension module {module_name!r} raised during register: {exc!r}") from exc
        attempts = staging.wf_attempts[start:]
        # The staged table itself is authoritative: anything that reached it
        # without passing FastMCP.add_tool, or that replaced or removed an
        # entry another module staged, is refused rather than installed.
        staged_after = staging._tool_manager._tools
        unrecorded = sorted(set(staged_after) - set(staged_before) - set(attempts))
        if unrecorded:
            problems.append(f"{module_name!r} registers {unrecorded} outside FastMCP.add_tool")
        tampered = sorted(
            name for name, tool in staged_before.items()
            if staged_after.get(name) is not tool
        )
        if tampered:
            problems.append(f"{module_name!r} replaces or removes tools staged by another module: {tampered}")
        withdrawn = sorted(set(attempts) - set(staged_after))
        if withdrawn:
            problems.append(f"{module_name!r} removes tools it registered: {withdrawn}")
        served_changed = sorted(
            name for name in set(served_before) | set(table)
            if served_before.get(name) is not table.get(name)
        )
        if served_changed:
            problems.append(f"{module_name!r} changes the served tool table directly: {served_changed}")
        if (
            len(staging._resource_manager._resources) + len(staging._resource_manager._templates)
            != resources_before
        ):
            problems.append(f"{module_name!r} registers MCP resources; extensions may register tools only")
        if len(staging._prompt_manager._prompts) != prompts_before:
            problems.append(f"{module_name!r} registers MCP prompts; extensions may register tools only")
        declared_overrides = set(mcp_tool_extensions.EXTENSION_OVERRIDES.get(module_name, ()))
        new_tools: list[str] = []
        overrides: list[str] = []
        for name in attempts:
            if name in staged_by:
                problems.append(f"{module_name!r} registers {name!r}, already staged by {staged_by[name]!r}")
                continue
            staged_by[name] = module_name
            if name in core_names or name in runner:
                if name not in declared_overrides:
                    problems.append(f"{module_name!r} registers existing tool {name!r} without declaring an override")
                else:
                    overrides.append(name)
                continue
            if not any(name.startswith(prefix) for prefix in prefixes):
                problems.append(f"{module_name!r} registers {name!r} without a declared extension prefix")
            if name not in tiers:
                problems.append(f"{module_name!r} registers {name!r} without a declared tier")
            for label, reserved_names in reserved.items():
                if name in reserved_names:
                    problems.append(f"{module_name!r} registers {name!r}, a name reserved by core {label}")
            new_tools.append(name)
        for name in sorted(declared_overrides - set(attempts)):
            problems.append(f"{module_name!r} declares override {name!r} but does not register it")
        provenance["modules"].append({
            "module": module_name,
            "path": str(source_path),
            "sha256": digest,
            "tools": [{"name": name, "tier": tiers.get(name)} for name in sorted(new_tools)],
            "overrides": sorted(overrides),
        })
    for name in sorted(set(tiers) - set(staged_by)):
        problems.append(f"declared tier for {name!r} has no registered tool")

    staged_table = staging._tool_manager._tools
    for name, tool in sorted(staged_table.items()):
        # The MIDDLEWARE wrappers are synchronous; an async handler would run
        # after the lock and guard have already returned.
        if getattr(tool, "is_async", False) or inspect.iscoroutinefunction(getattr(tool, "fn", None)):
            problems.append(
                f"{staged_by.get(name, 'an extension module')!r} registers async handler {name!r}; "
                "extension handlers must be synchronous"
            )
    _normalize_first_party_tool_argument_models(staging)
    _normalize_first_party_tool_argument_models(mcp)
    for entry in provenance["modules"]:
        for name in entry["overrides"]:
            if name not in staged_table or name not in table:
                continue  # already refused above (withdrawn or served-table change)
            problem = _override_compatibility_problem(name, table[name], staged_table[name])
            if problem:
                problems.append(problem)
    if problems:
        raise ExtensionLoadError("MCP tool extensions refused: " + "; ".join(problems))

    for name, tool in staged_table.items():
        if name in table:
            mcp.remove_tool(name)
        table[name] = tool
    return provenance


def _strip_to_runner_tools(mcp: Any) -> None:
    """Fail closed: leave only runner tools served (all tools without a roster)."""
    tm = getattr(mcp, "_tool_manager", None)
    tools = getattr(tm, "_tools", None) if tm is not None else None
    if not isinstance(tools, dict):
        return
    try:
        keep = set(_load_script("mcp_tool_roster").RUNNER_TOOLS)
    except Exception:
        keep = set()
    for name in list(tools):
        if name not in keep:
            tools.pop(name, None)


def register_mcp_surface(mcp: Any, get_handler: Any) -> None:
    """Register tools and resources; resolve state via get_handler() for hot reload."""
    # Wave 1p2q3 (131hh): stash the FastMCP instance and register the post-rebuild
    # notification callback against graph_query so auto-rebuilds dispatch
    # `notifications/resources/updated` for the wavefoundry://graph/* URIs.
    global _MCP_INSTANCE, _TOOL_REGISTRY, _EXTENSION_PROVENANCE
    _MCP_INSTANCE = mcp
    try:
        _load_graph_query().set_post_rebuild_callback(_dispatch_graph_resources_updated)
    except Exception:
        pass
    # Tool annotation constants — passed to @mcp.tool(annotations={...}).
    # All handlers also accept **kwargs so FastMCP's auto-generated "kwargs"
    # schema parameter is captured and rejected via _ensure_no_extra_args rather
    # than causing an unexpected-argument error at the Python call boundary.
    _READONLY_TOOL = {"readOnlyHint": True, "destructiveHint": False, "idempotentHint": True, "openWorldHint": False}
    _OBSERVATIONAL_TOOL = {
        "readOnlyHint": False,
        "destructiveHint": False,
        "idempotentHint": False,
        "openWorldHint": False,
    }
    _MUTATING_TOOL = {"readOnlyHint": False, "destructiveHint": False, "idempotentHint": False, "openWorldHint": False}
    _DESTRUCTIVE_TOOL = {"readOnlyHint": False, "destructiveHint": True, "idempotentHint": False, "openWorldHint": False}

    # --- Search and retrieval ---

    @mcp.tool(annotations=_READONLY_TOOL)
    def wf_help(goal: str = "", **kwargs: Any) -> dict[str, Any]:
        """Return a structured MCP workflow catalogue or a goal-specific recommended chain.

        Args:
            goal: Optional workflow goal, e.g. "plan_feature" or "inspect_wave".
        """
        bad = _ensure_no_extra_args("wf_help", kwargs)
        if bad is not None:
            return bad
        return wf_help_response(goal)

    @mcp.tool(annotations=_READONLY_TOOL)
    def wf_server_info(**kwargs: Any) -> dict[str, Any]:
        """Return the repository root and implementation version info for this MCP server.

        Use immediately after connect when you need to confirm which checkout this server is attached to.
        """
        bad = _ensure_no_extra_args("wf_server_info", kwargs)
        if bad is not None:
            return bad
        return wf_server_info_response(get_handler().root)

    @mcp.tool(annotations=_READONLY_TOOL)
    def wf_gpu_doctor(**kwargs: Any) -> dict[str, Any]:
        """Embedding-provider / GPU capability diagnostic — platform, onnxruntime, GPU detection
        (nvidia/apple), available ONNX execution providers, the provider Wavefoundry would select
        (+ reason/remediation + decision provenance: setup-cache / fresh-probe / operator-request),
        and the CUDA 12/13 ABI-gap check. Read-only, no index build; note it RUNS the bounded
        model-loading provider probe (seconds; needs the model cached), the same probe setup uses.
        Same report as the `setup-wavefoundry --check-gpu` CLI.
        """
        bad = _ensure_no_extra_args("wf_gpu_doctor", kwargs)
        if bad is not None:
            return bad
        return wf_gpu_doctor_response(get_handler().root)

    @mcp.tool(annotations=_OBSERVATIONAL_TOOL)
    def docs_search(
        query: str,
        kind: Literal["", "doc", "seed", "architecture", "prompt", "doc-summary", "doc-code"] = "",
        tags: list = [],
        limit: int = 7,
        **kwargs: Any,
    ) -> dict[str, Any]:
        """Semantic search over docs, architecture, prompts, seed chunks, and framework seeds at .wavefoundry/framework/seeds/.

        Prefer when: searching by concept, intent, or natural language across project and framework documentation.
        Use code_keyword instead when the exact text is known.
        Degrades per the 1seaq state table: with a PUBLISHED index (complete build epoch)
        but an unavailable semantic model, serves BM25 results from the FTS layer
        (search_mode: lexical_fallback); with no published index at all, serves the
        live-filesystem walk (search_mode: live_fallback). Every response carries
        search_mode (semantic | lexical_fallback | live_fallback; null on refusal/validation errors) and fallback_reason
        (null when healthy; else model_unavailable | index_missing | store_absent |
        index_not_ready | query_failed — query_failed means infrastructure failure,
        NOT an empty corpus).

        Tags pre-filter the search space before cosine ranking. Use to scope results to a specific doc category.
        Tag vocabulary: wave, agent, lifecycle, reference, journal, prompt, seed, framework, test, config.
        Multiple tags use OR semantics (a chunk matching any requested tag is included).
        kind and tags compose with AND semantics (a chunk must satisfy both when both are provided).
        Examples: tags=["wave"] for wave records, tags=["agent"] for agent prompts and journals,
                  tags=["lifecycle"] for install/onboarding docs, tags=["journal"] for agent journals only.

        Args:
            query: Natural language search query.
            kind: Optional filter — one of: doc, seed, architecture, prompt, doc-summary,
                doc-code (fenced code / directive bodies extracted from documentation files;
                not matched by the architecture virtual kind).
            tags: Optional list of classification tags to pre-filter results. See tag vocabulary above.
            limit: Maximum results to return (1–20, default 7).
        """
        bad = _ensure_no_extra_args("docs_search", kwargs)
        if bad is not None:
            if isinstance(bad.get("data"), dict):  # search contract: fields always present
                bad["data"].setdefault("search_mode", None)
                bad["data"].setdefault("fallback_reason", None)
            return bad
        # 1sed6 seqlock read: capture the complete epoch token before the
        # whole operation; discard results if it changed underneath. A None
        # pre-token is allowed here — docs_search's live-filesystem fallback
        # is the explicitly degraded path for a not-ready index.
        import sqlite_runtime as runtime
        try:
            _tok = _epoch_state(get_handler().root, propagate_runtime_errors=True)
            # The CAPTURED token drives the fallback serve decisions inside the
            # response fn (1seaq single-capture discipline — no second read).
            result = docs_search_response(get_handler().index, query, kind, limit=limit, tags=tags or None, epoch_state=_tok)
            # Review fix (ABA-hardened): the post-compare is UNCONDITIONAL and
            # uses the FULL state row. A stable pair (same attempt/status/
            # generation — including a stable not-ready store) is the sanctioned
            # degraded live-walk; ANY transition — publish mid-operation, or
            # building A → complete → building B (invisible to the complete-only
            # token, both endpoints None) — discards the results.
            if _epoch_state(get_handler().root, propagate_runtime_errors=True) != _tok:
                return _index_rebuilding_response("docs_search", {"query": query})
            return _record_retrieval_context(
                get_handler(),
                "docs_search",
                result,
                indexed_epoch_stable=bool(_tok and _tok[1] == "complete"),
                request_arguments={
                    "query": query,
                    "kind": kind,
                    "tags": tags,
                    "limit": limit,
                },
            )
        except (runtime.RuntimeUnavailable, runtime.StorageRecoveryRequired) as exc:
            return _index_runtime_failure_response(
                'docs_search', get_handler().root, {'query': query}, exc)

    @mcp.tool(annotations=_OBSERVATIONAL_TOOL)
    def code_search(query: str, language: str = "", kind: str = "", max_per_file: int = 0, tags: list = [], limit: int = 7, graph: bool = True, graph_limit: int = 5, layer: str = "project", **kwargs: Any) -> dict[str, Any]:
        """Semantic search over indexed source code chunks. Requires a built code index (index_build content='code').

        Prefer when: searching for code by concept, behavior, or intent (e.g. "React component with loading state").
        Use code_keyword instead when the exact token, symbol, or string is known — always available, deterministic.
        Use docs_search instead when the answer is in a spec, architecture doc, or prompt rather than source code.
        When the code index is absent: returns status='error' with a diagnostic — does not crash.
        Degrades per the 1seaq state table: with a PUBLISHED index (complete build epoch) but an
        unavailable semantic model, serves BM25 results from the FTS layer with the requested
        filters preserved (search_mode: lexical_fallback, exact-token recall). With no published
        index there is NO degraded path — the tool refuses (index_not_ready). Every response
        carries search_mode (hybrid | lexical_fallback; null on refusal/validation errors) and fallback_reason (null when healthy;
        else model_unavailable | index_missing | store_absent | index_not_ready | query_failed).

        Orientation pass (Guru): use kind="code-summary" with max_per_file=1 for a fast file-level survey before targeted retrieval.

        Tags pre-filter the search space before cosine ranking. Use to scope results to a specific file category.
        Tag vocabulary: test, config, framework, seed. Multiple tags use OR semantics.
        language, kind, and tags all compose with AND semantics when provided together.
        Example: tags=["test"] to scope to test files only, tags=["config"] for config/infra files.

        Choosing a language filter:
        - No filter: query spans the whole codebase. Best when you don't know which language has the answer.
        - Category: use when the answer could be in any language of a family, or the codebase mixes them.
          Categories: java (java/kotlin/scala/groovy), web (typescript/javascript/html/css/scss),
          systems (c/cpp/rust/go), script (python/ruby/shell/fish), data (sql), sparksql (sql alias), dotnet (csharp).
          Category responses include language_resolved (expanded language list) and language_extensions.
        - Canonical name or extension: use when you know the exact language. e.g. "python", "typescript", "tsx", ".tsx".
          Note: .tsx and .ts files are both indexed as language="typescript" — tsx/.tsx normalizes to typescript.
          Use "web" (category) if you want TypeScript + JavaScript + HTML + CSS + SCSS together.

        Candidate generation (wave 1wpif): language (single name, extension, or category), kind, and tags
        are pushed into BOTH candidate sources (the SQLite vector WHERE clause and the FTS5 WHERE) before the
        bounded top-k, so a selected-language match is never lost past a global window; the language
        value resolves through a fixed allowlist and never enters a predicate verbatim. max_per_file
        cannot be pushed down: retrieval continues over bounded candidate windows 30 -> 60 -> 120 -> 240
        per source (at most 4 queries / 240 examined rows per source per call) until `limit` capped rows
        exist. Every response carries `retrieval_accounting` (per-source queries and examined rows plus
        the stated ceiling: 8 queries / 480 rows over code_dense + code_lexical) and, when a per-file cap
        ran, `fill` with `reason` null (filled), `substrate_exhausted` (fewer eligible rows exist), or
        `bounded_ceiling_reached` (the ceiling exited first; a diagnostic of the same code is attached,
        eligible rows may remain). The cross-encoder reranks at most max(4 * limit, 30) candidates,
        unchanged by refill; the lexical fallback applies the same pushdown and refill contract.
        When the lexical layer is damaged, the healthy semantic results are still returned and a
        `lexical_undercoverage` diagnostic names the damaged tables (wave 1wpif, `1wpag`).

        Args:
            query: Natural language description of the code behavior or concept to find.
            language: Optional — category name, canonical language name, or raw extension (with or without dot).
            kind: Optional — filter to a specific chunk kind. Use "code-summary" for file-level orientation chunks only.
            max_per_file: Optional — cap results per file path (0 = no cap). Use 1 for orientation pass diversity.
            tags: Optional list of classification tags to pre-filter results. See tag vocabulary above.
            limit: Maximum results to return (1–20, default 7).
            graph: When True (default), append 1-hop ``graph_neighbors`` for top hits. Pass ``graph=False`` to suppress augmentation when you need the lean response.
            graph_limit: Number of top hits to expand when ``graph=True`` (default 5). Use 0 for no cap.
            layer: Graph layer for ``graph=True`` (default ``project``).

        Response fields:
        - graph_neighbors: (present unless ``graph=False``) 1-hop structural neighbors of the top-ranked hits, sourced from the graph index — file-level imports and symbol-level call relations.
        """
        bad = _ensure_no_extra_args("code_search", kwargs)
        if bad is not None:
            if isinstance(bad.get("data"), dict):  # search contract: fields always present
                bad["data"].setdefault("search_mode", None)
                bad["data"].setdefault("fallback_reason", None)
            return bad
        t_start = time.monotonic()
        # 1sed6 seqlock read (review-hardened): strict pre-gate — indexed code
        # search has NO sanctioned degraded path, so a missing complete epoch
        # refuses up front (deterministic, and immune to a mid-operation
        # publication racing the index load) — plus an unconditional
        # post-compare.
        # ONE state-token capture (review fix: a separate complete-probe +
        # state-capture pair left a between-reads window where a writer could
        # fence and the unchanged building==building post-check passed). The
        # completeness gate checks the CAPTURED token's own status.
        import sqlite_runtime as runtime
        try:
            _tok = _epoch_state(get_handler().root, propagate_runtime_errors=True)
            if _tok is None or _tok[1] != "complete":
                return _index_rebuilding_response("code_search", {"query": query})
            result = code_search_response(get_handler().index, query, language, limit=limit, kind=kind or None, max_per_file=max_per_file or None, tags=tags or None, epoch_state=_tok)
            result = _augment_with_graph_neighbors_if_enabled(
                result, get_handler().root,
                tool_key="code_search", graph=graph, graph_limit=graph_limit, layer=layer,
            )
            # Review fix (P0): the post-compare closes the fence AFTER graph
            # augmentation — the graph read is part of the indexed operation, so
            # a build fencing during augmentation must discard the WHOLE result,
            # not just the pre-augmentation half.
            if _epoch_state(get_handler().root, propagate_runtime_errors=True) != _tok:
                return _index_rebuilding_response("code_search", {"query": query})
            return _record_retrieval_context(
                get_handler(),
                "code_search",
                _inject_timing(result, t_start, "code_search"),
                indexed_epoch_stable=True,
                request_arguments={
                    "query": query,
                    "language": language,
                    "kind": kind,
                    "max_per_file": max_per_file,
                    "tags": tags,
                    "limit": limit,
                    "graph": graph,
                    "graph_limit": graph_limit,
                    "layer": layer,
                },
            )
        except (runtime.RuntimeUnavailable, runtime.StorageRecoveryRequired) as exc:
            return _index_runtime_failure_response(
                'code_search', get_handler().root, {'query': query}, exc)

    @mcp.tool(annotations=_READONLY_TOOL)
    def seed_get(name: str, **kwargs: Any) -> dict[str, Any]:
        """Retrieve a framework seed prompt by name or partial slug.

        Prefer when: you know the seed name or number. Use docs_search instead when searching for seed content by concept.

        Args:
            name: Seed name or partial slug, e.g. "plan-feature" or "020-run-contract".
        """
        bad = _ensure_no_extra_args("seed_get", kwargs)
        if bad is not None:
            if isinstance(bad.get("data"), dict):  # search contract: fields always present
                bad["data"].setdefault("search_mode", None)
                bad["data"].setdefault("fallback_reason", None)
            return bad
        # 1sed6 seqlock read (review fix): seed_get reads indexed chunks (with
        # a sanctioned disk fallback), so it takes the same whole-operation
        # fence as docs_search — unconditional post-compare, None pre allowed.
        import sqlite_runtime as runtime
        try:
            _tok = _epoch_state(get_handler().root, propagate_runtime_errors=True)
            result = seed_get_response(get_handler().index, name)
            if _epoch_state(get_handler().root, propagate_runtime_errors=True) != _tok:
                return _index_rebuilding_response("seed_get", {"name": name})
            return result
        except (runtime.RuntimeUnavailable, runtime.StorageRecoveryRequired) as exc:
            return _index_runtime_failure_response(
                'seed_get', get_handler().root, {'name': name}, exc)

